  ui_story_5020_50200101_142_dialog_content = "도망쳐!",
  ui_story_5020_50200101_143_dialog_content = "살려줘──!",
  ui_story_5020_50200101_144_dialog_content = "?!",
  ui_story_5020_50200101_145_dialog_content = "PlayerName, 싸울 준비해!",
  ui_story_5020_50200202_1_dialog_content = "<anim type=Shake>그어어어!</anim>",
  ui_story_5020_50200202_2_dialog_content = "으악! 오, 오지 마!",
  ui_story_5020_50200202_3_dialog_content = "<color=#e8d9bb>스륵──</color>",
  ui_story_5020_50200202_4_dialog_content = "다친 곳은 없는가.",
  ui_story_5020_50200202_5_dialog_content = "으으... 난 괜찮아... 고마워, 누나.",
  ui_story_5020_50200202_6_dialog_content = "<anim type=Shake>그어억...</anim>",
  ui_story_5020_50200202_7_dialog_content = "쳇, 끝이 없군.",
  ui_story_5020_50200202_8_dialog_content = "누나, 우리 이제 어떡해?",
  ui_story_5020_50200202_9_dialog_content = "넌 저쪽으로 도망쳐라. 그리고 절대 뒤돌아보지 마라.",
  ui_story_5020_50200202_10_dialog_content = "<anim type=Shake>구어어──</anim>",
  ui_story_5020_50200202_11_dialog_content = "PlayerName, 뭐 하는 거야?",
  ui_story_5020_50200202_12_dialog_content = "아까부터 너 좀 이상해. 뭐라고 혼자 중얼거리고.",
  ui_story_5020_50200202_13_dialog_content = "바닥에 복콩 주머니가 잔뜩 떨어져 있길래 주워서 잔뜩 던졌어.",
  ui_story_5020_50200202_14_dialog_content = "콩 던지면서 소리도 질렀다고.",
  ui_story_5020_50200202_15_option_content = "귀신은 물러가고! 복은 들어와라!",
  ui_story_5020_50200202_16_dialog_content = "<color=#e8d9bb>후두둑──</color>",
  ui_story_5020_50200202_17_option_content = "귀신은 물러가고! 복은 들어와라!",
  ui_story_5020_50200202_18_dialog_content = "<color=#e8d9bb>후두둑──</color>",
  ui_story_5020_50200202_19_option_content = "기이능 무어가고! 보근 드어아아!",
  ui_story_5020_50200202_20_dialog_content = "쓰으읍... 소리를 너무 질러서 혀를 깨물었어.",
  ui_story_5020_50200202_21_dialog_content = "그래서 효과가 있었어?",
  ui_story_5020_50200202_22_dialog_content = "음... 보다시피 역시 너희 전투력을 믿는 게 더 나은 것 같아.",
  ui_story_5020_50200202_23_dialog_content = "<size=45>으아아악!</size>",
  ui_story_5020_50200202_24_dialog_content = "이쪽으로 오면 안 됩니다! 모두 뒤로 물러나십시오!",
  ui_story_5020_50200202_25_dialog_content = "속사 감지!",
  ui_story_5020_50200202_26_dialog_content = "왜 오니가 사카이 거리에 나타난 거지?! 쇼군의 수비병들은 뭘 하고 있는 거야?",
  ui_story_5020_50200202_27_dialog_content = "설마 다들 성문을 지키러 간 건 아니겠지?",
  ui_story_5020_50200202_28_dialog_content = "그럴 리가... 우릴 막는 게 이것보다 중요하단 거야?",
  ui_story_5020_50200202_29_dialog_content = "이곳은 위험합니다. 어떻게든 먼저 평민들을 대피시킵시다.",
  ui_story_5020_50200202_30_dialog_content = "PlayerName 님, 평민들을 데리고 후방으로 물러나 주십시오.",
  ui_story_5020_50200202_31_dialog_content = "다들 따라오세요! 이쪽으로!",
  ui_story_5020_50200202_32_dialog_content = "앗, 저건... 무녀잖아?",
  ui_story_5020_50200202_33_dialog_content = "그리고 낯선 이방인들도 있어.",
  ui_story_5020_50200202_34_dialog_content = "따라가도 괜찮은 건가?",
  ui_story_5020_50200202_35_dialog_content = "어떡하지... 다들 우릴 안 믿는 것 같아.",
  ui_story_5020_50200202_36_dialog_content = "생사가 달렸는데 대체 뭘 망설이고 있는 거야?",
  ui_story_5020_50200202_37_dialog_content = "<size=45>으악! 오니가 왜 이렇게 많은 건데?!</size>",
  ui_story_5020_50200202_38_dialog_content = "어라? PlayerName 씨, 아직도 도망 안 갔어?",
  ui_story_5020_50200202_39_dialog_content = "철수! 철수! 포장마차도 뒤집히게 생겼다구!",
  ui_story_5020_50200202_40_dialog_content = "잠깐만, 아직 가지 마!",
  ui_story_5020_50200202_41_dialog_content = "모모, 안즈, 지금 너희 도움이 필요해.",
  ui_story_5020_50200202_42_dialog_content = "PlayerName 씨... 볼일이 있으면 나중에 말해줘!",
  ui_story_5020_50200202_43_dialog_content = "그래! 지금은 도망치는 게 먼저라구!",
  ui_story_5020_50200202_44_dialog_content = "일단 진정해!",
  ui_story_5020_50200202_45_dialog_content = "너희, 가게의 평판을 더 높이고 싶지 않아?",
  ui_story_5020_50200202_46_dialog_content = "<size=45>응!</size>",
  ui_story_5020_50200202_47_dialog_content = "운도에서 가장 우수한 맛집의 주인이 되고 싶지 않아?",
  ui_story_5020_50200202_48_dialog_content = "<size=45>물론이지!</size>",
  ui_story_5020_50200202_49_dialog_content = "그럼 너희가... 크흠, 평소에 잘하던 호객 솜씨로 사람들을 안전한 곳까지 대피시켜 줘.",
  ui_story_5020_50200202_50_dialog_content = "<anim type=Shake><size=50>좋아! 다들 따라와! 이쪽으로!</size></anim>",
  ui_story_5020_50200202_51_dialog_content = "으악, 내 귀야...",
  ui_story_5020_50200301_1_dialog_content = "합하, 평소 왕래하던 상인들이 지금 알현을 청하고 있습니다.",
  ui_story_5020_50200301_2_dialog_content = "오늘은 연등 야행으로 큰돈을 벌 대목이거늘, 어찌 나를 찾아왔단 말이더냐.",
  ui_story_5020_50200301_3_dialog_content = "좋다. 가서 만나보도록 하지.",
  ui_story_5020_50200301_4_dialog_content = "합하! 제발 살려주십시오!",
  ui_story_5020_50200301_5_dialog_content = "예는 거두고 고개를 들라. 대체 무슨 일인가.",
  ui_story_5020_50200301_6_dialog_content = "아이고, 모르셨습니까? 방금 사카이 거리가 오니의 습격을 받았습니다...",
  ui_story_5020_50200301_7_dialog_content = "그렇습니다요!",
  ui_story_5020_50200301_8_dialog_content = "저희들 가게도 전부 망가져서 큰 손실을 입었습니다...",
  ui_story_5020_50200301_9_dialog_content = "이러다간 올해 춘일제도 또 헛고생이 되고 말 겁니다요...",
  ui_story_5020_50200301_10_dialog_content = "크흠, 다들 조용히 하게. 지금 그런 말을 할 때인가!",
  ui_story_5020_50200301_11_dialog_content = "합하, 저희는 사카이 거리에 변고가 발생하였기에 즉시 보고를 드리고자 온 것입니다...",
  ui_story_5020_50200301_12_dialog_content = "그것이 사실이냐.",
  ui_story_5020_50200301_13_dialog_content = "소신의 실책입니다. 호위대는 지금 모두 성문에...",
  ui_story_5020_50200301_14_dialog_content = "즉시 호위대를 파견해라!",
  ui_story_5020_50200301_15_dialog_content = "혹여 백성들에게 무슨 변고라도 생긴다면 그대들도 무사치 못할 것이다.",
  ui_story_5020_50200301_16_dialog_content = "예!",
  ui_story_5020_50200301_17_dialog_content = "합하, 정말 감사합니다!",
  ui_story_5020_50200301_18_dialog_content = "수하의 실수는 내 과실이니, 유감을 표하지 않을 수 없구나.",
  ui_story_5020_50200301_19_dialog_content = "천만의 말씀입니다!",
  ui_story_5020_50200301_20_dialog_content = "조금 전 린네 님이 성안에서 백성들을 대피시키고 있는 것을 보았습니다.",
  ui_story_5020_50200301_21_dialog_content = "뭐라, 린네가 성안에 있었단 말이더냐?",
  ui_story_5020_50200301_22_dialog_content = "그렇습니다. 린네 님은 연등 야행 준비를 하고 계셨던 모양입니다.\n그래서 즉시 저희를 보호해 주셨습니다.",
  ui_story_5020_50200301_23_dialog_content = "그 당당한 모습에 소인은 실로 감격했습니다.",
  ui_story_5020_50200301_24_dialog_content = "그래서 저희도 뭔가 해야겠다고 생각한 것입니다.",
  ui_story_5020_50200301_25_dialog_content = "아마 린네 님께서 아직 합하께 상황을 고하지 않았으리라 여겨,\n이렇게 알현을 청하여 아뢰게 되었습니다.",
  ui_story_5020_50200301_26_dialog_content = "훌륭하다.",
  ui_story_5020_50200301_27_dialog_content = "이번 일은 반란군이 오니를 거리로 유인한 것이 자명하다.\n백성들의 목숨도 돌보지 않고 그 틈을 타 반란을 일으킬 심산이렷다.",
  ui_story_5020_50200301_28_dialog_content = "허나 두려워할 필요는 없느니라. 호위대가 이미 출발했으니, 모두의 안전을 보장할 것이다.",
  ui_story_5020_50200301_29_dialog_content = "합하께서는 실로 운도의 천복이십니다!",
  ui_story_5020_50200301_30_dialog_content = "하오면 소인들은 이만 물러가겠습니다.",
  ui_story_5020_50200301_31_dialog_content = "운도의 백성들은 무엇이 평화인지 모른다. 저들은 그저 받는 것밖에 모르는 자들이지.",
  ui_story_5020_50200301_32_dialog_content = "「그녀」의 염원을 이루기 위해서는 반드시 희생을 치를 수밖에 없다.",
  ui_story_5020_50200301_33_dialog_content = "허나 아직도 <color=#FFB400>촉유군</color>의 거동이 보이지 않는 것은 의외로구나.",
  ui_story_5020_50200301_34_dialog_content = "<color=#FFB400>나기</color>는 찾았느냐.",
  ui_story_5020_50200301_35_dialog_content = "아직입니다...",
  ui_story_5020_50200301_36_dialog_content = "<size=45>쓸모없는 놈들!</size>",
  ui_story_5020_50200301_37_dialog_content = "송구하옵니다, 합하...",
  ui_story_5020_50200301_38_dialog_content = "오니 부대를 이끌고 사카이 거리로 가서 놈들을 유인해라.",
  ui_story_5020_50200301_39_dialog_content = "오늘 밤 반드시 놈들의 뿌리를 뽑을 것이다.",
  ui_story_5020_50200301_40_dialog_content = "춘일제 또한 반드시 평소대로 거행해야 한다.",
  ui_story_5020_50200301_41_dialog_content = "예.",
  ui_story_5020_50200301_42_dialog_content = "린네는 때로는 실로 그대를 닮았구려.",
  ui_story_5020_50200301_43_dialog_content = "그대가 있었더라면, 아마 그대도 린네가 마음에 들었을 테지.",
  ui_story_5020_50200301_44_dialog_content = "그대가 떠난 후로 나는 내 희망을 새로운 무녀를 길러내는 데에 모두 걸었다.",
  ui_story_5020_50200301_45_dialog_content = "허나 이제 와서 보니 의문의 여지 없는 실패로 끝났구려.",
  ui_story_5020_50200301_46_dialog_content = "그대는 역시 그 누구와도 다른 존재였던 게요.",
  ui_story_5020_50200301_47_dialog_content = "그래도 안심하게. 약속은 꼭 지킬 터이니.",
  ui_story_5020_50200301_48_dialog_content = "이는 그대의 비원이자, 내 숙원이니 말이야.",
  ui_story_5020_50200301_49_dialog_content = "<anim type=Shake><size=45>그어어──!</size></anim>",
  ui_story_5020_50200301_50_dialog_content = "수가 너무 많아!",
  ui_story_5020_50200301_51_dialog_content = "후지쿠모 쇼군은... 정말로 백성들을 죽게 내버려 둘 작정인가?",
  ui_story_5020_50200301_52_dialog_content = "속사 감지!",
  ui_story_5020_50200301_53_dialog_content = "이번 오니들은 왠지 아까보다 더 강한 것 같아...",
  ui_story_5020_50200301_54_dialog_content = "집중해야 돼. 지금 중요한 건 사람들을 대피시키는 거야.",
  ui_story_5020_50200301_55_dialog_content = "린네, 바이스, 조금 더 버텨줘!",
  ui_story_5020_50200302_1_dialog_content = "모모랑 안즈 쪽은 어떻게 됐을까...",
  ui_story_5020_50200302_2_dialog_content = "<size=33>PlayerName 씨!</size>",
  ui_story_5020_50200302_3_dialog_content = "...누가 방금 나 부르지 않았어?",
  ui_story_5020_50200302_4_dialog_content = "응? 난 못 들었는데?",
  ui_story_5020_50200302_5_dialog_content = "PlayerName 씨!",
  ui_story_5020_50200302_6_dialog_content = "앗, 방금 들린 것 같아.",
  ui_story_5020_50200302_7_dialog_content = "저쪽에서 달려오는 사람이 보이는군요.",
  ui_story_5020_50200302_8_dialog_content = "<size=50>PlayerName 씨이이!</size>",
  ui_story_5020_50200302_9_option_content = "모모?!",
  ui_story_5020_50200302_10_dialog_content = "안즈랑 같이 사람들 데리고 대피한 거 아니었어?",
  ui_story_5020_50200302_11_option_content = "안즈?!",
  ui_story_5020_50200302_12_dialog_content = "모모랑 같이 사람들 데리고 대피한 거 아니었어?",
  ui_story_5020_50200302_13_dialog_content = "PlayerName 씨, 난 모모야!",
  ui_story_5020_50200302_14_dialog_content = "아... 미안... 둘이 너무 닮아서 말이지...",
  ui_story_5020_50200302_15_dialog_content = "어찌 돌아온 것인지요. 안즈와 평민들은 어디로 간 것입니까?",
  ui_story_5020_50200302_16_dialog_content = "난 여기 있어!",
  ui_story_5020_50200302_17_dialog_content = "뭐야, 왜 사람들을 도로 데리고 왔어?!",
  ui_story_5020_50200302_18_dialog_content = "어쩔 수 없었어! 다들 뒤만 막고 있었는데, 지금 앞쪽에도 오니가 있단 말이야!",
  ui_story_5020_50200302_19_dialog_content = "우린 포위됐다구!",
  ui_story_5020_50200302_20_dialog_content = "「이렇게 된 이상 길을 베어 나갈 뿐!」",
  ui_story_5020_50200302_21_dialog_content = "...그거 왠지 어디서 들어본 말 같은데요?",
  ui_story_5020_50200302_22_dialog_content = "그렇습니까?",
  ui_story_5020_50200302_23_dialog_content = "전에 요우의 「운도 여행 가이드북」을 본 적이 있습니다.",
  ui_story_5020_50200302_24_dialog_content = "방금 그것은 책에 쓰여 있던 「계절 복장」 선전 문구입니다.",
  ui_story_5020_50200302_25_dialog_content = "린네, 그 말은 솔직히 너한테는 별로 안 어울려...",
  ui_story_5020_50200302_26_dialog_content = "뭐 어때서? 난 되게 멋있는 것 같은데!",
  ui_story_5020_50200302_27_dialog_content = "그 말 난 왠지...",
  ui_story_5020_50200302_28_dialog_content = "사메야마가 운도 무사 옷을 입고 날뛰는 모습이 떠오른단 말이지...",
  ui_story_5020_50200302_29_dialog_content = "음... 뭔가 그런 느낌도 있긴 하네...",
  ui_story_5020_50200302_30_dialog_content = "좋아, 그럼 우리도 길을 베어 나가자!",
  ui_story_5020_50200302_31_dialog_content = "형제들이여, 가자!",
  ui_story_5020_50200302_32_dialog_content = "돌격──!",
  ui_story_5020_50200302_33_dialog_content = "뭐, 뭐야?!",
  ui_story_5020_50200302_34_dialog_content = "후지쿠모 쇼군이 그래도 양심은 있어서 지원군을 보냈나?",
  ui_story_5020_50200302_35_dialog_content = "복장은 오히려 평민 같은데...",
  ui_story_5020_50200302_36_dialog_content = "저들은 반란군입니다.",
  ui_story_5020_50200302_37_dialog_content = "우리는 <color=#FFB400>촉유군</color>이다!",
  ui_story_5020_50200302_38_dialog_content = "너희는 누구냐?",
  ui_story_5020_50200302_39_dialog_content = "우린...",
  ui_story_5020_50200302_40_dialog_content = "무녀와 두 이방인인가.",
  ui_story_5020_50200302_41_dialog_content = "저들을 잡아라!",
  ui_story_5020_50200401_1_dialog_content = "<anim type=Shake>에엣취──</anim>",
  ui_story_5020_50200401_2_dialog_content = "흥... 어떤 녀석이 이 대협객님을 욕한 거야?!",
  ui_story_5020_50200401_3_dialog_content = "계속 쭈그려 앉아 있었더니 다리가 저리네... 지금 나가면 밖에 아무도 없겠지?",
  ui_story_5020_50200401_4_dialog_content = "헤헤, 몸을 좀 풀어주니까 훨씬 좋아졌어!",
  ui_story_5020_50200401_5_dialog_content = "<anim type=Shake>그어어──</anim>",
  ui_story_5020_50200401_6_dialog_content = "뭐야, 성안에 왜 오니가 있어?!",
  ui_story_5020_50200401_7_dialog_content = "<size=45>하앗──!</size>",
  ui_story_5020_50200401_8_dialog_content = "설마 그 노인네, 자기가 사는 성 하나도 제대로 못 지키는 거야? 아니지?",
  ui_story_5020_50200401_9_dialog_content = "칫, 벌써 머리카락이 흐트러졌잖아. 만두머리 묶는 게 얼마나 힘든 건데!",
  ui_story_5020_50200401_10_dialog_content = "그나저나... 여긴 대체 어디야?",
  ui_story_5020_50200401_11_dialog_content = "성이 너무 크잖아! 거기다 어느 층이나 똑같이 생긴 것 같단 말이지.",
  ui_story_5020_50200401_12_dialog_content = "그러고 보니까 이 복도... 왠지 아까 지나간 느낌인데?",
  ui_story_5020_50200401_13_dialog_content = "안 되겠어. 뭔가 표시를 남겨야겠어.",
  ui_story_5020_50200401_14_dialog_content = "휴, 이 녀석은 뭘 잘 먹었길래 이렇게 무거워?",
  ui_story_5020_50200401_15_dialog_content = "자세는 이렇게 하고... 손은 이렇게... 손가락은 저쪽으로...",
  ui_story_5020_50200401_16_dialog_content = "휴~ 이러면 다시 봤을 때 방향을 알 수 있겠지?",
  ui_story_5020_50200401_17_dialog_content = "으... 냄새.",
  ui_story_5020_50200401_18_dialog_content = "대체 출구는 어디야?! 이제 오니는 건들기도 싫단 말이야...",
  ui_story_5020_50200401_19_dialog_content = "으으, 재수 없어! 돌아가면 목욕을 열 번은 해야겠어!",
  ui_story_5020_50200401_20_dialog_content = "<color=#e8d9bb>퉁──</color>",
  ui_story_5020_50200401_21_dialog_content = "<color=#e8d9bb>퉁, 퉁──</color>",
  ui_story_5020_50200401_22_dialog_content = "이런... 저거 린네가 말했던 유시 북소리 아냐?",
  ui_story_5020_50200401_23_dialog_content = "세상에! 내가 여기서 그렇게 오래 헤매고 있었단 말이야?",
  ui_story_5020_50200401_24_dialog_content = "안 돼... 똑똑한 요우야... 머리를 좀 써 봐!",
  ui_story_5020_50200401_25_dialog_content = "음... 직감을 믿으라고 PlayerName도 말했으니까...",
  ui_story_5020_50200401_26_dialog_content = "내 직감으로는... 이쪽인가...",
  ui_story_5020_50200401_27_dialog_content = "직감... 직감... 왼쪽...",
  ui_story_5020_50200401_28_dialog_content = "아아, 신이시여, 이 앞은 제발 안 가본 길이기를...",
  ui_story_5020_50200401_29_dialog_content = "......",
  ui_story_5020_50200401_30_dialog_content = "PlayerName 이 거짓말쟁이! 직감 따윈 아무 쓸모도 없잖아!",
  ui_story_5020_50200401_31_dialog_content = "됐어...",
  ui_story_5020_50200401_32_dialog_content = "차라리 큰맘 먹고 그 스승님이라는 사람처럼 「운수각」에서 뛰어내려야겠어.",
  ui_story_5020_50200401_33_dialog_content = "좋아, 그렇게 하자!",
  ui_story_5020_50200401_34_dialog_content = "음, 이렇게 보니까...",
  ui_story_5020_50200401_35_dialog_content = "그렇게 높지도 않네.",
  ui_story_5020_50200401_36_dialog_content = "스승님은 아마 저 벚나무를 밟고 내려갔겠지?",
  ui_story_5020_50200401_37_dialog_content = "벚나무야, 부탁해! 날 받아줘!",
  ui_story_5020_50200401_38_dialog_content = "......",
  ui_story_5020_50200401_39_dialog_content = "아, 안 되겠어...!",
  ui_story_5020_50200401_40_dialog_content = "역시 스승님은 대단하구나... 난 못 하겠어!",
  ui_story_5020_50200401_41_dialog_content = "너무 높잖아! 히잉...",
  ui_story_5020_50200401_41X1_dialog_content = "영웅이라면 자신 없는 일에는 함부로 뛰어들어선 안 돼!",
  ui_story_5020_50200401_41X2_dialog_content = "어, 어디 타고 내려갈 수 있는 밧줄 같은 게 없나 찾아 봐야겠어...",
  ui_story_5020_50200401_41X3_dialog_content = "으음... 이 방에서 뭔가 숨겨뒀을 만한 유일한 장소라면 역시...",
  ui_story_5020_50200401_41X4_dialog_content = "이 벽장!",
  ui_story_5020_50200401_41X5_dialog_content = "어라?",
  ui_story_5020_50200401_41X6_dialog_content = "이상해... 방금 그 느낌...",
  ui_story_5020_50200401_41X7_dialog_content = "뭔가 알 수 없는 <color=#FFB400>익숙한</color> 느낌이...",
  ui_story_5020_50200401_41X8_dialog_content = "됐어! 신경 끄고 얼른 밧줄이나 찾아보자!",
  ui_story_5020_50200401_42_dialog_content = "<color=#e8d9bb>딸랑──</color>",
  ui_story_5020_50200401_43_dialog_content = "<color=#e8d9bb>딸랑────, 딸랑────</color>",
  ui_story_5020_50200401_44_dialog_content = "어?!",
  ui_story_5020_50200401_45_dialog_content = "...신악의 방울 소리?",
  ui_story_5020_50200401_46_dialog_content = "<color=#e8d9bb>딸랑── 딸랑── 딸랑, 딸랑!</color>",
  ui_story_5020_50200401_47_dialog_content = "에이, 뭐야... 벽장에 걸린 <color=#FFB400>풍경</color> 소리였잖아.",
  ui_story_5020_50200401_48_dialog_content = "이상하네. 왜 신악의 방울을 풍경으로 달았지?",
  ui_story_5020_50200401_49_dialog_content = "잠깐만... 이거...",
  ui_story_5020_50200401_50_dialog_content = "<color=#e8d9bb>10년 전</color>",
  ui_story_5020_50200401_51_dialog_content = "<color=#e8d9bb>딸랑────, 딸랑────</color>",
  ui_story_5020_50200401_52_dialog_content = "쉿, 요우, 착하지. 소리 내면 안 돼. 여기 가만히 있는 거야.",
  ui_story_5020_50200401_53_dialog_content = "밖에 무슨 일이야? 츠키 언니, 무서워...",
  ui_story_5020_50200401_54_dialog_content = "나 혼자 가둬 두지 마...",
  ui_story_5020_50200401_55_dialog_content = "제발...",
  ui_story_5020_50200401_56_dialog_content = "<color=#FFB400>벽장</color> 안에서 푹 자고 있으렴. 눈을 떴을 땐 모든 게 끝나 있을 거야.",
  ui_story_5020_50200401_57_dialog_content = "츠키 언니...",
  ui_story_5020_50200401_58_dialog_content = "<size=45>문을 열어라!</size>",
  ui_story_5020_50200401_58X1_dialog_content = "(...누가 쳐들어온 건가?!)",
  ui_story_5020_50200401_58X2_dialog_content = "자, 성문을 지키십시오. 그 어떤 부정한 것도 들어오지 못하도록 하십시오!",
  ui_story_5020_50200401_58X3_dialog_content = "「이제 음양을 읊노니, 이 곡조와 함께 그대의 혼은 피안으로 돌아가리라...」",
  ui_story_5020_50200401_58X4_dialog_content = "<color=#e8d9bb>딸랑────, 딸랑────</color>",
  ui_story_5020_50200401_58X5_dialog_content = "(오니를 쫓아내는 신악의 방울 소리야...!)",
  ui_story_5020_50200401_58X6_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_5020_50200401_59_dialog_content = "누구시죠?! 어서 멈추세요! 여긴 함부로...",
  ui_story_5020_50200401_60_dialog_content = "<size=45>저리 꺼져!</size>",
  ui_story_5020_50200401_61_dialog_content = "(이 목소리는... 스승님?)",
  ui_story_5020_50200401_62_dialog_content = "나기?",
  ui_story_5020_50200401_63_dialog_content = "그 이름을 입에 올리지 마라. <color=#FFB400>「무녀」</color>.",
  ui_story_5020_50200401_64_dialog_content = "네겐 그럴 자격이 없으니까.",
  ui_story_5020_50200401_65_dialog_content = "말해라. 대체 왜 촉유군에게 항복을 권한 거지?",
  ui_story_5020_50200401_66_dialog_content = "넌 운도 백성들을 위해, 모두에게 더 좋은 미래를 위해 무녀가 될 거라고 약속했었지.",
  ui_story_5020_50200401_67_dialog_content = "......",
  ui_story_5020_50200401_68_dialog_content = "그런데 대체 왜!",
  ui_story_5020_50200401_69_dialog_content = "?!",
  ui_story_5020_50200401_70_dialog_content = "츠키!",
  ui_story_5020_50200401_71_dialog_content = "나기, 미친 것이냐?!",
  ui_story_5020_50200401_72_dialog_content = "어떻게 자기 친언니를!",
  ui_story_5020_50200401_73_dialog_content = "여봐라! 당장 저 여자를 죽여라!",
  ui_story_5020_50200401_74_dialog_content = "안... 됩니다...!",
  ui_story_5020_50200401_75_dialog_content = "그만...두십시오...",
  ui_story_5020_50200401_76_dialog_content = "합하... 우리의 발밑을 흐르는 이 강은... 논과 마을을 따라... 서쪽으로 흐르고 있겠지요...",
  ui_story_5020_50200401_77_dialog_content = "서쪽 산기슭의 정원에는... 아마 하얀 벚꽃이 벌써... 피어 있을 것입니다...",
  ui_story_5020_50200401_78_dialog_content = "부디... 그 벚꽃잎을 피로 물들이지... 말아 주세요...",
  ui_story_5020_50200401_79_dialog_content = "제가 떠나면... 그 흰 벚꽃들과 함께... 잠들게 해주세요...",
  ui_story_5020_50200401_80_dialog_content = "약속해 주세요... 제발...",
  ui_story_5020_50200401_81_dialog_content = "츠키, 정신 차려라! 내 지금 바로...",
  ui_story_5020_50200401_82_dialog_content = "「이제... 음양을... 읊노니...」",
  ui_story_5020_50200401_83_dialog_content = "무, 무얼 하려는 것이냐?!",
  ui_story_5020_50200401_84_dialog_content = "츠키! 지금 네 몸으로는 감당치 못할 것이야!",
  ui_story_5020_50200401_85_dialog_content = "「이 곡조와 함께...」",
  ui_story_5020_50200401_86_dialog_content = "「나의 혼은... 피안으로 돌아가리라...」",
  ui_story_5020_50200401_87_dialog_content = "으으윽──!",
  ui_story_5020_50200401_88_dialog_content = "......",
  ui_story_5020_50200401_89_dialog_content = "............",
  ui_story_5020_50200401_90_dialog_content = "그렇게 해서라도... 기어이 네 아우를 지키겠다는 것이냐...",
  ui_story_5020_50200401_91_dialog_content = "여봐라...",
  ui_story_5020_50200401_92_dialog_content = "앞으로 이 땅에는 오니 무사를 두어 엄히 지키도록 하라!",
  ui_story_5020_50200401_93_dialog_content = "이 여자를 죽을 때까지 가두어 둘 것이다. 두 번 다시는 해를 볼 수 없으리라!",
  ui_story_5020_50200401_94_dialog_content = "예!",
  ui_story_5020_50200401_95_dialog_content = "그 밖의 일은... 츠키의 말대로 행하라.",
  ui_story_5020_50200401_96_dialog_content = "분부 받잡겠습니다.",
  ui_story_5020_50200401_97_dialog_content = "......",
  ui_story_5020_50200401_98_dialog_content = "그대는 츠키를 죽였다. 허나 츠키는 그대를 지켰지.\n이 얼마나 우스운 일이란 말이냐!",
  ui_story_5020_50200401_99_dialog_content = "그 여자가 날 지켜줄 필요는 없었다.\n어차피 난 네놈을 죽일 수 있었으니까.",
  ui_story_5020_50200401_100_dialog_content = "나기여, 그대는 지금까지 아무것도 깨닫지 못했구나...",
  ui_story_5020_50200401_101_dialog_content = "츠키가 왜 내 곁에 서는 것을 택했는지를 말이다.",
  ui_story_5020_50200401_102_dialog_content = "츠키는 알아서는 아니 될 것을 알고 말았지만, 나는 그것을 묵인해 주었다.",
  ui_story_5020_50200401_103_dialog_content = "오니를 「퇴치」하는 것과 「부리는」 것, 그 차이는 운도의 오랜 법도와 이치를 꿰뚫는 것이었다.",
  ui_story_5020_50200401_104_dialog_content = "츠키는 내 처지를 이해해 주었고, 평생 운도의 평화를 추구하고자 나를 믿어주었다.",
  ui_story_5020_50200401_105_dialog_content = "츠키가 그대를 지킨 것은 그저...\n모든 것을 안 자가 아무것도 모르는 자에게 가지는 연민일 뿐이다.",
  ui_story_5020_50200401_106_dialog_content = "닥쳐! 그럴 리 없어!",
  ui_story_5020_50200401_107_dialog_content = "그게 아니라면 무어라 생각하는가.",
  ui_story_5020_50200401_108_dialog_content = "그대가 이미 오래전에 버렸던 자매의 정이라고 말하고 싶기라도 한 게냐?!",
  ui_story_5020_50200401_109_dialog_content = "츠키는 그대와 동년배이거늘, 항상 나이에 걸맞지 않은 깨달음으로 세상을 보아 왔지...",
  ui_story_5020_50200401_110_dialog_content = "...그런 츠키를... 그대가 죽였다!",
  ui_story_5020_50200401_111_dialog_content = "츠키가 운도에 품고 있던 모든 소망을... 그대는 츠키의 목숨과 함께 망쳐버렸다!",
  ui_story_5020_50200401_112_dialog_content = "그런 그대는 대체 무슨 자격으로 살아있단 말인가!",
  ui_story_5020_50200401_113_dialog_content = "......",
  ui_story_5020_50200401_114_dialog_content = "<size=33>츠키는... 어째서 마지막까지 그대를 지키려 했단 말인가...</size>",
  ui_story_5020_50200401_115_dialog_content = "...훌륭해. 아주 허울 좋은 언변이외다!",
  ui_story_5020_50200401_116_dialog_content = "그저 자기 야심을 위해 「이용」한 것을...\n대등하지도 않은 「신뢰」와 「이해」로 미화하다니....",
  ui_story_5020_50200401_117_dialog_content = "그렇게 해서 츠키를 속였던 거냐?!",
  ui_story_5020_50200401_118_dialog_content = "츠키는 현명한 여자였다.",
  ui_story_5020_50200401_119_dialog_content = "나와 그대의 목적은 츠키에게는 다를 바 없게 느껴졌을 것이다.\n모두 이곳을 지키기 위해서였을 뿐, 「이용」 같은 관계가 있을 리 만무하다.",
  ui_story_5020_50200401_120_dialog_content = "...허나, 이것으로 되었다.\n츠키가 그대에게 건 이 봉인도 일종의 형벌이라 할 수 있겠지.",
  ui_story_5020_50200401_121_dialog_content = "그대는 그저 영원토록 이곳에서 분개와 원한에 잠겨 있을 터이니.",
  ui_story_5020_50200401_122_dialog_content = "내 반드시 너를 죽이겠다!",
  ui_story_5020_50200401_123_dialog_content = "그런 생각이라도 품고 있는 게 그대에게 이로울 것이다.",
  ui_story_5020_50200401_124_dialog_content = "...츠키?",
  ui_story_5020_50200401_125_dialog_content = "스승님이... <size=45>무녀 언니를 죽였다고?!</size>",
  ui_story_5020_50200401_126_dialog_content = "하지만 스승님이 그런 사람일 것 같지는 않았는데...",
  ui_story_5020_50200401_127_dialog_content = "그때도 그렇게 그 여자를 이용했나?",
  ui_story_5020_50200401_128_dialog_content = "무녀여, 넌 그저 도구로 선택되었을 뿐이다.",
  ui_story_5020_50200401_129_dialog_content = "넌 전대 무녀가 어떤 끝을 맞았는지 알고 있나?",
  ui_story_5020_50200401_130_dialog_content = "닥쳐라!",
  ui_story_5020_50200401_131_dialog_content = "여봐라, 저 여자를 잡아라!",
  ui_story_5020_50200401_132_dialog_content = "아니야... 뭔가 오해가 있는 게 분명해...",
  ui_story_5020_50200401_133_dialog_content = "으, 머리가... 아파...",
  ui_story_5020_50200401_134_dialog_content = "얼른 PlayerName 쪽이랑 합류해서 이 사실을 전해야 해!",
  ui_story_5020_50200501_1_dialog_content = "이거 놔! 말로 하면 되잖아?!",
  ui_story_5020_50200501_2_dialog_content = "그래! 무슨 오해가 있는 게 분명해!",
  ui_story_5020_50200501_3_dialog_content = "......",
  ui_story_5020_50200501_4_dialog_content = "여기라면 당분간은 안전하겠군.",
  ui_story_5020_50200501_5_dialog_content = "평민들을 잘 안내해라.",
  ui_story_5020_50200501_6_dialog_content = "예!",
  ui_story_5020_50200501_7_dialog_content = "그리고 오는 내내 계속 떠들어대던 저 녀석들은...",
  ui_story_5020_50200501_8_dialog_content = "기둥에 묶어 둬라.",
  ui_story_5020_50200501_9_dialog_content = "뭐야?!",
  ui_story_5020_50200501_10_dialog_content = "예!",
  ui_story_5020_50200501_11_dialog_content = "얌전히 있어!",
  ui_story_5020_50200501_12_dialog_content = "칫... 이 녀석들...",
  ui_story_5020_50200501_13_dialog_content = "잠깐만, 이해가 안 되잖아!",
  ui_story_5020_50200501_14_dialog_content = "너희나 우리나 똑같이 사람들을 지키고 있었는데, 우린 같은 편 아니야?",
  ui_story_5020_50200501_15_dialog_content = "당연히 아니지.",
  ui_story_5020_50200501_16_dialog_content = "너희는 무녀와 함께 있었으니, 우리와는 물과 기름 같은 사이가 아닌가.",
  ui_story_5020_50200501_17_dialog_content = "무녀? 린네가 뭘 어쨌길래...",
  ui_story_5020_50200501_18_dialog_content = "알겠습니다.",
  ui_story_5020_50200501_19_dialog_content = "제 추측이 맞다면 아메모리도 당신들의 일원이겠군요. 그렇지요?",
  ui_story_5020_50200501_20_dialog_content = "무녀, 상황을 제대로 파악해라.",
  ui_story_5020_50200501_21_dialog_content = "지금 넌 우릴 심문할 입장이 아니다.",
  ui_story_5020_50200501_22_dialog_content = "후훗, 확실히 상황을 잘 모르겠군요.",
  ui_story_5020_50200501_23_dialog_content = "그렇다면 자기소개를 부탁드려도 되겠는지요.",
  ui_story_5020_50200501_24_dialog_content = "촉유군이라는 것은 대체 무엇입니까...",
  ui_story_5020_50200501_25_dialog_content = "하하하하! 참으로 웃기는군.",
  ui_story_5020_50200501_26_dialog_content = "운도의 무녀가 「촉유군」이라는 이름조차 모르는 날이 올 줄이야.",
  ui_story_5020_50200501_27_dialog_content = "이제 몇 대가 지나고 나면 아예 「운도」조차 잊어버릴 모양이로군.",
  ui_story_5020_50200501_28_dialog_content = "필경 너희들에게는 보잘 것 없는 일이겠지.",
  ui_story_5020_50200501_29_dialog_content = "무녀는 그저 성에 틀어박혀 느긋하게 「합하」의 비위나 맞추고 있으면 그만일 테니까.",
  ui_story_5020_50200501_30_dialog_content = "......",
  ui_story_5020_50200501_31_dialog_content = "왜 말을 그렇게 심하게 하는 건데?",
  ui_story_5020_50200501_32_dialog_content = "린네 씨는 계속 강부성 사람들을 지켜왔어. 그건 너희도 봤잖아!",
  ui_story_5020_50200501_33_dialog_content = "지킨다고? 허울 좋은 말 따위는 집어 치워라.",
  ui_story_5020_50200501_34_dialog_content = "그저 집에서 기르던 쥐를, 집에서 기르던 고양이가 물어 죽였을 뿐 아닌가.",
  ui_story_5020_50200501_35_dialog_content = "그런 것은 「지키는」 게 아니라 「조잡한 연극」이라 하는 것이다.",
  ui_story_5020_50200501_36_dialog_content = "「연극」? 대체 무슨...",
  ui_story_5020_50200501_37_dialog_content = "묻겠다. 너희는 온 성에 넘치는 저 악귀들이 어디서 왔다고 생각하지?",
  ui_story_5020_50200501_38_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_5020_50200501_39_dialog_content = "무녀, 그쪽이라면 음양의 도리를 잘 알지 않나. 어디 좀 들려주는 게 어떠한가.",
  ui_story_5020_50200501_40_dialog_content = "...음의 기운이 극에 달할 때, 제도되지 못한 원혼이 오니의 모습을 이루지요.",
  ui_story_5020_50200501_41_dialog_content = "그렇다면 「음의 기운」은 또 어떻게 생겨나지?\n아무런 까닭도 없이 나타난단 말인가?",
  ui_story_5020_50200501_42_dialog_content = "......",
  ui_story_5020_50200501_43_dialog_content = "내가 대신 말해주지. 그것은 <color=#FFB400>인간의 소행</color>이다.",
  ui_story_5020_50200501_44_dialog_content = "이 운도에는 예로부터 내려오는 세 개의 <color=#FFB400>신기</color>가 있다.",
  ui_story_5020_50200501_45_dialog_content = "극양의 신기, 참귀의 검 「<color=#FFB400>천운참</color>」, 지금은 그 행방을 알 수 없지.",
  ui_story_5020_50200501_46_dialog_content = "음양을 조화하는 신기, 곡옥 「<color=#FFB400>척귀능인</color>」은 우리 촉유군의 수중에 있다.",
  ui_story_5020_50200501_47_dialog_content = "그리고 극음의 신기, 「<color=#FFB400>구름의 거울</color>」은 줄곧 쇼군의 손에서 쓰이고 있었다.",
  ui_story_5020_50200501_48_dialog_content = "그때 쇼군이 린네 씨한테서 빼앗은 그 거울 말이지...",
  ui_story_5020_50200501_49_dialog_content = "「먹구름이 해를 가리면, 저승이 현세에 세워진다.」",
  ui_story_5020_50200501_50_dialog_content = "악귀가 횡행하는 작금의 상황을 만들어 낼 수 있는 것은...\n오직 「<color=#FFB400>구름의 거울</color>」뿐인 것이다.",
  ui_story_5020_50200501_51_dialog_content = "그리고 그 배후가 누구인지는 말하지 않아도 이해할 수 있을 터!",
  ui_story_5020_50200501_52_dialog_content = "...사실 우리도 같은 추측을 하고 있었어.",
  ui_story_5020_50200501_53_dialog_content = "근데 이해가 안 되는 게 하나 있어.",
  ui_story_5020_50200501_54_dialog_content = "만약 후지쿠모 쇼군이 정말로 오니를 조종하고 있다면...\n왜 쇼군은 오니를 물리치는 무녀를 육성해온 건데?",
  ui_story_5020_50200501_55_dialog_content = "말하지 않았는가, 그게 바로 「연극」이란 것이다.",
  ui_story_5020_50200501_56_dialog_content = "오니는 놈의 정복을 돕고, 무녀는 놈을 대신하여 민심을 농락하지.",
  ui_story_5020_50200501_57_dialog_content = "민심을... 농락한다고?",
  ui_story_5020_50200501_58_dialog_content = "쇼군은 오니를 조종하며 운도 사람들의 마음에 깊은 공포를 서서히 심어갔다.",
  ui_story_5020_50200501_59_dialog_content = "그러나 두려움만으로는 운도를 지배할 수 없는 법,\n사람을 부리는 데 능숙한 놈들이라면 잘 알고 있는 이치다.",
  ui_story_5020_50200501_60_dialog_content = "그러니 무녀를 길러 백성 앞에서 그 공포의 대상에 맞서는 모습을 보여주는 것이지.",
  ui_story_5020_50200501_61_dialog_content = "백성은 무녀를 따르고, 무녀는 쇼군의 명을 따른다.\n그게 바로 놈이 생각하는 통치의 길이다.",
  ui_story_5020_50200501_62_dialog_content = "하지만 그렇게 쉽게 놈의 뜻대로 되진 않을 것이다.",
  ui_story_5020_50200501_63_dialog_content = "그런 잔꾀에 넘어갈 만큼 운도 사람은 바보가 아니니 말이다.",
  ui_story_5020_50200501_64_dialog_content = "너희 무녀는 음과 양을 조화시켜 오니를 물리친다고 하지만,\n몇 대가 지나도 오니의 재앙이 진정될 기미는 보이지 않는다.",
  ui_story_5020_50200501_65_dialog_content = "......",
  ui_story_5020_50200501_66_dialog_content = "우린 결코 잊지 않았다. 애초에 이곳은 「강부」라는 이름도 아니었지.",
  ui_story_5020_50200501_67_dialog_content = "아무리 높고 훌륭한 성을 지어도, 얼마나 많은 금은보화를 가지고 오더라도.",
  ui_story_5020_50200501_68_dialog_content = "침략자는 영원히 침략자일 뿐.",
  ui_story_5020_50200501_69_dialog_content = "진정으로 운도를 지킬 수 있는 건 촉유군뿐이다.",
  ui_story_5020_50200501_70_dialog_content = "오직 우리만이 이곳에서 태어나고 자란 인간이니 말이다.",
  ui_story_5020_50200501_71_dialog_content = "침략자? 본도 사람들이 너희 눈에는 그렇게 보였던 거야...?",
  ui_story_5020_50200501_72_dialog_content = "당연한 일이 아닌가. 운도의 역사를 모르는 것이냐?",
  ui_story_5020_50200501_73_dialog_content = "뭐, 그렇겠지. 들을 기회도 없었을 테니까.",
  ui_story_5020_50200501_74_dialog_content = "(전에 모모랑 안즈가 조금 얘기해 주긴 했지만...)",
  ui_story_5020_50200501_75_dialog_content = "(촉유군이 말하는 역사와는 왠지 조금 다른 것 같아.)",
  ui_story_5020_50200501_76_dialog_content = "미안, 우리는 외지인이라서 들어본 적이 없었어.",
  ui_story_5020_50200501_77_dialog_content = "그렇다면 최소한의 인정을 베푸는 셈 치고 들려주마.",
  ui_story_5020_50200501_78_dialog_content = "오래전, 아직 본도의 무사들이 이 땅에 발을 들여놓기 전의 일이다.\n운도는 지금보다 더 아름다운 곳이었다.",
  ui_story_5020_50200501_79_dialog_content = "섬에는 자원이 풍족했고, 어떤 다툼도 없었다.\n유일한 위협이라면 이따금 현세에 모습을 드러내는 오니였지.",
  ui_story_5020_50200501_80_dialog_content = "촉유군은 운도의 평화를 지키기 위해, 귀신에 맞서고자 그 무렵에 탄생했던 것이다.",
  ui_story_5020_50200501_81_dialog_content = "그러나 결국 이 땅의 평화를 깨트린 것은 오니가 아닌 인간이었다.",
  ui_story_5020_50200501_82_dialog_content = "본도는 예로부터 운도라는 먹잇감을 노려왔고, 마침내 이곳에 첫 번째 쇼군을 파견했다.",
  ui_story_5020_50200501_83_dialog_content = "촉유군은 전쟁의 경험이 없었지만, 그래도 목숨을 걸고 맞섰다.",
  ui_story_5020_50200501_84_dialog_content = "쇼군은 연전연승을 거두었지만, 운도를 완전히 집어삼킬 수는 없었다.",
  ui_story_5020_50200501_85_dialog_content = "그러던 놈들은 결국 가장 악랄한 전법을 생각해 냈던 것이다.\n쇼군은 오니를 조종해서, 사람이 아닌 괴물들을 전쟁에 내세웠다.",
  ui_story_5020_50200501_86_dialog_content = "전란의 시대였다. 성불하지 못한 영혼은 운도에 차고 넘치는 것이었지.",
  ui_story_5020_50200501_87_dialog_content = "악귀들은 촉유군의 저항을 괴멸시켰고 운도는 함락됐다.\n그리고 쇼군은 저 해안에 강부성을 건설해 자신의 통치를 선언했던 것이다.",
  ui_story_5020_50200501_88_dialog_content = "촉유군의 잔당들은 숨어서 그때의 원한을 간직하고, 대를 이어 전해왔다.",
  ui_story_5020_50200501_89_dialog_content = "우리는 전쟁 속에서 배웠다. 그리고 모든 걸 되찾을 때를 기다리고 있는 것이다.",
  ui_story_5020_50200501_90_dialog_content = "(운도의 분쟁이 그런 거였다니...)",
  ui_story_5020_50200501_91_dialog_content = "(인간과 오니의 싸움... 그 뒤에는 인간과 인간의 대립이 숨어 있었어...)",
  ui_story_5020_50200501_92_dialog_content = "그 때가...",
  ui_story_5020_50200501_93_dialog_content = "이제 머지않았다.",
  ui_story_5020_50200501_94_dialog_content = "대장, 평민들은 잘 안내했습니다.",
  ui_story_5020_50200501_95_dialog_content = "이제...",
  ui_story_5020_50200501_96_dialog_content = "좋아. 저쪽에 가서 얘기하자고.",
  ui_story_5020_50200501_97_dialog_content = "......",
  ui_story_5020_50200501_98_dialog_content = "여러분께서는 방금 그가 말한 이야기가 진실이라고 생각하시는지요.",
  ui_story_5020_50200501_99_dialog_content = "모르겠어요... 정보가 너무 많아서 아직 정리가 안 돼요...",
  ui_story_5020_50200501_100_dialog_content = "저는 제가 오직 하나의 가르침만을 따르고 있다고 줄곧 생각했습니다.",
  ui_story_5020_50200501_101_dialog_content = "양부님의 말을 듣고, 강부성 사람들을 지키는 것 말이지요.",
  ui_story_5020_50200501_102_dialog_content = "하지만 이제 보니...",
  ui_story_5020_50200501_103_dialog_content = "그 두 일은 서로 모순되는 것 같습니다.",
  ui_story_5020_50200501_104_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_5020_50200501_105_dialog_content = "제가 해온 것이 그저 「연극」에 불과했던 것일까요.",
  ui_story_5020_50200501_106_dialog_content = "그, 근데 저 사람 얘기가 꼭 진짜라는 보장도 없잖아요.",
  ui_story_5020_50200501_107_dialog_content = "우릴 대뜸 말도 없이 붙잡은 녀석들인걸요.",
  ui_story_5020_50200501_108_dialog_content = "PlayerName, 네 생각은 어떤데?",
  ui_story_5020_50200501_109_dialog_content = "뭘 멍하니 정신을 팔고 있어?",
  ui_story_5020_50200501_110_dialog_content = "쉿──",
  ui_story_5020_50200501_111_dialog_content = "난 지금 저 사람들 말을 엿듣고 있다고...",
  ui_story_5020_50200501_112_dialog_content = "엿들어?",
  ui_story_5020_50200501_113_dialog_content = "재밌겠네! 나도 듣고 싶어!",
  ui_story_5020_50200501_114_dialog_content = "그럼 더 가까이 붙어봐.",
  ui_story_5020_50200501_115_dialog_content = "알겠어.",
  ui_story_5020_50200501_116_dialog_content = "대장, 우린 이제 갈 곳이 없습니다.",
  ui_story_5020_50200501_117_dialog_content = "성은 온통 오니 투성이고, 다른 곳의 형제들도 연락이 되질 않습니다...",
  ui_story_5020_50200501_118_dialog_content = "알겠다. 우린 일단 이동하지 않고 이곳을 지킨다.",
  ui_story_5020_50200501_119_dialog_content = "아메모리 님이 총통님을 구해내셨다고 하지 않으셨습니까?",
  ui_story_5020_50200501_120_dialog_content = "두 분이... 우릴 구하러 올까요?",
  ui_story_5020_50200501_121_dialog_content = "「명토의 유검」이 있다면 그 어떤 오니도 두려울 게 없지 않습니까!",
  ui_story_5020_50200501_122_dialog_content = "(역시 저 사람들은 아메모리 씨의 동료였구나!)",
  ui_story_5020_50200501_123_dialog_content = "(응, 게다가 아메모리, 지위가 꽤 높은 것 같아.)",
  ui_story_5020_50200501_124_dialog_content = "촉유군이 언제부터 지원군을 기다리며 싸움을 했단 말이냐.",
  ui_story_5020_50200501_125_dialog_content = "설령 혼자만 남게 하더라도 끝까지 싸워야 하는 것이다.",
  ui_story_5020_50200501_126_dialog_content = "그 말씀은... 그럼 두 분이...",
  ui_story_5020_50200501_127_dialog_content = "총통님과 아메모리 님에게는 그분들만의 일이 있다.",
  ui_story_5020_50200501_128_dialog_content = "내가 감히 염려할 일도 아니고, 네가 그럴 일도 더더욱 아니다.",
  ui_story_5020_50200501_129_dialog_content = "(그러고 보니 아메모리는 지금 어떻게 됐을까...)",
  ui_story_5020_50200501_130_dialog_content = "(걱정하지 마. 아메모리 씨는 강하니까 분명히 괜찮을 거야.)",
  ui_story_5020_50200501_131_dialog_content = "......",
  ui_story_5020_50200501_132_dialog_content = "대장, 다들 총통님이 풀려나셨다는 소식을 듣고 무척 흥분해 있습니다.",
  ui_story_5020_50200501_133_dialog_content = "그런데... 총통님께서는 우리에게 모습조차 보여주시질 않고 계십니다.",
  ui_story_5020_50200501_134_dialog_content = "형제들 중에는 그 소식이 거짓이라고 생각하는 사람도 많습니다.",
  ui_story_5020_50200501_135_dialog_content = "아니면...",
  ui_story_5020_50200501_136_dialog_content = "벌써 10년이나 지났으니, 총통님은 진작에 촉유군을 잊었을 거라는 녀석도...",
  ui_story_5020_50200501_137_dialog_content = "......",
  ui_story_5020_50200501_138_dialog_content = "거기까지.",
  ui_story_5020_50200501_139_dialog_content = "<color=#e8d9bb>콰앙──</color>",
  ui_story_5020_50200501_140_dialog_content = "(?!)",
  ui_story_5020_50200501_141_dialog_content = "무슨 일이지?",
  ui_story_5020_50200501_142_dialog_content = "<color=#e8d9bb>콰아앙!</color>",
  ui_story_5020_50200501_143_dialog_content = "(벽 너머에서 나는 소리야! 가까워!)",
  ui_story_5020_50200501_144_dialog_content = "싸울 준비를 해라!",
  ui_story_5020_50200501_145_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_5020_50200501_146_dialog_content = "<anim type=Shake><size=45>그어어어──!</size></anim>",
  ui_story_5020_50200501_147_dialog_content = "이렇게 빨리 찾아오다니...",
  ui_story_5020_50200501_148_dialog_content = "뭐, 어차피 벌어질 일이었으니.",
  ui_story_5020_50200501_149_dialog_content = "촉유군 형제들이여!",
  ui_story_5020_50200501_150_dialog_content = "예!",
  ui_story_5020_50200501_151_dialog_content = "정신 바짝 차려라!",
  ui_story_5020_50200501_152_dialog_content = "저 악귀들을 저승으로 돌려보내라!",
  ui_story_5020_50200501_153_dialog_content = "이런, 오니가 왔어!",
  ui_story_5020_50200501_154_dialog_content = "그러게! 어떡하지?!",
  ui_story_5020_50200501_155_dialog_content = "우린 묶여 있어서 아무것도 할 수가 없잖아!",
  ui_story_5020_50200501_156_dialog_content = "<size=45>어이! 우릴 풀어줘!</size>",
  ui_story_5020_50200501_157_dialog_content = "<size=45>우리도 싸우는 걸 도와줄 수 있어!</size>",
  ui_story_5020_50200501_158_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_5020_50200501_159_dialog_content = "뭐야, 안 들리나?",
  ui_story_5020_50200501_160_dialog_content = "감응 능력을 써보는 게 어때?",
  ui_story_5020_50200501_161_dialog_content = "아, 그렇네! 그럼...",
  ui_story_5020_50200501_162_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_5020_50200501_163_dialog_content = "<anim type=Shake>그어어어!</anim>",
  ui_story_5020_50200501_164_dialog_content = "이런! 하필 이럴 때...",
  ui_story_5020_50200501_165_dialog_content = "이쪽으로 온다!",
  ui_story_5020_50200501_166_dialog_content = "지금 촉유군을 불러봤자... 제때 와줄까?",
  ui_story_5020_50200501_167_dialog_content = "그걸 나한테 묻는 거야?!",
  ui_story_5020_50200501_168_dialog_content = "후훗, 그저 줄을 풀어줄 사람만 찾으면 되는 일이 아닌지요.",
  ui_story_5020_50200501_169_dialog_content = "촉유군이 풀어주지 않는다면, 저들에게 풀어달라고 하세요.",
  ui_story_5020_50200501_170_dialog_content = "저들? 네가 말하는 게 설마...",
  ui_story_5020_50200501_170X1_dialog_content = "<anim type=Shake>그어어어!</anim>",
  ui_story_5020_50200501_170X2_dialog_content = "오니한테 밧줄을 풀어달라고 하라고? 그 전에 나부터 베어버릴 거라고!",
  ui_story_5020_50200501_170X3_dialog_content = "그러니 잘 피하시는 것이 좋겠지요.",
  ui_story_5020_50200501_171_dialog_content = "<color=#e8d9bb>콰앙──!</color>",
  ui_story_5020_50200501_172_dialog_content = "<anim type=Shake>구어어──</anim>",
  ui_story_5020_50200501_173_dialog_content = "보세요.",
  ui_story_5020_50200501_174_dialog_content = "때로는 오니가 인간보다 말이 잘 통하는 법이랍니다.",
  ui_story_5020_50200502_1_dialog_content = "대장! 사방이 전부 적입니다!",
  ui_story_5020_50200502_2_dialog_content = "우린 포위됐습니다!",
  ui_story_5020_50200502_3_dialog_content = "이제 막 습격을 시작했을 뿐인데 곧바로 포위망을 펼치다니...",
  ui_story_5020_50200502_4_dialog_content = "이처럼 빠른 움직임과 포진은 예삿일이 아니다.",
  ui_story_5020_50200502_5_dialog_content = "대장, 그 말씀은...",
  ui_story_5020_50200502_6_dialog_content = "우리 촉유군이 오니와 무수히 싸워 오면서, 이렇게까지 궁지에 몰린 적이 있었나?",
  ui_story_5020_50200502_7_dialog_content = "오니의 감각은 둔해서, 그저 싸움의 분위기를 느끼고 올 뿐이었다.\n이번처럼 기민하게 움직인 적은 없었지.",
  ui_story_5020_50200502_8_dialog_content = "놈들이 지금과 같은 전세를 이룰 수 있었던 것은,\n우리의 위치를 미리 알고 포위망을 형성한 후 기습을 가한 것이다.",
  ui_story_5020_50200502_9_dialog_content = "분명히 배후에서 지휘하고 있는 놈이 있겠지.",
  ui_story_5020_50200502_10_dialog_content = "아무래도... 쇼군 놈이 조급해진 모양이군.",
  ui_story_5020_50200502_11_dialog_content = "대장, 그럼 이제 어떡합니까?",
  ui_story_5020_50200502_12_dialog_content = "우선은 버티면서 타개할 방법을 찾는다.",
  ui_story_5020_50200502_13_dialog_content = "적어도 백성들만이라도 강부성에서 대피시켜야 한다...",
  ui_story_5020_50200502_14_dialog_content = "(어이, 거기 당신들! 뒤를 조심해!)",
  ui_story_5020_50200502_15_dialog_content = "?!",
  ui_story_5020_50200502_16_dialog_content = "누가 말하는 거냐?!",
  ui_story_5020_50200502_17_dialog_content = "(나야, 아까 너희가 기둥에 묶어 둔 외지인 말이야.)",
  ui_story_5020_50200502_18_dialog_content = "밧줄을 풀은 것이냐?",
  ui_story_5020_50200502_19_dialog_content = "말을 할 거면 숨지 말고 나와라!",
  ui_story_5020_50200502_20_dialog_content = "(음... 사실 지금 난 당신들 옆에 있는 게 아냐.)",
  ui_story_5020_50200502_21_dialog_content = "(난 감응 능력이라는 걸 사용해서 당신한테 말을 걸고 있어.)",
  ui_story_5020_50200502_22_dialog_content = "무슨 뜻이지?",
  ui_story_5020_50200502_23_dialog_content = "(그러니까... 음, 그 이야기는 일단은 접어두자. 지금 그게 중요한 게 아니야.)",
  ui_story_5020_50200502_24_dialog_content = "(중요한 건 우리가 너흴 도와줄 수 있다는 거지.)",
  ui_story_5020_50200502_25_dialog_content = "도움? 흥, 우리 촉유군이 포로들의 도움이나 받을 사람들로 보이나?",
  ui_story_5020_50200502_26_dialog_content = "(지금 상황도 안 좋은데, 그런 허세는 접어두지 그래?)",
  ui_story_5020_50200502_27_dialog_content = "큭...",
  ui_story_5020_50200502_28_dialog_content = "(이제 곧 오른쪽에서도 오니가 올 거야.)",
  ui_story_5020_50200502_29_dialog_content = "오른쪽?",
  ui_story_5020_50200502_30_dialog_content = "<anim type=Shake>그어어어!</anim>",
  ui_story_5020_50200502_31_dialog_content = "정말이잖아...",
  ui_story_5020_50200502_32_dialog_content = "가자! 오니를 쓸어버리는 거다!",
  ui_story_5020_50200502_33_dialog_content = "(아, 사실 왼쪽에도 있어.)",
  ui_story_5020_50200502_34_dialog_content = "<anim type=Shake>그어어어!</anim>",
  ui_story_5020_50200502_35_dialog_content = "...왜 방금 전엔 말하지 않은 거냐?!",
  ui_story_5020_50200502_36_dialog_content = "(이쪽은 우리한테 맡기면 되니까.)",
  ui_story_5020_50200502_37_dialog_content = "답례는 필요 없어~",
  ui_story_5020_50200502_38_dialog_content = "어째서 우릴 도와준 거지?",
  ui_story_5020_50200502_39_dialog_content = "무녀가 있는 한 쇼군이 너희에게 해가 될 일은 하지 않을 터...",
  ui_story_5020_50200502_40_dialog_content = "(그건 말하자면 좀 긴데, 사실 우리도 쇼군이랑 「문제」가 좀 생겼거든...)",
  ui_story_5020_50200502_41_dialog_content = "문제?",
  ui_story_5020_50200502_42_dialog_content = "(뭐, 한번 싸웠다고 해야 하나... 나머지는 나도 정확히는 설명하기 힘들어.)",
  ui_story_5020_50200502_43_dialog_content = "(방금 당신 말을 듣고 나서야 알았어. 이 운도의 분쟁은 생각보다 더 복잡하다는 걸 말이야.)",
  ui_story_5020_50200502_44_dialog_content = "(비록 우리 같은 외부인이 나서서 정할 일은 아니겠지만...)",
  ui_story_5020_50200502_45_dialog_content = "(적어도 인간의 적이 오니라는 사실 하나만큼은 확실하다고 생각해.)",
  ui_story_5020_50200502_46_dialog_content = "(그러니까 적어도 지금은 같이 싸우자!)",
  ui_story_5020_50200502_47_dialog_content = "......",
  ui_story_5020_50200502_48_dialog_content = "좋다.",
  ui_story_5020_50200502_49_dialog_content = "일단은 믿어주도록 하지. 이 순간만은 너희도 오니에 맞서 싸우는 전사니 말이다.",
  ui_story_5020_50200502_50_dialog_content = "린네 씨! 괜찮아요?",
  ui_story_5020_50200502_51_dialog_content = "...예, 감사합니다.",
  ui_story_5020_50200502_52_dialog_content = "어디 불편한 데라도 있는 건가요?",
  ui_story_5020_50200502_53_dialog_content = "지금까지 이런 오니들은 린네 씨가 단숨에 없애버렸었잖아요.",
  ui_story_5020_50200502_54_dialog_content = "......",
  ui_story_5020_50200502_55_dialog_content = "죄송합니다. 걱정을 끼쳐 드렸군요.",
  ui_story_5020_50200502_56_dialog_content = "그저 마음이 조금 좋지 않을 뿐입니다.",
  ui_story_5020_50200502_57_dialog_content = "촉유군이 말한 것 때문인가요?",
  ui_story_5020_50200502_58_dialog_content = "...그렇습니다.",
  ui_story_5020_50200502_59_dialog_content = "「연극」이라는 말이 머릿속에서 떠나질 않습니다.",
  ui_story_5020_50200502_60_dialog_content = "그 말이 머릿속에서 계속 맴돌아서, 손에 힘이 들어가질 않더군요.",
  ui_story_5020_50200502_61_dialog_content = "어쩌면... 저는 싸울 이유를 잃어버린 것일지도 모르겠습니다.",
  ui_story_5020_50200502_62_dialog_content = "전 린네 씨가 성에서 쇼군한테 맞섰을 때 이미 마음을 정한 줄 알았어요...",
  ui_story_5020_50200502_63_dialog_content = "그때는 그저 분노했고, 이해할 수 없었을 뿐입니다.",
  ui_story_5020_50200502_64_dialog_content = "하지만 이제는 조금이나마 깨달은 사실이 있습니다.",
  ui_story_5020_50200502_65_dialog_content = "그게 뭐죠?",
  ui_story_5020_50200502_66_dialog_content = "애당초 합하께서는 제게 퇴마를 바라신 적이 없었습니다.",
  ui_story_5020_50200502_67_dialog_content = "그저 제가 무녀의 옷을 입고 백성들 앞에서 아름다운 춤을 추기를 바라셨지요.",
  ui_story_5020_50200502_68_dialog_content = "그동안 저는 그런 보잘것없는 「연극」 속 무녀의 역할을 해왔을 뿐입니다.",
  ui_story_5020_50200502_69_dialog_content = "그리고 이제 갑자기 무대 밖으로 내던져졌고,\n제가 연기해 온 게 무엇인지를 남에게 듣고서야 알았습니다.",
  ui_story_5020_50200502_70_dialog_content = "이제... 저는 무슨 역할을 맡아야 하는 것일지요...",
  ui_story_5020_50200502_71_dialog_content = "제가 맡아야 마땅한 그 역할인지, 아니면 제가 스스로 그렇다고 여겨왔던 쪽인지...",
  ui_story_5020_50200601_1_dialog_content = "모두 따라와라.",
  ui_story_5020_50200601_2_dialog_content = "왜 또 가는 거야? 어디로 가려는 건데?",
  ui_story_5020_50200601_3_dialog_content = "사카이 거리에서 점점 멀어지고 있잖아!",
  ui_story_5020_50200601_4_dialog_content = "우린 강부성을 떠날 것이다.",
  ui_story_5020_50200601_5_dialog_content = "뭐어? 왜?",
  ui_story_5020_50200601_6_dialog_content = "아무것도 없는 산골짜기로 가면 우린 어떻게 장사를 하라는 건데!",
  ui_story_5020_50200601_7_dialog_content = "악귀가 「놈」의 명령을 받고 성으로 몰려들고 있다. 지금은 오히려 성 밖이 안전하다.",
  ui_story_5020_50200601_8_dialog_content = "으으...",
  ui_story_5020_50200601_9_dialog_content = "모모, 지금 저 사람 말은 쇼군이 오니를 불러왔다는 거야?",
  ui_story_5020_50200601_10_dialog_content = "그런 것 같아. 근데 왜 그런 거지...?",
  ui_story_5020_50200601_11_dialog_content = "쇼군은 우릴 전부 죽일 생각인가...?",
  ui_story_5020_50200601_12_dialog_content = "그건 아니라고 생각해... 쇼군은 강부성의 통치자잖아.",
  ui_story_5020_50200601_13_dialog_content = "우리가 다 죽으면 누굴 통치하는데?",
  ui_story_5020_50200601_14_dialog_content = "설마... 오니?",
  ui_story_5020_50200601_15_dialog_content = "그런 무서운 얘기하지 마!",
  ui_story_5020_50200601_16_dialog_content = "<color=#e8d9bb>콰아앙!</color>",
  ui_story_5020_50200601_17_dialog_content = "?!",
  ui_story_5020_50200601_18_dialog_content = "<size=45>거기 무리들, 당장 멈춰라!</size>",
  ui_story_5020_50200601_19_dialog_content = "!!!",
  ui_story_5020_50200601_20_dialog_content = "이런...",
  ui_story_5020_50200601_21_dialog_content = "늦은 시간에 어딜 가려는 거지?",
  ui_story_5020_50200601_21X1_dialog_content = "<color=#e8d9bb>강부성 거리, 지붕 위</color>",
  ui_story_5020_50200601_21X2_dialog_content = "너, 너무 높잖아! 천천히 가!",
  ui_story_5020_50200601_21X3_dialog_content = "조금만 참아 주십시오. 지금 가장 빠르고 안전한 길은 지붕 위뿐이니 말이지요.",
  ui_story_5020_50200601_22_dialog_content = "PlayerName! 앞에 길이 없어!",
  ui_story_5020_50200601_23_dialog_content = "이제 어떡하지?",
  ui_story_5020_50200601_24_dialog_content = "아무래도... 이제 방법은 하나뿐이겠네...",
  ui_story_5020_50200601_25_dialog_content = "뛰어내리는 것 말입니까?",
  ui_story_5020_50200601_26_dialog_content = "응...",
  ui_story_5020_50200601_27_dialog_content = "좋아!",
  ui_story_5020_50200601_28_dialog_content = "야! 다들 그냥 먼저 뛰는 거야?!",
  ui_story_5020_50200601_29_dialog_content = "나...나는 아무도 안 도와주는 거냐고...",
  ui_story_5020_50200601_30_dialog_content = "서둘러, PlayerName!",
  ui_story_5020_50200601_31_dialog_content = "그러다 오니한테 잡히면 뛰지도 못해!",
  ui_story_5020_50200601_32_dialog_content = "아, 알겠다고!",
  ui_story_5020_50200601_33_dialog_content = "하아...",
  ui_story_5020_50200601_34_dialog_content = "간다아!",
  ui_story_5020_50200601_35_dialog_content = "<anim type=Shake><size=45>으──아──아──악!</size></anim>",
  ui_story_5020_50200601_36_dialog_content = "<color=#e8d9bb>푹──</color>",
  ui_story_5020_50200601_37_dialog_content = "사...살아있나?",
  ui_story_5020_50200601_38_dialog_content = "눈을 감고 뛰면 어떻게 안전하게 착지할 수 있겠어?",
  ui_story_5020_50200601_39_dialog_content = "내가 받아줬으니 망정이지.",
  ui_story_5020_50200601_40_dialog_content = "바이스... 네가 있어서 정말...",
  ui_story_5020_50200601_41_dialog_content = "일단 제대로 내려선 다음에 얘기해 줄래?",
  ui_story_5020_50200601_42_dialog_content = "아, 응...",
  ui_story_5020_50200601_43_dialog_content = "그럼 이제...",
  ui_story_5020_50200601_44_dialog_content = "다시 만났군, 이방인들.",
  ui_story_5020_50200601_45_dialog_content = "계속 지붕 위에 숨어 있었나?",
  ui_story_5020_50200601_46_dialog_content = "응...",
  ui_story_5020_50200601_47_dialog_content = "너희랑도 적당한 거리를 두는 게 좋다고 생각했거든.",
  ui_story_5020_50200601_48_dialog_content = "근데 지금은 그럴 여유가 없겠어...",
  ui_story_5020_50200601_49_dialog_content = "그래서 이제 우리한테 도와달라 간청하려는 거냐?",
  ui_story_5020_50200601_50_dialog_content = "간청? 이런 와중에도 꼭 말을 그렇게 해야 되겠어...?",
  ui_story_5020_50200601_51_dialog_content = "물론 당신들한테 폐를 끼칠 생각은 없어.",
  ui_story_5020_50200601_52_dialog_content = "난 그냥 당부해 두려는 것뿐이야. 곧 오니가 지붕을 타고 쫓아올 거거든.",
  ui_story_5020_50200601_53_dialog_content = "당신들이 싸울 생각이 없다면 우린 이대로 도망칠 거야.",
  ui_story_5020_50200601_54_dialog_content = "하지만 만약 아직 오니와 싸울 마음이 남았다면, 우리도 물론 도와줄게.",
  ui_story_5020_50200601_55_dialog_content = "흥, 말 하나는 잘하는군.",
  ui_story_5020_50200601_56_dialog_content = "어디 전장에서도 그만한 위세가 있길 빌어보마.",
  ui_story_5020_50200601_57_dialog_content = "그건 이제 곧 알게 될걸!",
  ui_story_5020_50200601_58_dialog_content = "다만 미리 말해두지. 저 여자는 물러나 있으라고 해라.",
  ui_story_5020_50200601_59_dialog_content = "우린 무녀와 함께 싸울 생각은 없으니까.",
  ui_story_5020_50200601_60_dialog_content = "......",
  ui_story_5020_50200601_61_dialog_content = "음... 저기, 린네는...",
  ui_story_5020_50200601_62_dialog_content = "잘 알겠습니다.",
  ui_story_5020_50200601_63_dialog_content = "여러분께서 몸소 나서 주신다면...",
  ui_story_5020_50200601_64_dialog_content = "저는 감사할 따름입니다.",
  ui_story_5020_50200601_65_dialog_content = "흥...",
  ui_story_5020_50200601_66_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_5020_50200601_67_dialog_content = "<anim type=Shake>그어어어!</anim>",
  ui_story_5020_50200601_68_dialog_content = "...뭐, 됐다.",
  ui_story_5020_50200601_69_dialog_content = "촉유군! 전투 준비다!",
  ui_story_5020_50200602_1_dialog_content = "얼마나 남았지?",
  ui_story_5020_50200602_2_dialog_content = "거의 다 없앴어... 주변의 기운이 약해지고 있어...",
  ui_story_5020_50200602_3_dialog_content = "바이스!",
  ui_story_5020_50200602_4_dialog_content = "응!",
  ui_story_5020_50200602_5_dialog_content = "당신들은 어때? 아직 더 싸울 수 있겠어?",
  ui_story_5020_50200602_6_dialog_content = "무슨 소리하는 거냐, 애송이.",
  ui_story_5020_50200602_7_dialog_content = "우선 네 몸이나 지켜라.",
  ui_story_5020_50200602_8_dialog_content = "당신 지금 상태가 안 좋잖아. 난 감응으로 알 수 있어.",
  ui_story_5020_50200602_9_dialog_content = "네가 정말 그런 술법을 쓸 수 있다면, 지금 내 정신이 얼마나 또렷한지도 알 수 있겠지.",
  ui_story_5020_50200602_10_dialog_content = "몸이 망가지면 정신이 아무리 또렷해도 무슨 소용인데?",
  ui_story_5020_50200602_11_dialog_content = "우리가 지금 맞서는 상대는 몸이 없어져도 싸울 수 있는 놈들이다.",
  ui_story_5020_50200602_12_dialog_content = "그것은 놈들이 한 줌의 영혼을 지니고 있기 때문이지.",
  ui_story_5020_50200602_13_dialog_content = "우리 운도의 관념에 따르면, 정신은 언제나 육체보다 강하고 고귀한 것이다.",
  ui_story_5020_50200602_14_dialog_content = "촉유군은 패배하거나 전사할 수도 있겠지. 하지만 결코 저항을 포기할 순 없다.",
  ui_story_5020_50200602_15_dialog_content = "당신들... 정말 무서운 각오를 하고 있는 거였구나...",
  ui_story_5020_50200602_16_dialog_content = "그래도 이번에는 아직 그런 각오까진 필요 없을 거야.",
  ui_story_5020_50200602_17_dialog_content = "이제 곧 끝날 테니까.",
  ui_story_5020_50200602_18_dialog_content = "흥...",
  ui_story_5020_50200602_19_dialog_content = "이게 마지막 한 마리로군.",
  ui_story_5020_50200602_20_dialog_content = "휴... 힘들어!",
  ui_story_5020_50200602_21_dialog_content = "애송이, 이제 어디로 가야 하지?",
  ui_story_5020_50200602_22_dialog_content = "서둘러 성을 나가서 평민들과 합류해야 한다.",
  ui_story_5020_50200602_23_dialog_content = "잠깐만, 아직 안심하긴 일러!",
  ui_story_5020_50200602_24_dialog_content = "어떤 사람들이 무리를 지어서 이쪽으로 오고 있어...",
  ui_story_5020_50200602_25_dialog_content = "사람? 누구지?",
  ui_story_5020_50200602_26_dialog_content = "<color=#e8d9bb>타탁... 타탁...</color>",
  ui_story_5020_50200602_27_dialog_content = "내 예상이 맞다면 당신들한테 좋은 상대는 아닐 거야...",
  ui_story_5020_50200602_28_dialog_content = "<color=#e8d9bb>타탁... 타탁... 타탁...</color>",
  ui_story_5020_50200602_29_dialog_content = "반란군의 잔당.",
  ui_story_5020_50200602_30_dialog_content = "강부성을 혼란에 빠트린 자들이여.",
  ui_story_5020_50200602_31_dialog_content = "오늘이야말로...",
  ui_story_5020_50200602_32_dialog_content = "<size=40>너희들을 일망타진하겠다.</size>",
  ui_story_5020_50200602_33_dialog_content = "무사들? 게다가 이렇게 많이?!",
  ui_story_5020_50200602_34_dialog_content = "흥, 집 지키는 개들은 항상 떼지어 다니지.",
  ui_story_5020_50200602_35_dialog_content = "큰 소리로 짖는 개는 두려워할 필요가 없는 법이다.",
  ui_story_5020_50200602_36_dialog_content = "모두 무기를 들어라!",
  ui_story_5020_50200602_37_dialog_content = "잠깐만!",
  ui_story_5020_50200602_38_dialog_content = "뒤에... 다른 사람들이 있어...",
  ui_story_5020_50200602_39_dialog_content = "다른 사람들?",
  ui_story_5020_50200602_40_dialog_content = "앗, 바이스 씨, PlayerName 씨!",
  ui_story_5020_50200602_41_dialog_content = "다들 괜찮아?!",
  ui_story_5020_50200602_42_dialog_content = "안즈랑 모모?",
  ui_story_5020_50200602_43_dialog_content = "너흰 분명히 사람들이랑 같이...",
  ui_story_5020_50200602_44_dialog_content = "아빠...",
  ui_story_5020_50200602_45_dialog_content = "쉿.",
  ui_story_5020_50200602_46_dialog_content = "...이 비겁한 놈들!",
  ui_story_5020_50200602_47_dialog_content = "평민들에게까지 손을 대다니!",
  ui_story_5020_50200602_48_dialog_content = "그건 우리가 할 말이다.",
  ui_story_5020_50200602_49_dialog_content = "촉유군 역도들은 백성들을 인질로 잡고 성 밖으로 향했다.",
  ui_story_5020_50200602_50_dialog_content = "이것이 네놈들의 첫 번째 죄다.",
  ui_story_5020_50200602_51_dialog_content = "인질? 흥, 얼토당토않은 소리!",
  ui_story_5020_50200602_52_dialog_content = "악귀가 거리를 덮칠 때는 얼굴도 보이지 않더니, 이제 와서 무슨 영웅인 체하는 것이냐!",
  ui_story_5020_50200602_53_dialog_content = "또한 너희는 합하께 반역하고 도당을 결성했다.",
  ui_story_5020_50200602_54_dialog_content = "그것이 네놈들의 두 번째 죄다.",
  ui_story_5020_50200602_55_dialog_content = "큭...",
  ui_story_5020_50200602_56_dialog_content = "또한, 질서와 법도를 전복시키기 위해 갖은 악행을 일삼았고...",
  ui_story_5020_50200602_57_dialog_content = "목적을 위해 금기를 어기고 강부성에 악귀를 불러들였다.",
  ui_story_5020_50200602_58_dialog_content = "그것이 네놈들의 세 번째 죄다.",
  ui_story_5020_50200602_59_dialog_content = "뭐라고?!",
  ui_story_5020_50200602_60_dialog_content = "촉유군은 계속 오니에 맞서 싸우고 있었잖아?",
  ui_story_5020_50200602_61_dialog_content = "맞아...",
  ui_story_5020_50200602_62_dialog_content = "저건 분명히 평민들한테 들으라고 하는 얘기야.",
  ui_story_5020_50200602_63_dialog_content = "무사 나리, 방금 하신 말씀이 정말입니까?",
  ui_story_5020_50200602_64_dialog_content = "촉유군이 귀신들을 불러들였다고요?",
  ui_story_5020_50200602_65_dialog_content = "근데 아까는 저들이 사람들을 구했는데...",
  ui_story_5020_50200602_66_dialog_content = "진상이 뭔지 누가 알겠어!",
  ui_story_5020_50200602_67_dialog_content = "그래, 우리처럼 힘없는 보통 사람들이 그런 걸 어떻게 알겠냐고...",
  ui_story_5020_50200602_68_dialog_content = "우린 그냥 우릴 지켜주는 사람만 믿으면 되는 거야...",
  ui_story_5020_50200602_69_dialog_content = "......",
  ui_story_5020_50200602_70_dialog_content = "난 너희들에게 적어도 최소한의 양심은 있으리라 여겼다.",
  ui_story_5020_50200602_71_dialog_content = "허나 이제 보니... 내가 너희를 너무 과대평가한 모양이군.",
  ui_story_5020_50200602_72_dialog_content = "이런 비열한 수작으로 시비를 전도하려 하다니, 그렇다고 모두를 속일 수 있을 거라 생각하나?",
  ui_story_5020_50200602_73_dialog_content = "다들 눈을 똑바로 떠라! 누군가는 분명히 보았을 것이다!",
  ui_story_5020_50200602_74_dialog_content = "누가 오니와 싸우며 죽어갔는지...",
  ui_story_5020_50200602_75_dialog_content = "그리고 누가 높은 담 너머에서 근심 없이 잠에 취해 있었는지 말이다!",
  ui_story_5020_50200602_76_dialog_content = "백성들이 보게 될 것은 오직 역적이 처형되는 모습뿐이다.",
  ui_story_5020_50200602_77_dialog_content = "여봐라, 평민들을 본성으로 돌려보내라.\n싸움에 무고한 자들을 말려들게 해서는 안 된다.",
  ui_story_5020_50200602_78_dialog_content = "아이고... 또 싸운단 말이야...?",
  ui_story_5020_50200602_79_dialog_content = "빨리 가자... 어서...",
  ui_story_5020_50200602_80_dialog_content = "말세야... 말세...",
  ui_story_5020_50200602_81_dialog_content = "잠깐만! 저쪽엔 우리 친구들도 있어! 해치면 안 돼!",
  ui_story_5020_50200602_82_dialog_content = "바이스 씨! PlayerName 씨! 얼른 우리랑 같이 도망가자...",
  ui_story_5020_50200602_83_dialog_content = "지금부터는 운도 사람들끼리의 싸움이 될 것 같아... 우린 어쩌지?",
  ui_story_5020_50200602_84_dialog_content = "잠깐만, 그렇게 단순한 문제가 아냐.",
  ui_story_5020_50200602_85_dialog_content = "일단 상황을 주시하자...",
  ui_story_5020_50200602_86_dialog_content = "적어도 백성들에게는 해를 끼치지 않겠다니, 일말의 양심은 남아 있는 모양이로구나.",
  ui_story_5020_50200602_87_dialog_content = "강부성의 평화를 지키는 것은 애초에 우리의 의무다.",
  ui_story_5020_50200602_88_dialog_content = "그런가? 난 그게 우리의 의무라고 생각했는데 말이지.",
  ui_story_5020_50200602_89_dialog_content = "너희들이 진정으로 평화를 원한다면, 부질없는 항거를 포기하고 법에 따라 심판을 받아라.",
  ui_story_5020_50200602_90_dialog_content = "<size=45>하하하하하!</size>",
  ui_story_5020_50200602_91_dialog_content = "쇼군이 정한 법 따위를 우리가 따를 성싶으냐!",
  ui_story_5020_50200602_92_dialog_content = "어리석은 놈들, 이제부터는 모두 너희가 자초한 일이다.",
  ui_story_5020_50200602_93_dialog_content = "흥, 원하던 바다!",
  ui_story_5020_50200602_94_dialog_content = "<color=#e8d9bb>딸랑──</color>",
  ui_story_5020_50200602_95_dialog_content = "?!",
  ui_story_5020_50200602_96_dialog_content = "!!!",
  ui_story_5020_50200602_97_dialog_content = "죄송합니다. 여러분의 흥을 깨트릴 생각은 없었습니다만.",
  ui_story_5020_50200602_98_dialog_content = "그 전에 묻고 싶은 것이 있습니다.",
  ui_story_5020_50200602_99_dialog_content = "무녀님?!",
  ui_story_5020_50200602_100_dialog_content = "역적들에게 사로잡혀 계셨던 것입니까!",
  ui_story_5020_50200602_101_dialog_content = "소신들의 불찰입니다. 지금 즉시...",
  ui_story_5020_50200602_102_dialog_content = "여러분은 촉유군이 귀신을 불러들였다고 말씀하셨는지요.",
  ui_story_5020_50200602_103_dialog_content = "그 증좌는 무엇입니까.",
  ui_story_5020_50200602_104_dialog_content = "...증좌라 하시면?",
  ui_story_5020_50200602_105_dialog_content = "어느 때에, 어디에서, 무엇을 근거로 하신 말씀이신지 묻는 것입니다.",
  ui_story_5020_50200602_106_dialog_content = "......",
  ui_story_5020_50200602_107_dialog_content = "무녀님, 소신 같은 미관말직은 이 일의 모든 내력을 알 권한은 없습니다.",
  ui_story_5020_50200602_108_dialog_content = "허나 안심하셔도 좋습니다. 이 모든 것은 합하께서 친히 하신 말씀입니다.",
  ui_story_5020_50200602_109_dialog_content = "호오.",
  ui_story_5020_50200602_110_dialog_content = "그것이 분명 합하께서 하신 말씀이고, 다른 이가 지어낸 것이 아님을 보증할 수 있으신지요.",
  ui_story_5020_50200602_111_dialog_content = "예, 그렇습니다.",
  ui_story_5020_50200602_112_dialog_content = "......",
  ui_story_5020_50200602_113_dialog_content = "후훗, 잘 알겠습니다.",
  ui_story_5020_50200602_114_dialog_content = "덕분에 제 입장을 잘 알게 되었으니, 응당 감사의 말씀을 드려야겠군요.",
  ui_story_5020_50200602_115_dialog_content = "그렇다면 다행입니다.",
  ui_story_5020_50200602_116_dialog_content = "저들을 진압하는 과정에서 해라도 입으실까 염려되니, 소신들의 뒤로 물러나 주십시오.",
  ui_story_5020_50200602_117_dialog_content = "<color=#e8d9bb>딸랑──</color>",
  ui_story_5020_50200602_118_dialog_content = "그럴 필요는 없습니다.",
  ui_story_5020_50200602_119_dialog_content = "이것이 바로 제 입장입니다.",
  ui_story_5020_50200602_120_dialog_content = "......",
  ui_story_5020_50200602_121_dialog_content = "무녀님, 소신들의 앞을 가로막는 것이 무엇을 의미하는지 잘 알고 계시겠지요.",
  ui_story_5020_50200602_122_dialog_content = "잘 모르겠습니다.",
  ui_story_5020_50200602_123_dialog_content = "저는 그저 제가 서 있던 자리를 지켰을 뿐입니다.\n여러분이 어디를 가서 무엇을 하든 저와는 무관한 일이지요.",
  ui_story_5020_50200602_124_dialog_content = "싸움이 벌어질 곳 한가운데 서신다는 것은 저희를 적으로 돌리시겠다는 것입니다.",
  ui_story_5020_50200602_125_dialog_content = "그것이 아니라면, 합하께 맞서시겠다는 뜻이겠지요.",
  ui_story_5020_50200602_126_dialog_content = "저는 무녀입니다. 무녀는 그 누구도 적으로 여기지 않습니다.",
  ui_story_5020_50200602_127_dialog_content = "다른 이가 저를 적으로 여길 수는 있겠습니다만.",
  ui_story_5020_50200602_128_dialog_content = "그 말씀은... 지금 합하를 책망하시는 것입니까?",
  ui_story_5020_50200602_129_dialog_content = "그렇지 않습니다. 오히려 이제야 그분의 뜻을 이해했는걸요.",
  ui_story_5020_50200602_130_dialog_content = "「촉유군이 귀신을 불러들였다」고 여러분이 말씀해 주신 덕분에 말이지요.",
  ui_story_5020_50200602_131_dialog_content = "......",
  ui_story_5020_50200602_132_dialog_content = "「운수각」에서 오니를 봤을 때도 저는 이해하지 못했습니다.",
  ui_story_5020_50200602_133_dialog_content = "「구름의 거울」이 오니를 되살려 냈을 때에도 저는 몰랐지요.",
  ui_story_5020_50200602_134_dialog_content = "말씀과 맞지 않던 그분의 행동에 저는 무척 혼란스러웠지만,\n어째서 그런 일을 하시는지 저는 도무지 이해할 수 없었습니다.",
  ui_story_5020_50200602_135_dialog_content = "그러나 여러분이 나타난 뒤에야 저는 마침내 답을 얻었습니다.",
  ui_story_5020_50200602_136_dialog_content = "무녀와 오니는 대대로 서로의 적이었지만. 그분께는 사실 같았던 것입니다.",
  ui_story_5020_50200602_137_dialog_content = "피아의 구분도 없이, 그저 음과 양으로 이루어진 한 쌍의 무기였을 뿐이지요.",
  ui_story_5020_50200602_138_dialog_content = "무력이 필요할 때는 오니를 부려 적을 제압하고...",
  ui_story_5020_50200602_139_dialog_content = "백성들의 마음을 다스릴 때는 무녀를 시켜 그 적의를 오니에게 돌리도록 했겠지요.",
  ui_story_5020_50200602_140_dialog_content = "무녀님, 어떤 일들은 무녀님께서 아직 이해하지 못하실 것입니다.",
  ui_story_5020_50200602_141_dialog_content = "네... 그래서 저는 제가 이해할 수 있는 것을 믿기로 하였습니다.",
  ui_story_5020_50200602_142_dialog_content = "오늘날까지 제가 배운 모든 것, 무녀로서의 제 신조를 믿기로 한 것입니다.",
  ui_story_5020_50200602_143_dialog_content = "저의 적은 오직 오니뿐입니다.",
  ui_story_5020_50200602_144_dialog_content = "......",
  ui_story_5020_50200602_145_dialog_content = "그리고 그것이 제가 지금 여기에 서 있는 이유입니다.",
  ui_story_5020_50200602_146_dialog_content = "당신 뒤의 무사들은...",
  ui_story_5020_50200602_147_dialog_content = "<color=#FFB400>산 자가 아니지요</color>. 그렇지 않습니까?",
  ui_story_5020_50200602_148_dialog_content = "......",
  ui_story_5020_50200602_149_dialog_content = "이렇게 된 이상, 더는 드릴 말씀이 없겠군요.",
  ui_story_5020_50200602_150_dialog_content = "......",
  ui_story_5020_50200602_151_dialog_content = "<color=#e8d9bb>딸랑──</color>",
  ui_story_5020_50200602_152_dialog_content = "「이제 음양을 읊노니, 이 곡조와 함께 그대의 혼은 피안으로 돌아가리라.」",
  ui_story_5020_50200701_1_dialog_content = "(우리는 시커멓게 몰려오는 오니 무사들의 압박감에 그저 보고만 있을 수밖에 없었다.)",
  ui_story_5020_50200701_2_dialog_content = "(그것은 마치 드높이 치솟은 파도가 이제 막 가장 높은 곳에서 떨어지려는 순간 같았다.)",
  ui_story_5020_50200701_3_dialog_content = "(그러나 린네는 거리 한가운데 서서, 홀로 그 파도에 맞서고 있었다.)",
  ui_story_5020_50200701_4_dialog_content = "(린네의 눈앞에는 저승이, 등 뒤에는 이승이 펼쳐져 있었다.)",
  ui_story_5020_50200701_5_dialog_content = "어머나...",
  ui_story_5020_50200701_6_dialog_content = "촉유군 여러분은 무녀와 함께 싸우는 것을 싫어하지 않으셨는지요.",
  ui_story_5020_50200701_7_dialog_content = "......",
  ui_story_5020_50200701_8_dialog_content = "무녀에게 보호받는 건 더 싫단 말이다.",
  ui_story_5020_50200701_9_dialog_content = "후훗, 정말 유감이로군요.",
  ui_story_5020_50200701_10_dialog_content = "여러분께서 전투에 참가하신다면, 제 「연극」을 감상해줄 분들이 없지 않겠는지요.",
  ui_story_5020_50200701_11_dialog_content = "그 「연극」이란 말은 어떻게 들어도 거슬리는군.",
  ui_story_5020_50200701_12_dialog_content = "당신께 배운 것이랍니다.",
  ui_story_5020_50200701_13_dialog_content = "그렇게 마음에 담아 두고 있었다니, 아무래도 절묘한 표현이었던 모양이군.",
  ui_story_5020_50200701_14_dialog_content = "네, 그렇습니다.",
  ui_story_5020_50200701_15_dialog_content = "무녀의 적으로서 저 자신보다 무녀를 더 잘 알고 계셨으니 말이지요.",
  ui_story_5020_50200701_16_dialog_content = "너도 나처럼 모든 것을 알게 되고 나면, 자기 신분이 싫어지게 될 거다.",
  ui_story_5020_50200701_17_dialog_content = "후훗, 섣불리 추단하진 말아 주시지요.",
  ui_story_5020_50200701_18_dialog_content = "「연극」이라는 말은 확실히 날카로웠지만, 싫지는 않습니다.",
  ui_story_5020_50200701_19_dialog_content = "인형 노릇도 달갑게 받아들이겠다는 건가?",
  ui_story_5020_50200701_20_dialog_content = "여러분이 관심을 갖는 것은 인형을 조종하는 손이겠지요.",
  ui_story_5020_50200701_21_dialog_content = "하지만 저는 제가 연극을 제대로 연기하고 있는지에만 관심이 있답니다.",
  ui_story_5020_50200701_22_dialog_content = "지금까지의 인형들은 제대로 연기한 적이 없었다.",
  ui_story_5020_50200701_23_dialog_content = "그렇습니까. 그렇다면 당신은 제가 제대로 연기할 수 있다고 생각하시는지요.",
  ui_story_5020_50200701_24_dialog_content = "......",
  ui_story_5020_50200701_25_dialog_content = "그게 바로 여러분이 무녀를 죽이는 것에 집착하는 이유였습니까?",
  ui_story_5020_50200701_26_dialog_content = "귀여운 아메모리는 제게 참 많은 폐를 끼쳤습니다만.",
  ui_story_5020_50200701_27_dialog_content = "귀엽...다니...",
  ui_story_5020_50200701_28_dialog_content = "아메모리 님께 그런 무례는 삼가는 게 좋을 거다.",
  ui_story_5020_50200701_29_dialog_content = "호오.",
  ui_story_5020_50200701_30_dialog_content = "아메모리는 항상 암살에 실패했으니, 체면 따위는 진작에 버렸다고 생각했습니다만.",
  ui_story_5020_50200701_31_dialog_content = "......",
  ui_story_5020_50200701_32_dialog_content = "그녀는 촉유군에서 어떤 지위에 있는지요.",
  ui_story_5020_50200701_33_dialog_content = "아메모리 님은 총통님의 제자시다.",
  ui_story_5020_50200701_34_dialog_content = "총통님께서 유폐되신 동안 촉유군은 아메모리 님을 총통으로 모셨다.",
  ui_story_5020_50200701_35_dialog_content = "그랬군요. 아메모리는 말수가 적어서 물어도 답을 해주질 않더군요.",
  ui_story_5020_50200701_36_dialog_content = "그러면 여러분의 총통이 바로 「명토의 유검」인 것인지요.",
  ui_story_5020_50200701_37_dialog_content = "총통님을 만났나?",
  ui_story_5020_50200701_38_dialog_content = "네, 한바탕 겨루기도 했지요.",
  ui_story_5020_50200701_39_dialog_content = "과연 쇼군에 맞설 수 있는 인물다웠습니다... 무서운 강자더군요.",
  ui_story_5020_50200701_40_dialog_content = "그분의 자리를 대신하는 아메모리도 힘든 길을 걸어왔겠지요.",
  ui_story_5020_50200701_41_dialog_content = "아메모리 님은 총통님과 닮은 점이 많으시다.\n총통님께서 하시려던 일도 모두 훌륭히 해내 오셨지.",
  ui_story_5020_50200701_42_dialog_content = "심지어... 총통님보다 뛰어나게 말이다.",
  ui_story_5020_50200701_43_dialog_content = "그렇습니까?",
  ui_story_5020_50200701_44_dialog_content = "무녀 암살에 있어서는 솜씨가 변변치 않은 듯하던데 말이지요.",
  ui_story_5020_50200701_45_dialog_content = "설마 그 총통님께서는 더 변변치 못하셨단 말입니까?",
  ui_story_5020_50200701_46_dialog_content = "......",
  ui_story_5020_50200701_47_dialog_content = "그 답은 너도 알고 있을 터.",
  ui_story_5020_50200701_48_dialog_content = "왜 자신이 무녀가 됐는지 생각해 봐라.",
  ui_story_5020_50200701_49_dialog_content = "......",
  ui_story_5020_50200701_50_dialog_content = "후훗, 그렇군요.",
  ui_story_5020_50200701_51_dialog_content = "그렇다면 무녀 암살도 여러분께는 일종의 「연극」이었던 것이 아닙니까.",
  ui_story_5020_50200701_52_dialog_content = "우릴 너와 같은 취급하지 마라.",
  ui_story_5020_50200701_53_dialog_content = "허나 지금은 함께 싸우고 있지요. 그렇지 않습니까?",
  ui_story_5020_50200701_54_dialog_content = "결국 당신도 이제 무대에 오른 것입니다.",
  ui_story_5020_50200702_1_dialog_content = "뒤에서 또 오니 무사들이 옵니다!",
  ui_story_5020_50200702_2_dialog_content = "이놈들... 지원군이 있었다니!",
  ui_story_5020_50200702_3_dialog_content = "...나도 봤다.",
  ui_story_5020_50200702_4_dialog_content = "이대로는 버틸 수 없습니다!",
  ui_story_5020_50200702_5_dialog_content = "대장, 이제 어떡합니까?",
  ui_story_5020_50200702_6_dialog_content = "......",
  ui_story_5020_50200702_7_dialog_content = "이 싸움, 아마 우리는 이기지 못할 것이다.",
  ui_story_5020_50200702_8_dialog_content = "대장...",
  ui_story_5020_50200702_9_dialog_content = "설마 이대로...",
  ui_story_5020_50200702_10_dialog_content = "하지만 아직 포기할 때는 아니다.",
  ui_story_5020_50200702_11_dialog_content = "우리는... 어쩌면 <color=#FFB400>다음 싸움</color>에서는 이길 수 있을지도 모른다.",
  ui_story_5020_50200702_12_dialog_content = "다음 싸움 말입니까?",
  ui_story_5020_50200702_13_dialog_content = "하지만 이 싸움에 지고 나면 다음이 있겠습니까...",
  ui_story_5020_50200702_14_dialog_content = "난 지금까지 우리가 해본 적 없는 방법을 시험해 볼 작정이다.",
  ui_story_5020_50200702_15_dialog_content = "이방인 애송이! 이리 와라!",
  ui_story_5020_50200702_16_dialog_content = "바로 옆에 있는데 뭘 그렇게 소리를 질러...",
  ui_story_5020_50200702_17_dialog_content = "어이, 애송이. 지금 이 상황에서 도망칠 자신이 있나?",
  ui_story_5020_50200702_18_dialog_content = "도망?",
  ui_story_5020_50200702_19_dialog_content = "오니 무사가 저렇게 많은데 어떻게 도망치겠어...",
  ui_story_5020_50200702_20_dialog_content = "만약 촉유군이 너희들의 뒤를 맡아준다면, 도망칠 수 있겠나?",
  ui_story_5020_50200702_21_dialog_content = "뭐?",
  ui_story_5020_50200702_22_dialog_content = "잘 들어라. 너희 이방인들은 무녀를 데리고 지금 즉시 도망쳐라.",
  ui_story_5020_50200702_23_dialog_content = "촉유군이 엄호하겠다. 다만 그리 오래 버티진 못할 것이다.",
  ui_story_5020_50200702_24_dialog_content = "너의 그 괴상한 재주를 모조리 활용하는 게 좋을 거다.",
  ui_story_5020_50200702_25_dialog_content = "알아들었나?",
  ui_story_5020_50200702_26_dialog_content = "알긴 알겠는데... 어째서...?",
  ui_story_5020_50200702_27_dialog_content = "어찌하여 그리 하려는 것인지요.",
  ui_story_5020_50200702_28_dialog_content = "......",
  ui_story_5020_50200702_29_dialog_content = "무녀, 네 「연극」은 더 많은 사람들이 보아야만 한다.",
  ui_story_5020_50200702_30_dialog_content = "......",
  ui_story_5020_50200702_31_dialog_content = "지금의 촉유군은 쇼군과 맞설 힘이 없다.",
  ui_story_5020_50200702_32_dialog_content = "하지만 너희들이라면 아직 희망이 있을지도 모른다.",
  ui_story_5020_50200702_33_dialog_content = "패배가 정해진 이상, 그저 울면서 포기하기보단 더 큰 판에 걸어보고 싶다.",
  ui_story_5020_50200702_34_dialog_content = "형제들이여! 전선을 지켜라! 한 발짝도 물러서지 마라!",
  ui_story_5020_50200702_35_dialog_content = "우리가 도망가면 너흰 어떻게 하려고?!",
  ui_story_5020_50200702_36_dialog_content = "<size=45>어서 가란 말이다!</size>",
  ui_story_5020_50200702_37_dialog_content = "......",
  ui_story_5020_50200702_38_dialog_content = "가시지요, PlayerName 님.",
  ui_story_5020_50200702_39_dialog_content = "저들은 이미 결심한 것입니다.",
  ui_story_5020_50200702_40_dialog_content = "넌 촉유군에게 빚을 진 거다.",
  ui_story_5020_50200702_41_dialog_content = "반드시 갚아라.",
  ui_story_5020_50200702_42_dialog_content = "우와!",
  ui_story_5020_50200702_43_dialog_content = "엄청나게 큰 북이다!",
  ui_story_5020_50200702_44_dialog_content = "엄청 크네!",
  ui_story_5020_50200702_45_dialog_content = "아빠, 이건 어디다 쓰는 거야?",
  ui_story_5020_50200702_46_dialog_content = "춘일제의 시작을 알리는 북이야.",
  ui_story_5020_50200702_47_dialog_content = "북재비가 북을 치면 온 강부성에 북소리가 울려서 춘일제의 시작을 모두에게 알리는 거지.",
  ui_story_5020_50200702_48_dialog_content = "우와!",
  ui_story_5020_50200702_49_dialog_content = "근데 왜 여기 버려져 있어? 북재비는?",
  ui_story_5020_50200702_50_dialog_content = "오니가 왔으니까 북재비도 당연히 도망갔겠지.",
  ui_story_5020_50200702_51_dialog_content = "아쉽네...",
  ui_story_5020_50200702_52_dialog_content = "그럼 가지고 놀아도 돼?",
  ui_story_5020_50200702_53_dialog_content = "지금은 안 돼. 사람들을 따라 도망가야지.",
  ui_story_5020_50200702_54_dialog_content = "내일 아빠가 다시 데리고 와 줄게.",
  ui_story_5020_50200702_55_dialog_content = "야, 모모.",
  ui_story_5020_50200702_56_dialog_content = "응.",
  ui_story_5020_50200702_57_dialog_content = "이 북, 지금은 주인 없지?",
  ui_story_5020_50200702_58_dialog_content = "딱 봐도 주인 없는 물건 같네.",
  ui_story_5020_50200702_59_dialog_content = "이거 가져가서...",
  ui_story_5020_50200702_60_dialog_content = "포장마차 옆에 놓으면...",
  ui_story_5020_50200702_61_dialog_content = "분명히 더 많은 손님을 불러 모을 수 있을 거야!",
  ui_story_5020_50200702_62_dialog_content = "<size=40>놈들을 잡아라!</size>",
  ui_story_5020_50200702_63_dialog_content = "<size=40>서둘러라! 어서!</size>",
  ui_story_5020_50200702_64_dialog_content = "응? 뭐지?",
  ui_story_5020_50200702_65_dialog_content = "뭔가...",
  ui_story_5020_50200702_66_dialog_content = "이쪽으로 달려오고 있어!",
  ui_story_5020_50200702_67_dialog_content = "안즈! 모모! 얼른 도와줘!",
  ui_story_5020_50200702_68_dialog_content = "아이쿠...",
  ui_story_5020_50200702_69_dialog_content = "으아아...",
  ui_story_5020_50200702_70_dialog_content = "아, 미안... 너무 빨리 달려서 못 멈췄어...",
  ui_story_5020_50200702_71_dialog_content = "그것보다 지금 급하다고! 무사들한테 쫓기고 있어!",
  ui_story_5020_50200702_72_dialog_content = "무사? 쫓겨?",
  ui_story_5020_50200702_73_dialog_content = "PlayerName 씨 무슨 짓 했어?",
  ui_story_5020_50200702_74_dialog_content = "설명할 시간이 없어! 어디 숨을 데 없어?",
  ui_story_5020_50200702_75_dialog_content = "빨리! 곧 쫓아올 거야!",
  ui_story_5020_50200702_76_dialog_content = "숨어? 너무 갑작스럽잖아!",
  ui_story_5020_50200702_77_dialog_content = "숨을 데라고 하면...",
  ui_story_5020_50200702_78_dialog_content = "<color=#e8d9bb>.........</color>",
  ui_story_5020_50200702_79_dialog_content = "<size=40>헤에──</size>",
  ui_story_5020_50200702_80_dialog_content = "PlayerName, 조금만 더 옆으로 가 봐...",
  ui_story_5020_50200702_81_dialog_content = "너무 좁아...",
  ui_story_5020_50200702_82_dialog_content = "나도 그러고 싶은데... 안이 동그란 걸 어떡해!",
  ui_story_5020_50200702_83_dialog_content = "어떻게 해도 미끄러진단 말이야!",
  ui_story_5020_50200702_84_dialog_content = "하아... 북 안에 숨자는 생각을 다 하다니...",
  ui_story_5020_50200702_85_dialog_content = "내가 아니라 안즈랑 모모가 생각한 거라고!",
  ui_story_5020_50200702_86_dialog_content = "후훗, 하지만 이보다 더 좋은 방법도 없지 않았습니까.",
  ui_story_5020_50200702_87_dialog_content = "지금은 참는 것이 좋겠습니다.",
  ui_story_5020_50200702_88_dialog_content = "네...",
  ui_story_5020_50200702_89_dialog_content = "쉿, 놈들이 왔어.",
  ui_story_5020_50200702_90_dialog_content = "너희들, 수상한 사람 세 명이 지나가는 걸 봤나?",
  ui_story_5020_50200702_91_dialog_content = "한 명은 붉은 무녀 옷을 입고 있어서 눈에 잘 띄었을 거다.",
  ui_story_5020_50200702_92_dialog_content = "응? 왜 세 명이어야 되는데?",
  ui_story_5020_50200702_93_dialog_content = "파란색 옷도 괜찮아?",
  ui_story_5020_50200702_94_dialog_content = "...「봤다」, 「못 봤다」로만 대답해라.",
  ui_story_5020_50200702_95_dialog_content = "못 봤어!",
  ui_story_5020_50200702_96_dialog_content = "그렇군, 알겠다.",
  ui_story_5020_50200702_97_dialog_content = "(휴... 이걸로 됐나...)",
  ui_story_5020_50200702_98_dialog_content = "그런데 너희는 여기서 뭘 하고 있지?",
  ui_story_5020_50200702_99_dialog_content = "왜 사람들을 따라가지 않은 거냐.",
  ui_story_5020_50200702_100_dialog_content = "아, 우리는... 그게...",
  ui_story_5020_50200702_101_dialog_content = "이 북이...",
  ui_story_5020_50200702_102_dialog_content = "북?",
  ui_story_5020_50200702_103_dialog_content = "(!!!)",
  ui_story_5020_50200702_104_dialog_content = "북에 무슨 문제라도 있나?",
  ui_story_5020_50200702_105_dialog_content = "(망했다...)",
  ui_story_5020_50200702_106_dialog_content = "그래! 이 북 때문이야!",
  ui_story_5020_50200702_107_dialog_content = "우린 북재비거든!",
  ui_story_5020_50200702_108_dialog_content = "마...맞아! 춘일제 개막 준비하고 있었어!",
  ui_story_5020_50200702_109_dialog_content = "북재비?",
  ui_story_5020_50200702_110_dialog_content = "너희처럼 키도 작은 애들이 북을 칠 수 있다고?",
  ui_story_5020_50200702_111_dialog_content = "키는 작지만...",
  ui_story_5020_50200702_112_dialog_content = "둘이 함께라면 칠 수 있어!",
  ui_story_5020_50200702_113_dialog_content = "둘이 같이?",
  ui_story_5020_50200702_114_dialog_content = "재미있구나. 어디 한번 쳐 봐라.",
  ui_story_5020_50200702_115_dialog_content = "지...진짜로 치라고?",
  ui_story_5020_50200702_116_dialog_content = "아니면 나중에 보는 게 어때? 무사 나리... 얼른 일행을 따라가야 되지 않아...?",
  ui_story_5020_50200702_117_dialog_content = "상관없다. 뒤에 나머지 인원들도 올 테니 조금 늦어도 괜찮다.",
  ui_story_5020_50200702_118_dialog_content = "자, 어디 한번 쳐 봐라.",
  ui_story_5020_50200702_119_dialog_content = "(......)",
  ui_story_5020_50200702_120_dialog_content = "(안즈, 모모... 설마 진짜 칠 생각은...)",
  ui_story_5020_50200702_121_dialog_content = "<size=30>PlayerName 씨, 미안...</size>",
  ui_story_5020_50200702_122_dialog_content = "<size=30>조금만 참아...</size>",
  ui_story_5020_50200702_123_dialog_content = "(자, 잠깐만! 진짜로...)",
  ui_story_5020_50200702_124_dialog_content = "에잇!",
  ui_story_5020_50200702_125_dialog_content = "<color=#e8d9bb><size=50>투웅───!</size></color>",
  ui_story_5020_50200702_126_dialog_content = "에잇!",
  ui_story_5020_50200702_127_dialog_content = "<color=#e8d9bb><size=50>투웅───!</size></color>",
  ui_story_5020_50200702_128_dialog_content = "제법인데? 너희들 꽤 실력이 있군!",
  ui_story_5020_50200702_129_dialog_content = "<anim type=Shake>하... 아하하...</anim>",
  ui_story_5020_50200702_130_dialog_content = "과, 과찬이야...",
  ui_story_5020_50200702_131_dialog_content = "합하께서는 춘일제를 예정대로 개최한다고 하셨다.\n마침 잘 됐군. 너흰 그 북을 본성으로 옮겨라.",
  ui_story_5020_50200702_132_dialog_content = "가는 길에 내가 말한 세 사람을 발견하면 소리를 질러라.",
  ui_story_5020_50200702_133_dialog_content = "응!",
  ui_story_5020_50200702_134_dialog_content = "아...",
  ui_story_5020_50200702_135_dialog_content = "PlayerName 씨...",
  ui_story_5020_50200702_136_dialog_content = "셋 다 괜찮아...?",
  ui_story_5020_50200702_137_dialog_content = "<size=45>괜찮을 리가 없잖아아!</size>",
  ui_story_5020_50200702_138_dialog_content = "<size=45>귀가 안 들릴 지경이라고!</size>",
  ui_story_5020_50200702_139_dialog_content = "잘 듣고 있는 것 같은데...?",
  ui_story_5020_50200702_140_dialog_content = "지금은 감응 능력을 쓴 거야! 귀는 반응이 없어!",
  ui_story_5020_50200702_141_dialog_content = "PlayerName, 너 입이 움직이는데 무슨 말하고 있어?",
  ui_story_5020_50200702_142_dialog_content = "미안! 다들 정말 미안해!",
  ui_story_5020_50200702_143_dialog_content = "휴...",
  ui_story_5020_50200702_144_dialog_content = "됐어, 그 상황에선 어쩔 수 없었으니까.",
  ui_story_5020_50200702_145_dialog_content = "쉿!",
  ui_story_5020_50200702_146_dialog_content = "무사가 또 온다!",
  ui_story_5020_50200702_147_dialog_content = "왜 끝이 없는 건데...",
  ui_story_5020_50200702_148_dialog_content = "이제 어떡하지?",
  ui_story_5020_50200702_149_dialog_content = "계속 북 안에 숨어있을 수밖에 없어!",
  ui_story_5020_50200702_150_dialog_content = "나랑 안즈가 인적이 드문 곳으로 옮겨줄게. 그러면 도망가기 쉬워질 거야.",
  ui_story_5020_50200702_151_dialog_content = "그것도... 괜찮을 것 같네...",
  ui_story_5020_50200702_152_dialog_content = "그렇지?",
  ui_story_5020_50200702_153_dialog_content = "우린 항상 좋은 방법을 생각해 낸다니까!",
  ui_story_5020_50200702_154_dialog_content = "대신 미리 말해두는데...",
  ui_story_5020_50200702_155_dialog_content = "북은 절대 치지 마!",
  ui_story_5020_50200702_156_dialog_content = "안 칠게! 절대로!",
  ui_story_5020_50200702_157_dialog_content = "(촉유군이 우리가 도망칠 수 있게 도와준 건 우리한테 뭘 원해서였을까...)",
  ui_story_5020_50200702_158_dialog_content = "(촉유군은... 어떻게 됐을까...)",
  ui_story_5020_50200702_159_dialog_content = "항복! 우린 항복하겠다!",
  ui_story_5020_50200702_160_dialog_content = "어이! 안 들리는 거냐! 그만하겠다고! 항복이다!",
  ui_story_5020_50200702_161_dialog_content = "드디어 깨달았어! 쇼군 나리 말이 맞았어!",
  ui_story_5020_50200702_162_dialog_content = "촉유군은 죄인이다! 법의 심판을 받겠다!",
  ui_story_5020_50200702_163_dialog_content = "......",
  ui_story_5020_50200702_164_dialog_content = "무사 나리, 당신은 쇼군의 개... 아니, 오른팔로서...",
  ui_story_5020_50200702_165_dialog_content = "당연히 법과 절차를 따르겠지?",
  ui_story_5020_50200702_166_dialog_content = "어째서 무녀를 보내준 것이냐.",
  ui_story_5020_50200702_167_dialog_content = "무녀는 알아서 도망쳤는데? 우리랑 무슨 상관이야?",
  ui_story_5020_50200702_168_dialog_content = "...적의 적이 반드시 친구라고 할 수는 없겠지.",
  ui_story_5020_50200702_169_dialog_content = "허나 무녀는 합하의 양녀다. 너희가 그래봤자 어떤 파란도 일으키지 못할 것이다.",
  ui_story_5020_50200702_170_dialog_content = "그럼 잘됐네! 얼른 끝내자고! 이제 평화로운 시대가 오는구나!",
  ui_story_5020_50200702_171_dialog_content = "......",
  ui_story_5020_50200702_172_dialog_content = "놈들을 묶어서 본성으로 압송하라.",
  ui_story_5020_50200801_1_dialog_content = "「붉은 꽃 꺾어 님에게 주니──」",
  ui_story_5020_50200801_2_dialog_content = "「꽃잎은 옥설 위에 떨어지네.」",
  ui_story_5020_50200801_3_dialog_content = "스승님, 이제 어찌 하실 생각이십니까.",
  ui_story_5020_50200801_4_dialog_content = "뭐야, 아직도 따라오고 있었나.",
  ui_story_5020_50200801_5_dialog_content = "그렇게 계속 따라오기 힘들지도 않는 것이냐.",
  ui_story_5020_50200801_6_dialog_content = "소생이 도움을 드릴 수 있습니다.",
  ui_story_5020_50200801_7_dialog_content = "뭘 도와주겠다는 것이냐? 필요 없다.",
  ui_story_5020_50200801_8_dialog_content = "난 내 개인적인 일을 해결하러 갈 뿐이다.",
  ui_story_5020_50200801_9_dialog_content = "볼일이 끝나면 다시 찾아가마. 그러니 얌전히 있어라.",
  ui_story_5020_50200801_10_dialog_content = "......",
  ui_story_5020_50200801_11_dialog_content = "스승님, 그 당시에도 스승님은 홀로 가신 끝에...",
  ui_story_5020_50200801_12_dialog_content = "...다시는 그런 일이 벌어지게 둘 수는 없습니다.",
  ui_story_5020_50200801_13_dialog_content = "소생도 어른이 되었습니다. 조금이나마 힘이 되어 드릴 수 있습니다.",
  ui_story_5020_50200801_14_dialog_content = "그리고... 소생뿐만이 아닙니다. 촉유군이 있지 않습니까.",
  ui_story_5020_50200801_15_dialog_content = "그때로부터 몇 년이 흐른 것이냐...",
  ui_story_5020_50200801_16_dialog_content = "10년입니다.",
  ui_story_5020_50200801_17_dialog_content = "10년이라! 하하하, 참으로 길었구나.",
  ui_story_5020_50200801_18_dialog_content = "내 기억 속 너는 검보다도 작아서, 바람이 불면 날아갈 것만 같았지.",
  ui_story_5020_50200801_19_dialog_content = "그런데 지금은 벌써 이렇게 컸구나. 솜씨도 제법이라 뿌리쳐도 떨어지질 않아.",
  ui_story_5020_50200801_20_dialog_content = "스승님...",
  ui_story_5020_50200801_21_dialog_content = "그런데 정작 네 머리는 그리 똑똑해지지 않은 것 같구나.",
  ui_story_5020_50200801_22_dialog_content = "「힘이 되어 준다」니, 무슨 힘을 주겠다는 것이냐?",
  ui_story_5020_50200801_23_dialog_content = "스승님께서 계속 이루려 하셨던 일을 도울 것입니다.",
  ui_story_5020_50200801_24_dialog_content = "강부성을 진정한 주인의 손에 돌려주는 것 말입니다.",
  ui_story_5020_50200801_25_dialog_content = "하하하, 이제 알겠구나.",
  ui_story_5020_50200801_26_dialog_content = "그게 바로 네가 어떻게든 날 구해내려던 이유였겠지.",
  ui_story_5020_50200801_27_dialog_content = "넌 그저 내가 모든 것을 해결해 주리라 기대하고 있는 것이야.",
  ui_story_5020_50200801_28_dialog_content = "내가 너흴 데리고 성곽 아래에서 검을 휘두르며,\n쇼군 놈을 쳐부수길 바라는 것이겠지. 그렇지?",
  ui_story_5020_50200801_29_dialog_content = "스승님께서는 분명히 하실 수...",
  ui_story_5020_50200801_30_dialog_content = "거기까지 해라.",
  ui_story_5020_50200801_31_dialog_content = "제자야, 너는 내게 너무나도 많은 허황된 환상을 품고 있어.",
  ui_story_5020_50200801_32_dialog_content = "나는 성자 같은 게 아니다. 게다가 그런 존재에는 한참 못 미친다.",
  ui_story_5020_50200801_33_dialog_content = "너희들의 기대로 날 구속하고, 「정의」 따위를 연기하게 하지 마라.",
  ui_story_5020_50200801_34_dialog_content = "......",
  ui_story_5020_50200801_35_dialog_content = "허나 스승님께서 계속해오신 것은...",
  ui_story_5020_50200801_36_dialog_content = "그래, 나는 계속 쇼군에게 항거해 왔다.",
  ui_story_5020_50200801_37_dialog_content = "하지만 그건 내가 그리 하고 싶었을 뿐이지, 천하의 백성들을 위해서가 아니었다.",
  ui_story_5020_50200801_38_dialog_content = "나는 그리 많은 것을 감당할 수 없다.",
  ui_story_5020_50200801_39_dialog_content = "......",
  ui_story_5020_50200801_40_dialog_content = "사실 나는 줄곧 내가 촉유군의 총통으로는 적합하지 않다고 생각해 왔다.",
  ui_story_5020_50200801_41_dialog_content = "그저 그 시절에는 나보다 강한 사람이 없었을 뿐이고,\n어쩌다 보니 저들이 나를 치켜세운 것에 지나지 않는다.",
  ui_story_5020_50200801_42_dialog_content = "총통이라는 역할은 내겐 번거롭고 고된 의무였다.",
  ui_story_5020_50200801_43_dialog_content = "난 차라리 홀로 성에 쳐들어가는 쪽이 더 좋았지.",
  ui_story_5020_50200801_44_dialog_content = "성의 무사들이 겹겹이 포진해도, 나를 막을 수 있는 사람은 아무도 없었다.",
  ui_story_5020_50200801_45_dialog_content = "그래, 난 그렇게 하고 싶은 일을 하는 사람이다.",
  ui_story_5020_50200801_46_dialog_content = "너는 어떻느냐, 제자야.",
  ui_story_5020_50200801_47_dialog_content = "넌 대체 무엇을 하고 싶은 것이냐.",
  ui_story_5020_50200801_48_dialog_content = "소생은...",
  ui_story_5020_50200801_49_dialog_content = "생각해본 적 없나?",
  ui_story_5020_50200801_50_dialog_content = "......",
  ui_story_5020_50200801_51_dialog_content = "소생은 줄곧 스승님처럼 되고 싶었습니다.",
  ui_story_5020_50200801_52_dialog_content = "호오?",
  ui_story_5020_50200801_53_dialog_content = "촉유군 사람들은 모두 소생을 스승님의 후계자로 여겨 왔습니다.",
  ui_story_5020_50200801_54_dialog_content = "소생도... 모두의 기대에 부응하고자 노력했고,\n스승님의 부재가 남긴 공백을 메워보려 했습니다.",
  ui_story_5020_50200801_55_dialog_content = "그러나 그 공백은 소생에게는 너무나도 큰 것이었습니다.\n아무리 노력해도 충분하지 못했습니다.",
  ui_story_5020_50200801_56_dialog_content = "......",
  ui_story_5020_50200801_57_dialog_content = "그러니... 스승님께서 봉인의 땅에서 나오셨을 때,\n소생은 비로소 한숨을 돌릴 수 있었던 것입니다.",
  ui_story_5020_50200801_58_dialog_content = "그 순간에는 소생의 사명이 마침내 끝났다고 생각했습니다.",
  ui_story_5020_50200801_59_dialog_content = "바보 같은 제자야. 너는 내 대신이 아니야.",
  ui_story_5020_50200801_60_dialog_content = "촉유군은 내 아래에서 진퇴유곡의 처지를 수없이 겪어왔다.\n그럼에도 네 덕분에 10년을 버틸 수 있었던 것이지.",
  ui_story_5020_50200801_61_dialog_content = "너는 이미 나보다 훨씬 잘하였다.",
  ui_story_5020_50200801_62_dialog_content = "그럴 리가... 없습니다.",
  ui_story_5020_50200801_63_dialog_content = "이제부터 너도 네가 하고 싶은 일을 찾는 게 좋겠구나.",
  ui_story_5020_50200801_64_dialog_content = "그건 내가 가르쳐줄 수 없는 일이다.",
  ui_story_5020_50200801_65_dialog_content = "......",
  ui_story_5020_50200801_66_dialog_content = "자, 그러니 조금이라도 내 제자다운 면모를 보이란 말이다. 멍청하게 굴지 말고.",
  ui_story_5020_50200801_67_dialog_content = "가서 네가 할 일을 하는 거다.",
  ui_story_5020_50200801_68_dialog_content = "<color=#e8d9bb>뚜벅... 뚜벅... 뚜벅...</color>",
  ui_story_5020_50200801_69_dialog_content = "......",
  ui_story_5020_50200801_70_dialog_content = "왜 아직도 따라오는 것이냐?",
  ui_story_5020_50200801_71_dialog_content = "소생은 자신이 하고 싶은 일이 무엇인지 아직 모르겠습니다.\n그래서 지금은 스승님을 따라가고자 합니다.",
  ui_story_5020_50200801_72_dialog_content = "너...",
  ui_story_5020_50200801_73_dialog_content = "하아, 그럼 네 마음대로 해라.",
  ui_story_5020_50200801_74_dialog_content = "<color=#e8d9bb>뚜벅... 뚜벅... 뚜벅...</color>",
  ui_story_5020_50200801_75_dialog_content = "「붉은 꽃 꺾어 님에게 주니──」",
  ui_story_5020_50200801_76_dialog_content = "「꽃잎은...」",
  ui_story_5020_50200801_77_dialog_content = "「꽃잎은 옥설 위에 떨어지네.」",
  ui_story_5020_50200801_78_dialog_content = "......",
  ui_story_5020_50200801_79_dialog_content = "생각이 나는구나. 어렸을 때 넌 노래를 잘했지.",
  ui_story_5020_50200801_80_dialog_content = "지금은 더 잘하게 되었구나.",
  ui_story_5020_50200801_81_dialog_content = "스승님의 칭찬을 받으니 기쁩니다.",
  ui_story_5020_50200801_82_dialog_content = "다른 한 제자 녀석은 아둔해서 가사조차 기억하질 못했는데 말이야.",
  ui_story_5020_50200801_83_dialog_content = "...그 아이는 지금 더 많은 것을 잊어버렸습니다.",
  ui_story_5020_50200801_84_dialog_content = "알고 있다. 녀석은 뭐든지 몸으로 배우는 부류였지.\n싸움을 배우는 능력만큼은 누구보다 빨랐다.",
  ui_story_5020_50200801_85_dialog_content = "어렸을 때는 네가 항상 졌었는데, 지금은 어떻지?",
  ui_story_5020_50200801_86_dialog_content = "......",
  ui_story_5020_50200801_87_dialog_content = "마침 잘됐군. 기어이 따라와야겠다면 일이나 좀 거들거라.",
  ui_story_5020_50200801_88_dialog_content = "이 밧줄을 당겨봐라.",
  ui_story_5020_50200801_89_dialog_content = "스승님, 이것은 이 가게의 물건이 아닙니까...",
  ui_story_5020_50200801_90_dialog_content = "알고 있다. 빌리는 것뿐이다. 안 돌려주는 것도 아니잖아.",
  ui_story_5020_50200801_91_dialog_content = "자, 나와 동시에 당기는 거다.",
  ui_story_5020_50200801_92_dialog_content = "<color=#e8d9bb>후두두둑──</color>",
  ui_story_5020_50200801_93_dialog_content = "좋아, 그 밧줄을 지고 따라와라.",
  ui_story_5020_50200801_94_dialog_content = "...예.",
  ui_story_5020_50200801_95_dialog_content = "<color=#e8d9bb>뚜벅... 뚜벅... 뚜벅...</color>",
  ui_story_5020_50200801_96_dialog_content = "참.",
  ui_story_5020_50200801_97_dialog_content = "그때 내가 그렇게 된 뒤로...",
  ui_story_5020_50200801_98_dialog_content = "쇼군이 장례를 치르진 않았나?",
  ui_story_5020_50200801_99_dialog_content = "장례 말씀이십니까?",
  ui_story_5020_50200801_100_dialog_content = "그런 기억은 없습니다.",
  ui_story_5020_50200801_101_dialog_content = "음, 그렇군.",
  ui_story_5020_50200801_102_dialog_content = "누구의 장례 말씀이신지요.",
  ui_story_5020_50200801_103_dialog_content = "......",
  ui_story_5020_50200801_104_dialog_content = "「츠키」다. 아직 기억하고 있나?",
  ui_story_5020_50200801_105_dialog_content = "그때 츠키가 너희 둘을 내게 맡겼었지.",
  ui_story_5020_50200801_106_dialog_content = "예, 기억하고 있습니다.",
  ui_story_5020_50200801_107_dialog_content = "스승님의 언니 되시는 분이 아닙니까.",
  ui_story_5020_50200801_108_dialog_content = "어릴 적에는 줄곧 저희를 돌봐 주셨지요.",
  ui_story_5020_50200801_109_dialog_content = "무척 자상하신 분이었던 기억이 납니다.",
  ui_story_5020_50200801_110_dialog_content = "그래, 정말 자상한 사람이었지.",
  ui_story_5020_50200801_111_dialog_content = "어떻게 별세하신 것인지요.",
  ui_story_5020_50200801_112_dialog_content = "......",
  ui_story_5020_50200801_113_dialog_content = "내가 죽였다.",
  ui_story_5020_50200801_114_dialog_content = "!",
  ui_story_5020_50200801_115_dialog_content = "츠키가 「무녀」였기 때문이지.",
  ui_story_5020_50200801_116_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_5020_50200801_117_dialog_content = "<color=#e8d9bb>............</color>",
  ui_story_5020_50200801_118_dialog_content = "애당초 무녀가 되지 말았어야 했다. 나는 처음부터 그렇게 말했었지.",
  ui_story_5020_50200801_119_dialog_content = "허나 츠키는 내 말에는 아랑곳하지 않았다.\n자기가 언니니까, 항상 아우보다 똑똑하다고 생각했지.",
  ui_story_5020_50200801_120_dialog_content = "츠키는 무녀가 운도에 평화를 가져다줄 거라고 했다.",
  ui_story_5020_50200801_121_dialog_content = "나는 그런 츠키를 비웃었지. 무녀가 주는 평화란 그저 쇼군을 위한 것...\n운도에 평화를 줄 수 있는 것은 오직 검뿐이라고 나는 말했었다.",
  ui_story_5020_50200801_122_dialog_content = "그렇게 결국에는 어느 쪽도 서로를 설득하지 못하고, 각자의 길을 걷게 되었던 것이다.",
  ui_story_5020_50200801_123_dialog_content = "츠키는 본도로 수행을 떠났고, 나는 도처에서 오니를 베며 솜씨를 길렀다.",
  ui_story_5020_50200801_124_dialog_content = "그리고 몇 년 후, 츠키는 쇼군의 무녀가 되었고, 나는 「명토의 유검」이 되었다.",
  ui_story_5020_50200801_125_dialog_content = "......",
  ui_story_5020_50200801_126_dialog_content = "다시 만났을 때 츠키는 옛날이야기는 전혀 꺼내지 않았고,\n나와 퇴마로 승부를 겨루고 싶다고 했다.",
  ui_story_5020_50200801_127_dialog_content = "그 말을 듣고 난 웃음을 참지 못했고, 기꺼이 승부를 받아들였지.",
  ui_story_5020_50200801_128_dialog_content = "그때 츠키는 자신만만하게 어떤 검을 뽑아 들었다.",
  ui_story_5020_50200801_129_dialog_content = "나는 그와 같은 칼은 한 번도 본 적이 없었다.\n극양의 힘을 발하는 그 모습은 마치 귀신을 베기 위해서만 존재하는 것처럼 보였다.",
  ui_story_5020_50200801_130_dialog_content = "나는 그 승부에서 졌고, 츠키는 기쁜 듯이 내 눈앞에서 춤을 추며 말했다...",
  ui_story_5020_50200801_131_dialog_content = "「말했잖아요. 무녀는 평화를 가져온다고 말이에요」...라고.",
  ui_story_5020_50200801_132_dialog_content = "그때 난 츠키가 정말 해낼 수 있을 거라 믿고 있었다.",
  ui_story_5020_50200801_133_dialog_content = "스승님을 이기다니...",
  ui_story_5020_50200801_134_dialog_content = "그 검이 없었으면 절대 이길 수 없었어!",
  ui_story_5020_50200801_135_dialog_content = "참귀의 검 천운참이 있으면 세 살짜리 어린아이도 오니를 물리칠 수 있을 것이다.\n하물며 그걸 츠키가 다루었으니 그 위력이 어떻겠어.",
  ui_story_5020_50200801_136_dialog_content = "다만 나는 그 이후로 다시는 「천운참」을 볼 수 없었다.",
  ui_story_5020_50200801_137_dialog_content = "그 승부 이후 퇴마는 츠키의 목표가 아니라, 한낱 수단이 되어버렸으니까.",
  ui_story_5020_50200801_138_dialog_content = "......",
  ui_story_5020_50200801_139_dialog_content = "츠키는 구름의 거울을 사용해 사람들에게 오니를 퇴치하는 모습을 보이기 시작했다.",
  ui_story_5020_50200801_140_dialog_content = "하지만 난 알 수 있었지. 그건 그저 연극일 뿐이었다.",
  ui_story_5020_50200801_141_dialog_content = "10년 전 그 축제에서 츠키는 구름의 거울을 사용해 오니를 불러냈고,\n그것을 다시 퇴치하는 연극을 질리지도 않고 되풀이했다.",
  ui_story_5020_50200801_142_dialog_content = "나는 그것을 알아봤지만, 애석하게도 다른 이들은 아무것도 모른 채 믿게 되었지.",
  ui_story_5020_50200801_143_dialog_content = "백성들은 무녀가 강부성에 평화를 가져다준다고 믿었고,\n무녀를 기르는 쇼군은 훌륭한 통치자라고 믿었다.",
  ui_story_5020_50200801_144_dialog_content = "그때 비로소 나는 알게 되었다.\n나와 츠키는 서로가 서로의 평화를 가로막는 적이 되어 있었던 것이다.",
  ui_story_5020_50200801_145_dialog_content = "촉유군은 뜻이 꺾여 많은 이들이 저항할 의지를 잃었고,\n쇼군 편에 붙어 순종하려는 자들도 생겨나기 시작했다.",
  ui_story_5020_50200801_146_dialog_content = "그것은 무력 진압보다 더 무서운 것이었지.",
  ui_story_5020_50200801_147_dialog_content = "어째서입니까?",
  ui_story_5020_50200801_148_dialog_content = "쇼군에게 살해당한 자들의 자식들은 원한을 가슴에 새기고,\n앞선 자들의 뜻을 이어받아 저항자가 된다.",
  ui_story_5020_50200801_149_dialog_content = "그러나 무녀에게 속은 자들은 점차 원한을 잊게 되고,\n자신의 뿌리를 잊은 채로 쇼군의 가축이 되지.",
  ui_story_5020_50200801_150_dialog_content = "촉유군은 패배를 두려워하지 않는다.\n비록 진정한 승리를 맛본 적은 없었으나, 우리의 저항심은 결코 꺼진 적이 없다.",
  ui_story_5020_50200801_151_dialog_content = "진정으로 무서운 것은 타협, 동화, 그리고 변화다.",
  ui_story_5020_50200801_152_dialog_content = "전사들은 그렇게 점점 자신이 싸울 이유를 잊게 되니 말이다.",
  ui_story_5020_50200801_153_dialog_content = "그리고 결국에는 우리가 왜 존재했는지조차 기억하는 사람이 없게 되지.",
  ui_story_5020_50200801_154_dialog_content = "이 섬은 아직 운도라고 불리기는 하지만, 이미 오래전에 운도 본연의 모습을 잃어버렸다.",
  ui_story_5020_50200801_155_dialog_content = "......",
  ui_story_5020_50200801_156_dialog_content = "그래서 나는 너와 촉유군의 모든 이에게 무녀를 반드시 죽여야 한다고 했던 것이다.",
  ui_story_5020_50200801_157_dialog_content = "쇼군은 결코 촉유군을 꺾을 수 없지만, 무녀는 그럴 수 있는 존재니까.",
  ui_story_5020_50200801_158_dialog_content = "<color=#e8d9bb>뚜벅... 뚜벅... 뚜벅...</color>",
  ui_story_5020_50200801_159_dialog_content = "자, 다 왔다.",
  ui_story_5020_50200801_160_dialog_content = "와서 거들어라. 여기 있는 <color=#FFB400>술</color>을 전부 꺼내는 거다.",
  ui_story_5020_50200801_161_dialog_content = "그리고 지고 온 밧줄로 술동이를 전부 묶어라.",
  ui_story_5020_50200801_162_dialog_content = "스승님, 이건...",
  ui_story_5020_50200801_163_dialog_content = "괜찮대도. 이 가게 주인은 나랑 아는 사이니까!",
  ui_story_5020_50200801_164_dialog_content = "탁자에 차용증을 써뒀으니 돈은 나중에 돌아와서 주면 된다.",
  ui_story_5020_50200801_165_dialog_content = "서둘러라.",
  ui_story_5020_50200801_166_dialog_content = "......",
  ui_story_5020_50200801_167_dialog_content = "<color=#e8d9bb>투욱... 투욱...</color>",
  ui_story_5020_50200801_168_dialog_content = "휴...",
  ui_story_5020_50200801_169_dialog_content = "좋아, 잘 묶었군!",
  ui_story_5020_50200801_170_dialog_content = "이 술들을 짊어지고 따라와라.",
  ui_story_5020_50200801_171_dialog_content = "무거워서 못 걷겠으면 교대해 주마.",
  ui_story_5020_50200801_172_dialog_content = "...괜찮습니다.",
  ui_story_5020_50200801_173_dialog_content = "정말이냐? 앞으로는 더 힘들 텐데.",
  ui_story_5020_50200801_174_dialog_content = "어디로 가시려는 겁니까?",
  ui_story_5020_50200801_175_dialog_content = "<color=#FFB400>본성</color>으로 간다.",
  ui_story_5020_50200801_176_dialog_content = "본성 말입니까?!",
  ui_story_5020_50200801_177_dialog_content = "그래.",
  ui_story_5020_50200801_178_dialog_content = "본성의 꼭대기엔 가 보았나? 거기 경치는 정말 절경이거든. 술 마시기 가장 좋은 곳이지.",
  ui_story_5020_50200801_179_dialog_content = "너는 내 제자가 아니더냐. 본성에 쳐들어가는 정도는 어렵지 않겠지?",
  ui_story_5020_50200801_180_dialog_content = "...예.",
  ui_story_5020_50200801_181_dialog_content = "스승님께서 가실 수 있는 곳이라면 저도 갈 수 있습니다.",
  ui_story_5020_50200801_182_dialog_content = "<color=#e8d9bb>뚜벅... 뚜벅... 뚜벅...</color>",
  ui_story_5020_50200801_183_dialog_content = "또 이 길을 걷는구나.",
  ui_story_5020_50200801_184_dialog_content = "10년 전에도 이 길을 걸었지. 본성의 모습이 점점 커지는 것을 보며 말이다.",
  ui_story_5020_50200801_185_dialog_content = "저 성은 해와 달도 가릴 만큼 커서, 한 번 들어가면 다시는 못 나올 것만 같았다.",
  ui_story_5020_50200801_186_dialog_content = "하지만 스승님께서는 나오실 뜻이 없으셨지 않습니까.",
  ui_story_5020_50200801_187_dialog_content = "「척귀능인」을 저희에게 맡기고 가셨으니 말입니다.",
  ui_story_5020_50200801_188_dialog_content = "하하, 그랬지.",
  ui_story_5020_50200801_189_dialog_content = "「척귀능인」은 보물이다. 무슨 일이 있어도 쇼군의 손에 넘어가서는 안 되는 것이다.",
  ui_story_5020_50200801_190_dialog_content = "그런 위험을 아시면서도 무녀를 죽여야만 했던 것입니까.",
  ui_story_5020_50200801_191_dialog_content = "그것도 친언니를...",
  ui_story_5020_50200801_192_dialog_content = "그래. 친언니를 말이다.",
  ui_story_5020_50200801_193_dialog_content = "어쩌면 서로 통하는 게 있었다고 해야 할까.\n우리는 그 날이 오리라는 것을 모두 알고 있었다.",
  ui_story_5020_50200801_194_dialog_content = "나는 죽을 각오가 되어 있었고, 츠키도 내 손에 죽을 각오를 하고 있었다.",
  ui_story_5020_50200801_195_dialog_content = "난 우리가 「운수각」에서 함께 운도의 평화를 위해 죽는 줄로만 알았다.",
  ui_story_5020_50200801_196_dialog_content = "하지만...",
  ui_story_5020_50200801_197_dialog_content = "츠키는 내가 죽는 것을 원치 않았고...",
  ui_story_5020_50200801_198_dialog_content = "나도 사실 죽고 싶지 않았다.",
  ui_story_5020_50200801_199_dialog_content = "?!",
  ui_story_5020_50200801_200_dialog_content = "반드시 저승에 함께 데려가야 할 자가 있었으니 말이야.",
  ui_story_5020_50200801_201_dialog_content = "......",
  ui_story_5020_50200801_202_dialog_content = "...후지쿠모 쇼군 말씀이십니까?",
  ui_story_5020_50200801_203_dialog_content = "그래, 그놈이지. 당연히 그놈이 아니겠느냐.",
  ui_story_5020_50200801_204_dialog_content = "츠키의 죽음 앞에서야 나는 무엇이 츠키를 바꿔버린 것인지 알았다.",
  ui_story_5020_50200801_205_dialog_content = "츠키는 한 사람을 믿었다. 죽음 직전까지도 믿고 있었지.",
  ui_story_5020_50200801_206_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_5020_50200801_207_dialog_content = "난 차라리 츠키가 타락했거나, 혹은 누군가에게 조종당했길 빌었다.",
  ui_story_5020_50200801_208_dialog_content = "허나... 츠키는 스스로 후지쿠모에게 속는 것을 선택했던 것이었다.",
  ui_story_5020_50200801_209_dialog_content = "그것이 잘못된 일임을 알면서도, 츠키는 후지쿠모가 옳다고 믿었다.",
  ui_story_5020_50200801_210_dialog_content = "츠키의 판단을 짓눌러 버렸던 그 인간.",
  ui_story_5020_50200801_211_dialog_content = "나는 그 감정을 뼈에 사무치게 증오했다.",
  ui_story_5020_50200801_212_dialog_content = "감정으로 츠키의 판단을 일그러트린 쇼군을 증오했다.",
  ui_story_5020_50200801_213_dialog_content = "말했잖아. 나라는 사람은 하고 싶은 일을 할 뿐이라고.",
  ui_story_5020_50200801_214_dialog_content = "그러니 나와 놈, 적어도 어느 한쪽은 반드시 죽어야만 한다.",
  ui_story_5020_50200801_215_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_5020_50200801_216_dialog_content = "드디어 도착했구나.",
  ui_story_5020_50200801_217_dialog_content = "건물 타는 건 너도 잘하겠지?",
  ui_story_5020_50200801_218_dialog_content = "예.",
  ui_story_5020_50200801_219_dialog_content = "그렇다면 누가 먼저 올라가는지 겨루어 볼까!",
  ui_story_5020_50200801_220_dialog_content = "...스승님, 저는 술을 잔뜩 지고 있습니다만.",
  ui_story_5020_50200801_221_dialog_content = "뭐냐, 정말 스승을 이겨먹을 생각이었던 게냐?",
  ui_story_5020_50200801_222_dialog_content = "......",
  ui_story_5020_50200801_223_dialog_content = "<color=#e8d9bb>타탁... 타탁... 타탁...</color>",
  ui_story_5020_50200801_224_dialog_content = "스승님, 츠키 님의 일을 후회하십니까?",
  ui_story_5020_50200801_225_dialog_content = "당연히 아니지. 내가 언제 뭘 후회한 적이 있더냐?",
  ui_story_5020_50200801_226_dialog_content = "그렇다면 어찌 장례에 대해서 물으셨습니까?",
  ui_story_5020_50200801_227_dialog_content = "......",
  ui_story_5020_50200801_228_dialog_content = "츠키를 죽인 것은 후회하지 않는다. 다만...",
  ui_story_5020_50200801_229_dialog_content = "츠키는 내 언니다. 장례는 내가 치러주는 것이 마땅한 일이 아니냐.",
  ui_story_5020_50200801_230_dialog_content = "......",
  ui_story_5020_50200801_231_dialog_content = "게다가 다른 일도 하나 있었다.",
  ui_story_5020_50200801_232_dialog_content = "「천운참」은 츠키의 검이니, 함께 부장되었을지도 모른다.",
  ui_story_5020_50200801_233_dialog_content = "참귀의 검은 쇼군에게는 필요치 않은 것이니 말이야.",
  ui_story_5020_50200801_234_dialog_content = "「천운참」을 찾으시려는 것입니까?",
  ui_story_5020_50200801_235_dialog_content = "그래.",
  ui_story_5020_50200801_236_dialog_content = "그 보검이 흙에 묻힌 걸 알면 츠키도 원통해서 울고 말 게다.",
  ui_story_5020_50200801_237_dialog_content = "<color=#e8d9bb>타탁... 타탁!</color>",
  ui_story_5020_50200801_238_dialog_content = "휴── 정말 오래간만에 올라오는구나!",
  ui_story_5020_50200801_239_dialog_content = "제자야, 밧줄을 풀거라.",
  ui_story_5020_50200801_240_dialog_content = "어디 이 집 술 빚는 솜씨가 10년 사이에 얼마나 늘었나 볼까!",
  ui_story_5020_50200801_241_dialog_content = "예.",
  ui_story_5020_50200801_242_dialog_content = "너는 술 마실 나이가 되었더냐?",
  ui_story_5020_50200801_243_dialog_content = "...저는 술을 마실 줄 모릅니다.",
  ui_story_5020_50200801_244_dialog_content = "재미없게.",
  ui_story_5020_50200801_245_dialog_content = "뭐, 되었다. 한 통은 나한테 주고, 나머지는 전부 <color=#FFB400>깨트려라</color>.",
  ui_story_5020_50200801_246_dialog_content = "예? 그건 어찌...",
  ui_story_5020_50200801_247_dialog_content = "깨라면 깰 것이지, 잔말이 많구나.",
  ui_story_5020_50200801_248_dialog_content = "...예.",
  ui_story_5020_50200801_249_dialog_content = "<color=#e8d9bb>쨍그랑!</color>",
  ui_story_5020_50200801_250_dialog_content = "<color=#e8d9bb>쨍그랑!</color>",
  ui_story_5020_50200801_251_dialog_content = "<color=#e8d9bb>쨍그랑!</color>",
  ui_story_5020_50200801_252_dialog_content = "하하하하, 잘한다!",
  ui_story_5020_50200801_253_dialog_content = "<anim type=Shake>꿀꺽... 꿀꺽...</anim>",
  ui_story_5020_50200801_254_dialog_content = "캬아──! 좋구나!",
  ui_story_5020_50200801_255_dialog_content = "<color=#e8d9bb>타탁... 타탁... 타탁...</color>",
  ui_story_5020_50200801_256_dialog_content = "스승님, 떨어지지 않게 조심하십시오.",
  ui_story_5020_50200801_257_dialog_content = "떨어질 리가 없잖아! 나를 누구라고 생각하는 것이냐!",
  ui_story_5020_50200801_258_dialog_content = "제자야, 성 아래를 보거라.",
  ui_story_5020_50200801_259_dialog_content = "지금 이쪽으로 오고 있는 게 누구더냐.",
  ui_story_5020_50200801_260_dialog_content = "......",
  ui_story_5020_50200801_261_dialog_content = "후지쿠모 쇼군입니다.",
  ui_story_5020_50200801_262_dialog_content = "뭘 하고 있는 것일까요?",
  ui_story_5020_50200801_263_dialog_content = "내가 말해주마. 원수는 서로를 가장 잘 이해하는 법이니 말이야.",
  ui_story_5020_50200801_264_dialog_content = "이렇게 멀리서도, 성을 사이에 두고 있어도, 나는 저놈이 무슨 생각을 하는지 알 수 있다.",
  ui_story_5020_50200801_265_dialog_content = "분명 지금 자신이 한 걸음 한 걸음 「평화」로 향하고 있다고 생각하고 있을 게다.",
  ui_story_5020_50200801_266_dialog_content = "어째서입니까?",
  ui_story_5020_50200801_267_dialog_content = "나도 그렇게 생각하기 때문이다.",
  ui_story_5020_50200801_268_dialog_content = "!!!",
  ui_story_5020_50200801_269_dialog_content = "스승님, 설마...",
  ui_story_5020_50200801_270_dialog_content = "혼자서 마시는 술은 재미가 없구나.",
  ui_story_5020_50200801_271_dialog_content = "제자가 거들어 주지 않는다니, 이 강부성이 대신 마셔주게 해야겠다!",
  ui_story_5020_50200901_1_dialog_content = "합하, 반란군의 주력은 이미 진압하였고, 지금 본성으로 호송하는 중입니다.",
  ui_story_5020_50200901_2_dialog_content = "좋다.",
  ui_story_5020_50200901_3_dialog_content = "촉유군의 비뚤어진 깃발이 오늘에서야 쓰러지는가.",
  ui_story_5020_50200901_4_dialog_content = "백성들에게 알려라. 성루 아래에서 죄인을 심판할 것이야.",
  ui_story_5020_50200901_5_dialog_content = "백성들이 근심으로 하룻밤을 보냈으니,\n누군가는 책임을 지고 이 소란에 종지부를 찍어야 하지 않겠느냐.",
  ui_story_5020_50200901_6_dialog_content = "날이 밝으면 춘일제도 거행해야 하니 말이다.",
  ui_story_5020_50200901_7_dialog_content = "예, 합하.",
  ui_story_5020_50200901_8_dialog_content = "<color=#e8d9bb>덜컹... 덜컹...</color>",
  ui_story_5020_50200901_9_dialog_content = "저기, 우리 진짜 조용한 곳으로 가는 거 맞아?",
  ui_story_5020_50200901_10_dialog_content = "어째 주변이 점점 더 시끄러워지는 것 같은데...",
  ui_story_5020_50200901_11_dialog_content = "어쩔 수 없어, PlayerName 씨.",
  ui_story_5020_50200901_12_dialog_content = "북을 가지고 가려니까 너무 눈에 띈단 말이야.\n인파에 섞여서 가는 수밖에 없어.",
  ui_story_5020_50200901_13_dialog_content = "...우리 지금 어디쯤이야?",
  ui_story_5020_50200901_14_dialog_content = "지금...",
  ui_story_5020_50200901_15_dialog_content = "본성에 거의 다 왔어.",
  ui_story_5020_50200901_16_dialog_content = "뭐야?! 그럼 제 발로 죽으러 가는 거잖아?!",
  ui_story_5020_50200901_17_dialog_content = "에이, 어떻게든 될 거라구!",
  ui_story_5020_50200901_18_dialog_content = "정 안 되면 춘일제가 끝날 때까지 숨어 있으면...",
  ui_story_5020_50200901_19_dialog_content = "우릴 죽일 작정이냐고오오!",
  ui_story_5020_50200901_20_dialog_content = "<size=45>길을 비켜라!</size>",
  ui_story_5020_50200901_21_dialog_content = "<size=45>앞을 막지 마라!</size>",
  ui_story_5020_50200901_22_dialog_content = "또 뭔데?",
  ui_story_5020_50200901_23_dialog_content = "무사들이 사람들을 잔뜩 데리고 왔어!",
  ui_story_5020_50200901_24_dialog_content = "어라? 저 사람들은...",
  ui_story_5020_50200901_25_dialog_content = "촉유군이야!",
  ui_story_5020_50200901_26_dialog_content = "촉유군이라고?!",
  ui_story_5020_50200901_27_dialog_content = "전부 잡혀버린 건가...",
  ui_story_5020_50200901_28_dialog_content = "응, 그런 것 같아...",
  ui_story_5020_50200901_29_dialog_content = "다들 본성으로 가고 있어.",
  ui_story_5020_50200901_30_dialog_content = "본성...? 쇼군은 그 사람들을 어쩔 생각인 거지...",
  ui_story_5020_50200901_31_dialog_content = "아마 오늘 밤 소동의 죄를 뒤집어씌워 성난 민심을 달래려 하겠지요.",
  ui_story_5020_50200901_32_dialog_content = "자기들을 위해 싸웠는데... 어떻게 그런...",
  ui_story_5020_50200901_33_dialog_content = "사람들이 그걸 믿을까요?",
  ui_story_5020_50200901_34_dialog_content = "오니를 언제 불러내고 거둘지는 쇼군의 뜻대로 정해질 뿐입니다.",
  ui_story_5020_50200901_35_dialog_content = "백성들에게는 촉유군이 잡힌 후 오니의 재앙이 물러가는 것만이 보일 뿐입니다.",
  ui_story_5020_50200901_36_dialog_content = "저들에게는 선택의 여지가 없지요. 그저 믿을 수밖에 없는 것입니다.",
  ui_story_5020_50200901_37_dialog_content = "근데 그러면...",
  ui_story_5020_50200901_38_dialog_content = "그렇게 된다면...",
  ui_story_5020_50200901_39_dialog_content = "어라...",
  ui_story_5020_50200901_40_dialog_content = "그러면 강부성에 더는 오니가 나타나지 않게 되는 거잖아요...?",
  ui_story_5020_50200901_41_dialog_content = "그렇게 생각하면... 좋은 일인 걸까요...?",
  ui_story_5020_50200901_42_dialog_content = "...응, 그렇겠지.",
  ui_story_5020_50200901_43_dialog_content = "그야말로 냉혹한 통치자 그 자체잖아.",
  ui_story_5020_50200901_44_dialog_content = "어떤 망설임도 없이 무언가를 희생시키고, 배신하지만...",
  ui_story_5020_50200901_45_dialog_content = "결국에는... 모든 게 더 좋아진 것처럼 보이게 되는 거지.",
  ui_story_5020_50200901_46_dialog_content = "......",
  ui_story_5020_50200901_47_dialog_content = "그렇게 「보일 뿐」이지요. 그렇지 않습니까?",
  ui_story_5020_50200901_48_dialog_content = "운도 사람들은 영혼을 중히 여깁니다.\n모두가 진심으로 영혼의 존재를 믿고 있는 것입니다.",
  ui_story_5020_50200901_49_dialog_content = "이 사태가 제 말대로 나아간다면, 백성들은 정말로 외환이 없는 환상 속에서 살 수 있겠지요.",
  ui_story_5020_50200901_50_dialog_content = "그러나 진상을 외면한 영혼의 죄업은 죽음과 무슨 차이가 있겠는지요.",
  ui_story_5020_50200901_51_dialog_content = "저는 백성들이 진상을 알게 된다면 아무도 받아들이지 않을 것이라 믿습니다.",
  ui_story_5020_50200901_52_dialog_content = "그렇네요! 모두를 거짓 속에 살게 만들 순 없어요!",
  ui_story_5020_50200901_53_dialog_content = "다들 진상을 알아야만 해요!",
  ui_story_5020_50200901_54_dialog_content = "......",
  ui_story_5020_50200901_55_dialog_content = "그래, 너희 말이 맞아.",
  ui_story_5020_50200901_56_dialog_content = "진상을 외면한 평화는 결코 평화라고 할 수 없어.",
  ui_story_5020_50200901_57_dialog_content = "우리가 모두에게 진상을 알려야만 해.",
  ui_story_5020_50200901_58_dialog_content = "<color=#e8d9bb>덜컹... 덜컹...</color>",
  ui_story_5020_50200901_59_dialog_content = "안즈, 모모, 촉유군의 호송 대열을 따라갈 수 있을까?",
  ui_story_5020_50200901_60_dialog_content = "따라간다고?",
  ui_story_5020_50200901_61_dialog_content = "그랬다간 정말로 도망칠 기회가 없을 거라구.",
  ui_story_5020_50200901_62_dialog_content = "도망 안 가. 가긴 어딜 간다고.",
  ui_story_5020_50200901_63_dialog_content = "모처럼 왔는데 춘일제를 놓칠 순 없잖아!",
  ui_story_5020_50200901_64_dialog_content = "죄인을 심판한다던데, 정말이야?",
  ui_story_5020_50200901_65_dialog_content = "진짜라니까, 쇼군의 명이라잖아!",
  ui_story_5020_50200901_66_dialog_content = "악귀를 불러낸 죄인한테 법의 심판을 내린대!",
  ui_story_5020_50200901_67_dialog_content = "저기 좀 봐, 지금 광장으로 가고 있어!",
  ui_story_5020_50200901_68_dialog_content = "잠깐만, 정말 저 사람들이야? 저기 내가 아는 사람도 많이 있다고!",
  ui_story_5020_50200901_69_dialog_content = "남 대신 붙잡혀 나온 사람들인지 누가 알겠어?",
  ui_story_5020_50200901_70_dialog_content = "쇼군 나리는 그런 수완 하나는 알아주잖아, 퉷.",
  ui_story_5020_50200901_71_dialog_content = "누구든 오늘 같은 소동을 벌였으면 비참한 벌을 받을 거라고...",
  ui_story_5020_50200901_72_dialog_content = "<color=#e8d9bb>퉁──</color>",
  ui_story_5020_50200901_73_dialog_content = "아뢰옵니다!",
  ui_story_5020_50200901_74_dialog_content = "역적의 도당 촉유군을 모조리 추포했습니다!",
  ui_story_5020_50200901_75_dialog_content = "부디 합하께서 역적들을 심판해 주십시오!",
  ui_story_5020_50200901_76_dialog_content = "내가 강부성에 온 지도 벌써 수십 년의 세월이 흘렀구나.",
  ui_story_5020_50200901_77_dialog_content = "그간 벌어진 추악한 싸움에 내 고회도 이루 말할 수 없었느니라.",
  ui_story_5020_50200901_78_dialog_content = "그러나 오늘날 마침내...",
  ui_story_5020_50200901_79_dialog_content = "「평화」의 빛이 보이는도다.",
  ui_story_5020_50200901_80_dialog_content = "「평화」...",
  ui_story_5020_50200901_81_dialog_content = "전란으로 강부성이 도탄에 빠질 때 나는 전란을 평정했고...",
  ui_story_5020_50200901_82_dialog_content = "오니의 재앙이 강부성을 덮칠 때 나는 무녀를 길렀다...",
  ui_story_5020_50200901_83_dialog_content = "그리하여 이 성에 가장 안온무사한 세월을 주었던 것이다.",
  ui_story_5020_50200901_84_dialog_content = "허나 자고로 만족을 모르는 자는 늘 있어 왔다.",
  ui_story_5020_50200901_85_dialog_content = "그자들은 내가 세운 질서를 짓밟고, 더 많은 것을 탐하려 했다!",
  ui_story_5020_50200901_86_dialog_content = "바로 그자들이 지금 우리의 앞에 있느니라.",
  ui_story_5020_50200901_87_dialog_content = "......",
  ui_story_5020_50200901_88_dialog_content = "역적 촉유군의 잔당들이여, 죄를 인정하느냐?",
  ui_story_5020_50200901_89_dialog_content = "죄?",
  ui_story_5020_50200901_90_dialog_content = "무슨 말인지 잘 모르겠는데.",
  ui_story_5020_50200901_91_dialog_content = "쇼군 나리가 가장 잘 알지 않겠어? 직접 말씀해 주시지 그래.",
  ui_story_5020_50200901_92_dialog_content = "좋다. 내 친히 알려주마.",
  ui_story_5020_50200901_93_dialog_content = "그대들은 악귀와 결탁하여 강부성을 혼란에 빠트렸다.",
  ui_story_5020_50200901_94_dialog_content = "이는 참형에 처할 죄이니라!",
  ui_story_5020_50200901_95_dialog_content = "쳇.",
  ui_story_5020_50200901_96_dialog_content = "후지쿠모, 네놈은...",
  ui_story_5020_50200901_97_dialog_content = "(저기, 화가 잔뜩 났을 텐데 끊어서 미안해.)",
  ui_story_5020_50200901_98_dialog_content = "(일단 좀 참고 시간을 벌어줄래?)",
  ui_story_5020_50200901_99_dialog_content = "(지금 당신들이 죽으면 나도 엄청 곤란하거든.)",
  ui_story_5020_50200901_100_dialog_content = "......",
  ui_story_5020_50200901_101_dialog_content = "(안즈랑 모모가 당신들을 풀어주러 갈 거야. 기회는 단 한 순간뿐이야.)",
  ui_story_5020_50200901_102_dialog_content = "(그 뒤에 당신들이 모든 무사를 단숨에 제압해야 돼. 안 그러면 우린 전부 끝장이야.)",
  ui_story_5020_50200901_103_dialog_content = "(내 말 알아들었으면 헛기침을 해.)",
  ui_story_5020_50200901_104_dialog_content = "크흠!",
  ui_story_5020_50200901_105_dialog_content = "(좋아, 그럼 연기를 계속해줘.)",
  ui_story_5020_50200901_106_dialog_content = "아, 저기... 쇼군 나리, 의논하고 싶은 게 하나 있는데 말이지.",
  ui_story_5020_50200901_107_dialog_content = "베는 건 괜찮은데, 참수형은 좀 피해 주면 안 되겠나?",
  ui_story_5020_50200901_108_dialog_content = "......",
  ui_story_5020_50200901_109_dialog_content = "팔이든 다리든 좋을 대로 잘라도 되니 말이야.",
  ui_story_5020_50200901_110_dialog_content = "난 머리가 좋거든. 아껴두면 쓸모가 많을 거라고.",
  ui_story_5020_50200901_111_dialog_content = "무사는 이쪽에 세 명, 저쪽에 다섯 명, 길 건너편에도 두 명이 있어.",
  ui_story_5020_50200901_112_dialog_content = "바이스, 기억했어?",
  ui_story_5020_50200901_113_dialog_content = "세 명... 다섯 명... 두 명...",
  ui_story_5020_50200901_114_dialog_content = "잘 기억해줘! 기회는 한 번뿐이야!",
  ui_story_5020_50200901_115_dialog_content = "안즈랑 모모가 북의 가죽을 풀어놨으니까, 이따가 우린 곧바로 뛰쳐나가면 돼.",
  ui_story_5020_50200901_116_dialog_content = "북에서 나가자마자 주위의 무사들을 동시에 전부 쓰러트려야 해!",
  ui_story_5020_50200901_117_dialog_content = "그래야 안즈랑 모모가 가서 촉유군을 풀어줄 수 있어.",
  ui_story_5020_50200901_118_dialog_content = "응! 세 명... 다섯 명...",
  ui_story_5020_50200901_119_dialog_content = "그렇다면 제가 해야 할 일은 쇼군의 움직임을 막는 것이겠지요.",
  ui_story_5020_50200901_120_dialog_content = "응, 최대한 상황을 통제할 수 없게 만드는 거야.",
  ui_story_5020_50200901_121_dialog_content = "쇼군이 오니를 조종해서 우릴 제압하려 들면, 그걸로 진상을 밝힐 수 있을 거야!",
  ui_story_5020_50200901_122_dialog_content = "그다음에는 무엇을 하시겠습니까? 어찌 도망칠 생각이신지요.",
  ui_story_5020_50200901_123_dialog_content = "거기까진 계획을 못 세웠어... 그건 그때 가서 보자!",
  ui_story_5020_50200901_124_dialog_content = "안즈, 모모, 준비됐어?",
  ui_story_5020_50200901_125_dialog_content = "응!",
  ui_story_5020_50200901_126_dialog_content = "밧줄을 끊고 나서 촉유군을 따라 도망치면 되는 거지?",
  ui_story_5020_50200901_127_dialog_content = "그래!",
  ui_story_5020_50200901_128_dialog_content = "근데 저 사람들 그렇게 강해 보이진 않는데...",
  ui_story_5020_50200901_129_dialog_content = "괜찮을까?",
  ui_story_5020_50200901_130_dialog_content = "위험한 상황이 생기면 어떻게든 우리에게 말해줘.",
  ui_story_5020_50200901_131_dialog_content = "예를 들면...",
  ui_story_5020_50200901_132_dialog_content = "그래. 우린 북이 있잖아.",
  ui_story_5020_50200901_133_dialog_content = "아하! 이해했어!",
  ui_story_5020_50200901_134_dialog_content = "북 치는 거 좋아~",
  ui_story_5020_50200901_135_dialog_content = "이제 바이스 너만 남았어...",
  ui_story_5020_50200901_136_dialog_content = "다 기억하고 있어!",
  ui_story_5020_50200901_137_dialog_content = "좋아!",
  ui_story_5020_50200901_138_dialog_content = "그럼 다들 준비해... 셋...",
  ui_story_5020_50200901_139_dialog_content = "<size=40>둘...</size>",
  ui_story_5020_50200901_140_dialog_content = "<size=45>하나...</size>",
  ui_story_5020_50200901_141_dialog_content = "<size=50>가자!</size>",
  ui_story_5020_50200901_142_dialog_content = "<color=#e8d9bb><size=50>콰아앙──!</size></color>",
  ui_story_5020_50200901_143_dialog_content = "속사 감지!",
  ui_story_5020_50200901_144_dialog_content = "얼른 구하러 가자! 빨리!",
  ui_story_5020_50200901_145_dialog_content = "알고 있다구!",
  ui_story_5020_50200901_146_dialog_content = "싸, 싸움이다! 사람 살려!",
  ui_story_5020_50200901_147_dialog_content = "형제들이여, 무기를 들어라!",
  ui_story_5020_50200901_148_dialog_content = "역적들이 풀려났다! 합하를 지켜라!",
  ui_story_5020_50200901_149_dialog_content = "<color=#e8d9bb>딸랑──</color>",
  ui_story_5020_50200901_150_dialog_content = "......",
  ui_story_5020_50200901_151_dialog_content = "......",
  ui_story_5020_50200901_152_dialog_content = "린네, 그런 선택은 하지 말았어야 했다.",
  ui_story_5020_50200901_153_dialog_content = "어째서인지요.",
  ui_story_5020_50200901_154_dialog_content = "그것은 틀린 것이기 때문이다.",
  ui_story_5020_50200901_155_dialog_content = "제게 가르쳐 주셨던 옳고 그름과 당신께서 믿고 계신 옳고 그름은...\n왠지 다른 것 같습니다만.",
  ui_story_5020_50200901_156_dialog_content = "네게 모든 것을 가르칠 수 있는 것은 아니었다. 너도 시간을 들여 이해했어야 했다.",
  ui_story_5020_50200901_157_dialog_content = "그럴 필요는 없게 되었습니다. 저는 이미 스스로의 옳고 그름을 배웠으니 말이지요.",
  ui_story_5020_50200901_158_dialog_content = "제 전임 무녀들, 당신께서 「옳다」고 여겼던 그 무녀들은 어떠한 말로를 맞이했는지요.",
  ui_story_5020_50200901_159_dialog_content = "네가 보고 있는 강부성은 저들이 만든 것이다.",
  ui_story_5020_50200901_160_dialog_content = "그렇습니까?",
  ui_story_5020_50200901_161_dialog_content = "그렇다면 저는 다른 강부성을 보고 싶습니다.",
  ui_story_5020_50200901_162_dialog_content = "지금처럼 허튼 행동을 통해서 말이냐?",
  ui_story_5020_50200901_163_dialog_content = "반란은 수없이 보아 왔다. 저들이 가져오는 것은 변혁이 아니라 파멸이다.",
  ui_story_5020_50200901_164_dialog_content = "당신께서 보지 못하셨던 것도 있을 것입니다.",
  ui_story_5020_50200901_165_dialog_content = "예를 들자면, 당신에게 칼을 겨누는 무녀가 있겠지요.",
  ui_story_5020_50200901_166_dialog_content = "네 칼날 따위는 아무래도 좋다.",
  ui_story_5020_50200901_167_dialog_content = "나는 그저 네가 분명하게 생각하길 바랄 뿐이다.",
  ui_story_5020_50200901_168_dialog_content = "저는 줄곧 제 적은 영원히 오니뿐이라고 생각하고 있었습니다.",
  ui_story_5020_50200901_169_dialog_content = "그러나 지금은 여기 서서 당신과 맞서고 있습니다.",
  ui_story_5020_50200901_170_dialog_content = "저는 처음으로 산 자에게 적의를 느꼈습니다.",
  ui_story_5020_50200901_171_dialog_content = "그 적의에 두려움을 느끼는 게 좋을 것이다.",
  ui_story_5020_50200901_172_dialog_content = "후훗.",
  ui_story_5020_50200901_173_dialog_content = "두려움이라기보다는 흥분에 가까운 듯싶습니다만.",
  ui_story_5020_50200902_1_dialog_content = "죽여라!",
  ui_story_5020_50200902_2_dialog_content = "무엄하다! 역적들!",
  ui_story_5020_50200902_3_dialog_content = "으아악! 사람이 죽었다!",
  ui_story_5020_50200902_4_dialog_content = "당황하지 마라!",
  ui_story_5020_50200902_5_dialog_content = "대열을 다시 갖추고 역적들을 포위해라!",
  ui_story_5020_50200902_6_dialog_content = "포위? 흥.",
  ui_story_5020_50200902_7_dialog_content = "아무래도 상황 파악을 제대로 못 하는 모양이군.",
  ui_story_5020_50200902_8_dialog_content = "오니가 없는 한 전세는 우리 것이다!",
  ui_story_5020_50200902_9_dialog_content = "가소롭구나.",
  ui_story_5020_50200902_10_dialog_content = "네놈들 촉유군은 사람이든 오니든 언제 한 번 이긴 적이라도 있단 말이더냐!",
  ui_story_5020_50200902_11_dialog_content = "이번에는 이길 것이다.",
  ui_story_5020_50200902_12_dialog_content = "어떡하지... 도망가야 하나?",
  ui_story_5020_50200902_13_dialog_content = "도망? 어디로 갈 수 있겠어?! 여길 떠나봤자 오니랑 마주칠 뿐이라고...",
  ui_story_5020_50200902_14_dialog_content = "오니도 사람을 죽이고, 사람도 사람을 죽인다니... 하...",
  ui_story_5020_50200902_15_dialog_content = "오늘은... 대체 얼마나 많은 목숨을 또 앗아가려 하는 것인가...",
  ui_story_5020_50200902_16_dialog_content = "<color=#e8d9bb>콰르릉──!</color>",
  ui_story_5020_50200902_17_dialog_content = "!!!",
  ui_story_5020_50200902_18_dialog_content = "!!!",
  ui_story_5020_50200902_19_dialog_content = "저건...",
  ui_story_5020_50200902_20_dialog_content = "드디어 때가 됐군요.",
  ui_story_5020_50200902_21_dialog_content = "「금운이 솟아 십방을 비추나니, 귀요는 머리를 숙이고, 정괴는 경배할지어다」",
  ui_story_5020_50200902_22_dialog_content = "......",
  ui_story_5020_50200902_23_dialog_content = "마침내 제게 구름의 거울의 진짜 용도를 가르쳐 주시는군요.",
  ui_story_5020_50200902_24_dialog_content = "내가 바라는 것은 예나 지금이나 평화뿐이다.",
  ui_story_5020_50200902_25_dialog_content = "그러나 그대들은 그 평화를 누리면서도, 정작 평화가 무엇인지조차 알지 못한다.",
  ui_story_5020_50200902_26_dialog_content = "내 더는 그대들을 가르치고 있을 시간이 없느니라.",
  ui_story_5020_50200902_27_dialog_content = "오늘 강부성의 평화를 기필코 실현시키겠다.",
  ui_story_5020_50200902_28_dialog_content = "그대들이 원하든, 원하지 않든 말이다.",
  ui_story_5020_50200902_29_dialog_content = "......",
  ui_story_5020_50200902_30_dialog_content = "......",
  ui_story_5020_50200902_31_dialog_content = "오...오니다! 오니가 나타났다!",
  ui_story_5020_50200902_32_dialog_content = "나리! 그만들 싸우고 오니를 물리쳐 주십시오!",
  ui_story_5020_50200902_33_dialog_content = "그만 싸워? 흥.",
  ui_story_5020_50200902_34_dialog_content = "놈들의 지원군이 온 것이다. 이 무사 놈들의 공세는 이제부터라고. 안 그런가?",
  ui_story_5020_50200902_35_dialog_content = "......",
  ui_story_5020_50200902_36_dialog_content = "여봐라.",
  ui_story_5020_50200902_37_dialog_content = "거리를 봉쇄하라.",
  ui_story_5020_50200902_38_dialog_content = "합하의 명이 있기 전까지는 그 누구도 이곳을 떠날 수 없다!",
  ui_story_5020_50200902_39_dialog_content = "뭐라고?!",
  ui_story_5020_50200902_40_dialog_content = "여길 떠날 수 없다니 그게 무슨 소리요! 오니가 온단 말이오!",
  ui_story_5020_50200902_41_dialog_content = "설마 당신들...",
  ui_story_5020_50200902_42_dialog_content = "형제들이여! 촉유군은 쇼군의 명 따위는 듣지 않는다!",
  ui_story_5020_50200902_43_dialog_content = "당장 길을 터서 백성들을 피신시켜라!",
  ui_story_5020_50200902_44_dialog_content = "예!",
  ui_story_5020_50200902_45_dialog_content = "서둘러! 다들 촉유군을 따라가자!",
  ui_story_5020_50200902_46_dialog_content = "거봐! 내가 말했잖아. 역시 믿을 수 있는 건 같은 운도 사람뿐이라고!",
  ui_story_5020_50200902_47_dialog_content = "이제야 확실해졌어! 쇼군이 오니와 한패였어!",
  ui_story_5020_50200902_48_dialog_content = "퉷! 인간의 탈을 쓴 짐승 같으니라고!",
  ui_story_5020_50200902_49_dialog_content = "거리를 봉쇄한다니요! 백성들을 해칠 작정이십니까?",
  ui_story_5020_50200902_50_dialog_content = "나는 지금 저들을 위해 질서를 수호하고 있는 것이다.",
  ui_story_5020_50200902_51_dialog_content = "질서를 따르는 자는 평화를 누릴 수 있고, 질서를 거스르는 자는 벌을 받아 마땅하다.",
  ui_story_5020_50200902_52_dialog_content = "오니로 질서를 세우겠다는 말씀이십니까?",
  ui_story_5020_50200902_53_dialog_content = "미치셨군요...",
  ui_story_5020_50200902_54_dialog_content = "인간과 오니는 그저 몸뚱이만 다른 것에 불과하다.",
  ui_story_5020_50200902_55_dialog_content = "천박해졌구나, 린네.",
  ui_story_5020_50200902_56_dialog_content = "......",
  ui_story_5020_50200902_57_dialog_content = "린네! 더는 상대하지 마!",
  ui_story_5020_50200902_58_dialog_content = "촉유군이 사람들을 데리고 포위를 뚫고 있어. 근데...",
  ui_story_5020_50200902_59_dialog_content = "적이 너무 많아! 저들만으로는 돌파할 수 없을 거야.",
  ui_story_5020_50200902_60_dialog_content = "...방법을 찾으셨는지요.",
  ui_story_5020_50200902_61_dialog_content = "응.",
  ui_story_5020_50200902_62_dialog_content = "네가 가서 도와줘.",
  ui_story_5020_50200902_63_dialog_content = "저 말입니까? 그럼 이쪽은 어찌 하실 생각이신지요.",
  ui_story_5020_50200902_64_dialog_content = "나랑 바이스가 쇼군을 막을게.",
  ui_story_5020_50200902_65_dialog_content = "뭐? 우리가?",
  ui_story_5020_50200902_66_dialog_content = "그래. 얼마나 버틸지는 모르겠지만... 그러니까 최대한 빨리 돌파해야 해.",
  ui_story_5020_50200902_67_dialog_content = "린네, 오니 퇴치라면 네가 적임자잖아. 너밖에 없어.",
  ui_story_5020_50200902_68_dialog_content = "저는 다만 여러분이...",
  ui_story_5020_50200902_69_dialog_content = "걱정할 거 없어! 괜찮으니까!",
  ui_story_5020_50200902_70_dialog_content = "시간이 없어! 얼른 가!",
  ui_story_5020_50200902_71_dialog_content = "...알겠습니다.",
  ui_story_5020_50200902_72_dialog_content = "여러분들도 부디 무리하지 말아 주십시오.",
  ui_story_5020_50200902_73_dialog_content = "...PlayerName, 정말 괜찮아?",
  ui_story_5020_50200902_74_dialog_content = "우리 둘이서 어떻게 쇼군을 상대해?",
  ui_story_5020_50200902_75_dialog_content = "못 해.",
  ui_story_5020_50200902_76_dialog_content = "<size=45>그럼 이제 끝장이잖아!</size>",
  ui_story_5020_50200902_77_dialog_content = "당황하지 마. 우리 둘만 있는 게 아니니까.",
  ui_story_5020_50200902_78_dialog_content = "지원군이 곧 올 거야.",
  ui_story_5020_50200902_79_dialog_content = "아이참, 또 막다른 골목이네!",
  ui_story_5020_50200902_80_dialog_content = "대체 뭐 하러 집을 이렇게 복잡하게 지어 놨어?",
  ui_story_5020_50200902_81_dialog_content = "이대로 헤매다가는 오늘 밤은 여기서 묵을 수밖에 없겠어...",
  ui_story_5020_50200902_82_dialog_content = "마실 물도 없고... 먹을 것도 없는데...",
  ui_story_5020_50200902_83_dialog_content = "게다가 엄청 덥잖아...",
  ui_story_5020_50200902_84_dialog_content = "응? 여기 원래 이렇게 더웠나?",
  ui_story_5020_50200902_85_dialog_content = "으아아아악!",
  ui_story_5020_50200902_86_dialog_content = "부, 불이야! 누구 없어?!",
  ui_story_5020_50200902_87_dialog_content = "안 돼... 이러면 여기 있을 수 없잖아. 얼른 도망가야지!",
  ui_story_5020_50200902_88_dialog_content = "<color=#e8d9bb>타탁... 타탁... 타탁...</color>",
  ui_story_5020_50200902_89_dialog_content = "뭐야! 또 막혔잖아!",
  ui_story_5020_50200902_90_dialog_content = "어떡하지... 창문으로 뛰어내려야 되나...",
  ui_story_5020_50200902_91_dialog_content = "엄청 높네!",
  ui_story_5020_50200902_92_dialog_content = "아, 안 돼... 여기서 뛰어내렸다간...",
  ui_story_5020_50200902_93_dialog_content = "으아아아!",
  ui_story_5020_50200902_94_dialog_content = "...별로 안 높은 것 같기도?!",
  ui_story_5020_50200902_95_dialog_content = "괜찮아... 머리부터 떨어지지만 않으면 문제 없어!",
  ui_story_5020_50200902_96_dialog_content = "간다...",
  ui_story_5020_50200902_97_dialog_content = "하나, 둘...",
  ui_story_5020_50200902_98_dialog_content = "세에엣!",
  ui_story_5020_50200902_99_dialog_content = "<anim type=Shake><size=45>와아아아아아아아아아아악!</size></anim>",
  ui_story_5020_50200902_100_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_5020_50200902_101_dialog_content = "아야얏... 내 엉덩이...",
  ui_story_5020_50200902_102_dialog_content = "요...요우?!",
  ui_story_5020_50200902_103_dialog_content = "그래!",
  ui_story_5020_50200902_104_dialog_content = "우와! 바이스! PlayerName!",
  ui_story_5020_50200902_105_dialog_content = "오랜만이야!",
  ui_story_5020_50200902_106_dialog_content = "저기... 나 좀 일으켜 줄래?",
  ui_story_5020_50200902_107_dialog_content = "...자, 내 손 잡아.",
  ui_story_5020_50200902_108_dialog_content = "PlayerName, 네가 말한 지원군이 요우였어?",
  ui_story_5020_50200902_109_dialog_content = "왠지 우리보다 요우가 더 도움이 필요하겠는데...",
  ui_story_5020_50200902_110_dialog_content = "으윽... 그래도 요우만 있는 건 아냐.",
  ui_story_5020_50200902_111_dialog_content = "비키시오!",
  ui_story_5020_50200902_112_dialog_content = "후지쿠모 쇼군, 오늘이야말로 네놈이 진 빚을 받아 가겠다.",
  ui_story_5020_50200902_113_dialog_content = "닌자여, 내 그대에게 빚진 것은 없을 터이거늘.",
  ui_story_5020_50200902_114_dialog_content = "네놈의 목숨을 운도에 갚아야 할 것이다.",
  ui_story_5020_50200902_115_dialog_content = "아메모리! 너도 와줬구나!",
  ui_story_5020_50200902_116_dialog_content = "소생은 줄곧 성루 위에 있었소.",
  ui_story_5020_50200902_117_dialog_content = "처음에는 방관하려 했으나, 그대들이 너무 약해서 참을 수가 없었소.",
  ui_story_5020_50200902_118_dialog_content = "참으로 재미있군.",
  ui_story_5020_50200902_119_dialog_content = "쥐새끼 몇 마리를 모은다고 내게 맞설 수 있으리라 생각하나?",
  ui_story_5020_50200902_120_dialog_content = "하하하하하하!",
  ui_story_5020_50200902_121_dialog_content = "쥐가 뭐 어때서? 쥐도 이빨이 있잖아?",
  ui_story_5020_50200902_122_dialog_content = "10년이든, 50년이든, 100년이든 계속 물어뜯게 해 봐라.",
  ui_story_5020_50200902_123_dialog_content = "아무리 높은 성도 결국 무너질 테니 말이다!",
  ui_story_5020_50200902_124_dialog_content = "서...성이 불타고 있어!",
  ui_story_5020_50200902_125_dialog_content = "맞아! 그래서 뛰어내린 거라구!",
  ui_story_5020_50200902_126_dialog_content = "후지쿠모, 이토록 아름다운 성을 본 적이 있나?",
  ui_story_5020_50200902_127_dialog_content = "이 성은 마을 한가운데 우뚝 솟아 하늘을 가리고 있었지.",
  ui_story_5020_50200902_128_dialog_content = "지금처럼 좋은 술과 불길이 있으니 비로소 아름답게 느껴지는구나.",
  ui_story_5020_50200902_129_dialog_content = "세상의 모든 것은 가장 아름다운 순간을 맞이하기 위해 태어나는 법.",
  ui_story_5020_50200902_130_dialog_content = "그야말로 최고의 결말이 아니겠나.",
  ui_story_5020_50200902_131_dialog_content = "「명토의 유검」...",
  ui_story_5020_50200902_132_dialog_content = "도망갈 리는 없다고 생각했다. 고작 자유만으로 만족할 자가 아니니 말이야.",
  ui_story_5020_50200902_133_dialog_content = "그대는 역시 지옥에서 나를 노리는 요사한 검이로다...",
  ui_story_5020_50200902_134_dialog_content = "후지쿠모, 한 가지 물어보고 싶은 게 있다.\n네가 보아 온 츠키는 언제 가장 아름다웠지?",
  ui_story_5020_50200902_135_dialog_content = "...그대는 츠키의 이름을 입에 올릴 자격이 없느니라.",
  ui_story_5020_50200902_136_dialog_content = "난 어렸을 때 츠키가 내게 노래를 가르쳐 줄 때가 가장 아름다웠다고 생각했다.",
  ui_story_5020_50200902_137_dialog_content = "그러다 나중에는 「무녀가 평화를 가져온다」고 말할 때의\n모습이 가장 아름다웠다는 생각이 들었지.",
  ui_story_5020_50200902_138_dialog_content = "지금은 내가 어찌 생각하는지 아는가?",
  ui_story_5020_50200902_139_dialog_content = "그만 닥치지 못할까!",
  ui_story_5020_50200902_140_dialog_content = "내 품에서 죽었을 때의 츠키가 가장 아름답더군.",
  ui_story_5020_50200902_141_dialog_content = "......",
  ui_story_5020_50200902_142_dialog_content = "그 아름다움에 나는 분노했고, 증오했다.",
  ui_story_5020_50200902_143_dialog_content = "그 아름다움이 너를 위한 것이었기 때문이다.",
  ui_story_5020_50200902_144_dialog_content = "10년의 시간이 흘렀다. 강부성의 통치자여.",
  ui_story_5020_50200902_145_dialog_content = "자, 승부를 겨루자.",
  ui_story_5020_50200902_146_dialog_content = "네가 날 죽이고 싶은 마음이 더 강할까.\n아니면 내가 널 죽이고 싶은 마음이 더 강할까.",
  ui_story_5020_50201001_1_dialog_content = "그대는 자격이 없다.",
  ui_story_5020_50201001_2_dialog_content = "그대는 츠키의 이름을 입에 담아서는 아니 될 자란 말이다.",
  ui_story_5020_50201001_3_dialog_content = "츠키가 이룬 아름다움을 짓밟은 것은 그대가 아니더냐.",
  ui_story_5020_50201001_4_dialog_content = "그대야말로 저승에 가서 츠키에게 사과해야 마땅한 것이다!",
  ui_story_5020_50201001_5_dialog_content = "!!!",
  ui_story_5020_50201001_6_dialog_content = "...후지쿠모, 너는 역시 미쳤구나. 완전히 미친 게야.",
  ui_story_5020_50201001_7_dialog_content = "더는 잃어선 아니 될 것이 없기 때문이겠지.",
  ui_story_5020_50201001_8_dialog_content = "......",
  ui_story_5020_50201001_9_dialog_content = "뭘 멍하니 있는 거냐, 제자들아.",
  ui_story_5020_50201001_10_dialog_content = "예, 스승님! 소생도 돕겠습니다!",
  ui_story_5020_50201001_11_dialog_content = "도우라는 게 아니다.",
  ui_story_5020_50201001_12_dialog_content = "너희는 어서 도망쳐라.",
  ui_story_5020_50201001_13_dialog_content = "...스승님, 허나...",
  ui_story_5020_50201001_14_dialog_content = "어서 가라!",
  ui_story_5020_50201001_15_dialog_content = "너희 애송이 놈들을 돌볼 틈이 없단 말이다!",
  ui_story_5020_50201001_16_dialog_content = "날 방해하지 마라!",
  ui_story_5020_50201001_17_dialog_content = "스승님...",
  ui_story_5020_50201001_18_dialog_content = "...네! 알겠어요!",
  ui_story_5020_50201001_19_dialog_content = "가자, 아메모리. 스승님은 반드시 이길 거야!",
  ui_story_5020_50201001_20_dialog_content = "......",
  ui_story_5020_50201001_21_dialog_content = "알겠습니다, 스승님.",
  ui_story_5020_50201001_22_dialog_content = "그래야지. 그래야 착한 제자들이지.",
  ui_story_5020_50201001_23_dialog_content = "「명토의 유검」, 남을 위해 몸을 던질 마음 따위가 있다니, 실로 놀라운지고.",
  ui_story_5020_50201001_24_dialog_content = "쳇, 난 그저 「명토의 유검」의 전설을 끝내고 싶지가 않을 뿐이야.",
  ui_story_5020_50201001_25_dialog_content = "오니 베기로 이름을 날린 검객이 인간이기를 포기한 최강의 오니와 싸우고...",
  ui_story_5020_50201001_26_dialog_content = "이제 그의 손에 죽었다는 전설을 남길 것이다.",
  ui_story_5020_50201001_27_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_5020_50201001_28_dialog_content = "엄청난 소리잖아...",
  ui_story_5020_50201001_29_dialog_content = "이게 정말... 두 사람이 싸우는 소리라고?",
  ui_story_5020_50201001_30_dialog_content = "도망친 건 현명한 선택이었어... 우린 애초에 상대가 아니었어.",
  ui_story_5020_50201001_31_dialog_content = "지금 성의 상황은 어떻소?",
  ui_story_5020_50201001_32_dialog_content = "린네는? 왜 너희랑 같이 안 있는 건데?",
  ui_story_5020_50201001_33_dialog_content = "아... 하나씩 말해줄게.",
  ui_story_5020_50201001_34_dialog_content = "쇼군이 오니를 불러와서 자기 무사들이랑 같이 강부성 사람들을 통제하려고 했어.",
  ui_story_5020_50201001_35_dialog_content = "마침 평민들이 전부 모여 있어서 다행이었어.\n지금 린네는 촉유군이랑 같이 포위를 돌파하려는 중이야.",
  ui_story_5020_50201001_36_dialog_content = "초규구이?",
  ui_story_5020_50201001_37_dialog_content = "촉유군이오!",
  ui_story_5020_50201001_38_dialog_content = "운도의 현지인이 결성한 군사 조직이오. 스승님과 소생도 그 일원이외다.",
  ui_story_5020_50201001_39_dialog_content = "아하!",
  ui_story_5020_50201001_40_dialog_content = "본래라면 그대도 우리의 일원일 터였소.",
  ui_story_5020_50201001_41_dialog_content = "그럼 촉유군은 착한 사람들이란 말이네?",
  ui_story_5020_50201001_42_dialog_content = "...그리 이해하고 싶다면 그렇게 하시오.",
  ui_story_5020_50201001_43_dialog_content = "허나 어째서 무녀가 촉유군과 함께 있는 것이오?",
  ui_story_5020_50201001_44_dialog_content = "인질로 잡힌 것인가?",
  ui_story_5020_50201001_45_dialog_content = "린네를 인질로 잡았다고?! 그럼 촉유군은 나쁜 놈들이잖아!",
  ui_story_5020_50201001_46_dialog_content = "아, 아니, 그게 아니고... 이런저런 일이 생겨서 린네랑 촉유군이 힘을 합쳤거든.",
  ui_story_5020_50201001_47_dialog_content = "지금은 일단 같은 편이라고 봐도 될 것 같아.",
  ui_story_5020_50201001_48_dialog_content = "촉유군과 무녀가 같은 편이라?",
  ui_story_5020_50201001_49_dialog_content = "상상조차 힘들군...",
  ui_story_5020_50201001_50_dialog_content = "음... 린네의 말을 빌리자면, 무녀의 적은 오니뿐이라고 했어.",
  ui_story_5020_50201001_51_dialog_content = "그러니까 지금 린네가 하는 일은 자기가 해야만 하는 일이란 얘기야.",
  ui_story_5020_50201001_52_dialog_content = "...좋소, 알겠소이다.",
  ui_story_5020_50201001_53_dialog_content = "그 녀석이 있다면 평민들도 일단은 안전하겠지.",
  ui_story_5020_50201001_54_dialog_content = "소생은 지금 물건을 하나 찾고 있소.",
  ui_story_5020_50201001_55_dialog_content = "뭔데?",
  ui_story_5020_50201001_56_dialog_content = "참귀의 검 「<color=#FFB400>천운참</color>」이오.",
  ui_story_5020_50201001_57_dialog_content = "스승님의 말씀대로라면... 그것이 이 전세를 뒤바꿀 수 있을지도 모르오.",
  ui_story_5020_50201001_58_dialog_content = "그거 촉유군한테 들은 적 있어! 무슨 전설의 무기 같은 거 맞지?",
  ui_story_5020_50201001_59_dialog_content = "근데 행방을 알 수 없다는 것 같던데...",
  ui_story_5020_50201001_60_dialog_content = "그 검은 전임 무녀와 함께 부장되었을 것이오.",
  ui_story_5020_50201001_61_dialog_content = "오! 단서를 찾았구나!",
  ui_story_5020_50201001_62_dialog_content = "근데... 그것만 가지고는 힘들지 않겠어?",
  ui_story_5020_50201001_63_dialog_content = "성 밖의 무덤을 모조리 뒤질 것이오.",
  ui_story_5020_50201001_64_dialog_content = "잠깐만! 그렇게 극단적일 필요는 없잖아!",
  ui_story_5020_50201001_65_dialog_content = "달리 방도가 있소? 어느 무덤이 전임 무녀의 것인지는 아무도 모르지 않소...",
  ui_story_5020_50201001_66_dialog_content = "저기...",
  ui_story_5020_50201001_67_dialog_content = "전임 무녀는 츠키 언니지?",
  ui_story_5020_50201001_68_dialog_content = "그렇소.",
  ui_story_5020_50201001_69_dialog_content = "기억이 난 것이오?",
  ui_story_5020_50201001_70_dialog_content = "응, 기억났어.",
  ui_story_5020_50201001_71_dialog_content = "그리고... 어디 묻혔는지도 기억해.",
  ui_story_5020_50201001_72_dialog_content = "뭐라?!",
  ui_story_5020_50201001_73_dialog_content = "그것이 사실인가?",
  ui_story_5020_50201001_73X1_dialog_content = "뭐라고?!",
  ui_story_5020_50201001_73X2_dialog_content = "너, 너... 그게 기억이 났다는 건 그럼...",
  ui_story_5020_50201001_73X3_dialog_content = "잃어버린 기억이 전부 돌아온 거야?",
  ui_story_5020_50201001_73X4_dialog_content = "응, 이제 전부 기억나.",
  ui_story_5020_50201001_73X5_dialog_content = "진짜 잘됐네!",
  ui_story_5020_50201001_73X6_dialog_content = "이런 상황에서 기억을 되찾을 줄은 몰랐지만...",
  ui_story_5020_50201001_73X7_dialog_content = "그래도 운도에 온 목적을 드디어 달성했잖아!",
  ui_story_5020_50201001_73X8_dialog_content = "헤헤, 그러게. 원래 목적은 달성했어!",
  ui_story_5020_50201001_73X9_dialog_content = "근데... 그렇게 기쁘지 않은 것 같아...",
  ui_story_5020_50201001_73X10_dialog_content = "하긴, 강부성도 저런 상황이니까...",
  ui_story_5020_50201001_73X11_dialog_content = "어떻게 기억을 되찾은 거야?",
  ui_story_5020_50201001_73X12_dialog_content = "스승님이 봉인된 운수각에서 벽장을 하나 발견했어.",
  ui_story_5020_50201001_73X13_dialog_content = "난 10년 전 거기서 기억을 잃은 거였어.",
  ui_story_5020_50201001_73X14_dialog_content = "츠키 언니가 날 벽장에 숨겼고, 그 안에서 난 스승님이 츠키 언니를 죽이는 걸 지켜봤어.",
  ui_story_5020_50201001_73X15_dialog_content = "그때 난 너무 무서웠고... 모든 게 이해가 안 돼서...",
  ui_story_5020_50201001_73X16_dialog_content = "그래서 모든 일을 머리에서 지워버렸던 거야.",
  ui_story_5020_50201001_73X17_dialog_content = "기쁘지 않다고 하는 이유가 있었구나...",
  ui_story_5020_50201001_73X18_dialog_content = "내가 줄곧 찾던 기억이 사실은 날 고통스럽게 했었고,\n내가 버렸던 것이라는 사실을 알고 나니까...",
  ui_story_5020_50201001_73X19_dialog_content = "내가 해온 모든 게... 무의미하게 느껴지는 것 같아.",
  ui_story_5020_50201001_73X20_dialog_content = "그리 여기지 마시오.",
  ui_story_5020_50201001_73X21_dialog_content = "그저 과거의 그대가 10년 후의 그대에게 기억을 맡겼을 뿐인 것이오.",
  ui_story_5020_50201001_73X22_dialog_content = "그대가 성장하여 고향으로 돌아와, 10년 전 피할 수 없었던 운명 앞에 다시 설 때까지...\n그 기억은 그대를 기다리고 있었을 것이오.",
  ui_story_5020_50201001_73X23_dialog_content = "어라...",
  ui_story_5020_50201001_73X24_dialog_content = "아메모리... 너 원래 그렇게 말을 잘하는 애였어?",
  ui_story_5020_50201001_73X25_dialog_content = "......",
  ui_story_5020_50201001_73X26_dialog_content = "묘지에 대해서도 그때 들은 것이오?",
  ui_story_5020_50201001_74_dialog_content = "응...",
  ui_story_5020_50201001_75_dialog_content = "쇼군이 한 말이 내 기억 속에 있었어.\n츠키 언니를 강부성의 <color=#FFB400>서쪽 산기슭</color>에 묻으라고 했어.",
  ui_story_5020_50201001_76_dialog_content = "강부성 서쪽 산기슭이라...",
  ui_story_5020_50201001_77_dialog_content = "알겠소.",
  ui_story_5020_50201001_78_dialog_content = "따라오시오. 성 밖으로 나갈 것이오.",
  ui_story_5020_50201001_79_dialog_content = "성 밖? 지금은 밖으로 나가기 쉽지 않을 텐데...",
  ui_story_5020_50201001_80_dialog_content = "놈들이 오고 있거든.",
  ui_story_5020_50201001_81_dialog_content = "!!!",
  ui_story_5020_50201001_82_dialog_content = "<color=#e8d9bb>콰아앙──!</color>",
  ui_story_5020_50201001_83_dialog_content = "<anim type=Shake>......</anim>",
  ui_story_5020_50201001_84_dialog_content = "<anim type=Shake>그 누구도... 이곳을... 떠날 수 없다!</anim>",
  ui_story_5020_50201002_1_dialog_content = "아빠, 아빠...",
  ui_story_5020_50201002_2_dialog_content = "<anim type=Shake>그어어어!</anim>",
  ui_story_5020_50201002_3_dialog_content = "흐윽...",
  ui_story_5020_50201002_4_dialog_content = "이야압!",
  ui_story_5020_50201002_5_dialog_content = "받아라!",
  ui_story_5020_50201002_6_dialog_content = "우와!",
  ui_story_5020_50201002_7_dialog_content = "야, 멋대로 다니면 안 돼. 지금은 위험하다구!",
  ui_story_5020_50201002_8_dialog_content = "얼른 사람들한테 돌아가!",
  ui_story_5020_50201002_9_dialog_content = "응, 알았어!",
  ui_story_5020_50201002_10_dialog_content = "근데 너희는?",
  ui_story_5020_50201002_11_dialog_content = "우린 할 일이 있거든!",
  ui_story_5020_50201002_12_dialog_content = "수다 떨 시간 없어, 안즈! 서둘러!",
  ui_story_5020_50201002_13_dialog_content = "<color=#e8d9bb>덜컹... 덜컹...</color>",
  ui_story_5020_50201002_14_dialog_content = "우와!",
  ui_story_5020_50201002_15_dialog_content = "그 커다란 북이잖아!",
  ui_story_5020_50201002_16_dialog_content = "헤헤, 대단하지?",
  ui_story_5020_50201002_17_dialog_content = "이걸 왜 가져가는데?",
  ui_story_5020_50201002_18_dialog_content = "이건 이제 우리 거거든!",
  ui_story_5020_50201002_19_dialog_content = "근데... 지금은 위험하다면서?",
  ui_story_5020_50201002_20_dialog_content = "이렇게 큰 북을 가지고 가려면 부담스럽지 않아?",
  ui_story_5020_50201002_21_dialog_content = "그럴 리가! 이걸로 우린 촉유군을 구출했다구!",
  ui_story_5020_50201002_22_dialog_content = "그래. 앞으로도 더 많은 사람을 구할 수 있을지도 몰라!",
  ui_story_5020_50201002_23_dialog_content = "<color=#e8d9bb>터벅... 터벅... 터벅...</color>",
  ui_story_5020_50201002_24_dialog_content = "대장, 이쪽을 돌파하는 건 무리일 것 같습니다!",
  ui_story_5020_50201002_25_dialog_content = "다들 지쳤습니다! 정면으로 싸워도 승산은 없습니다...",
  ui_story_5020_50201002_26_dialog_content = "방향을 바꾸는 게 어떻겠습니까?",
  ui_story_5020_50201002_27_dialog_content = "안 된다. 이대로는 바로 적에게 포위돼 버릴 거다.",
  ui_story_5020_50201002_28_dialog_content = "무슨 일이 있어도 활로를 열어야 한다!",
  ui_story_5020_50201002_29_dialog_content = "하지만...",
  ui_story_5020_50201002_30_dialog_content = "알고 있다. 밤새 싸워서 모두 지칠 대로 지쳤겠지.",
  ui_story_5020_50201002_31_dialog_content = "하지만 오늘 싸움은 이전과는 다르다.",
  ui_story_5020_50201002_32_dialog_content = "이 싸움에 걸린 건 우리 목숨만이 아니다. 운도의 운명이 걸려 있단 말이다.",
  ui_story_5020_50201002_33_dialog_content = "그러니 우리에게 포기할 권리는 없다.",
  ui_story_5020_50201002_34_dialog_content = "죽어서 귀신이 되더라도 함께 싸우는 거다!",
  ui_story_5020_50201002_35_dialog_content = "<color=#e8d9bb>딸랑──</color>",
  ui_story_5020_50201002_36_dialog_content = "당신들이 귀신이 되도록 누가 허락한답니까?",
  ui_story_5020_50201002_37_dialog_content = "제 일거리를 늘리는 것은 곤란합니다만.",
  ui_story_5020_50201002_38_dialog_content = "무녀?!",
  ui_story_5020_50201002_39_dialog_content = "어째서 우리한테 온 거지?",
  ui_story_5020_50201002_40_dialog_content = "PlayerName 님께서 당신들에게 진 빚을...",
  ui_story_5020_50201002_41_dialog_content = "제가 대신 갚으러 왔습니다.",
  ui_story_5020_50201002_42_dialog_content = "......",
  ui_story_5020_50201002_43_dialog_content = "좋다.",
  ui_story_5020_50201002_44_dialog_content = "귀신을 퇴치하는 일이라면 무녀를 믿도록 하지.",
  ui_story_5020_50201002_45_dialog_content = "전쟁의 전술에 대해서는 저도 당신들을 믿겠습니다.",
  ui_story_5020_50201002_46_dialog_content = "그렇다면 이제 촉유군이 얼마나 의지할 수 있는 자들인지 알게 될 것이다.",
  ui_story_5020_50201002_47_dialog_content = "전원! 전력을 다해 적의 포위를 돌파한다!",
  ui_story_5020_50201002_48_dialog_content = "평민들을 데리고 「<color=#FFB400>항구</color>」로 진격한다!",
  ui_story_5020_50201002_49_dialog_content = "<anim type=Shake>크윽...</anim>",
  ui_story_5020_50201002_50_dialog_content = "후회하는가, 나기여?",
  ui_story_5020_50201002_51_dialog_content = "후회? 그런 단어도 있었던가.",
  ui_story_5020_50201002_52_dialog_content = "그대처럼 강인한 전사는 자신의 죽음을 어찌 상상했을지 궁금하구나.",
  ui_story_5020_50201002_53_dialog_content = "그거라면 10년 전에 딱 한 번 생각해 봤었지.",
  ui_story_5020_50201002_54_dialog_content = "츠키와 함께 죽는 것이었다.",
  ui_story_5020_50201002_55_dialog_content = "허나 츠키는 그대를 살렸지.",
  ui_story_5020_50201002_56_dialog_content = "그대는 츠키에게 갚을 수 없는 빚을 졌느니라.",
  ui_story_5020_50201002_57_dialog_content = "내세에는 츠키의 아우로 태어나지 말거라.",
  ui_story_5020_50201002_58_dialog_content = "쿨럭... 하하하...",
  ui_story_5020_50201002_59_dialog_content = "내세라니... 네놈의 입에서 그런 말이 나오다니 정말 가엾구나.",
  ui_story_5020_50201002_60_dialog_content = "네놈에겐 인간의 마음이 얼마나 더 남아 있지?",
  ui_story_5020_50201002_61_dialog_content = "누가 네놈의 썩어 문드러진 영혼을... 제도할 수 있겠냔 말이다.",
  ui_story_5020_50201002_62_dialog_content = "......",
  ui_story_5020_50201002_63_dialog_content = "나는 내 말로가 이러할 것을 알고 있었다.",
  ui_story_5020_50201002_64_dialog_content = "인간의 마음? 그런 것 따위는 진즉 츠키와 함께 죽었다.",
  ui_story_5020_50201002_65_dialog_content = "그저 오니가 될 뿐이지 않은가. 인간으로서 가질 수 있는 것 따위에 미련은 없다.",
  ui_story_5020_50201002_66_dialog_content = "그것도 그렇겠지...",
  ui_story_5020_50201002_67_dialog_content = "취설각에 앉아 천수를 다하는 것은... 네게 결코 있어선 안 될 말로다.",
  ui_story_5020_50201002_68_dialog_content = "네놈은 평온한 죽음을 맞을 자격 따윈 없으니 말이다.",
  ui_story_5020_50201002_69_dialog_content = "내가 가여울 것이 뭐가 있겠느냐.",
  ui_story_5020_50201002_70_dialog_content = "나는 전사로서 전장에 나섰고, 이제 다른 강한 전사를 꺾고 승리했다.",
  ui_story_5020_50201002_71_dialog_content = "후지쿠모... 정말 그렇게 생각하나?",
  ui_story_5020_50201002_72_dialog_content = "우리들의 전장은... 10년 전에 있을 뿐이다...",
  ui_story_5020_50201002_73_dialog_content = "10년이나 그대의 목숨을 벌어준 것을 츠키에게 감사하거라.",
  ui_story_5020_50201002_74_dialog_content = "너야말로 잊지 마라... 이 전장이 왜 오늘 다시 펼쳐진 것인지를...",
  ui_story_5020_50201002_75_dialog_content = "......",
  ui_story_5020_50201002_76_dialog_content = "이 전장에 있는 전사는... 이제 우리뿐만이 아니야!",
  ui_story_5020_50201002_77_dialog_content = "<anim type=Shake>하하... 하..,</anim>",
  ui_story_5020_50201002_78_dialog_content = "<size=45><anim type=Shake>하하하하!</anim></size>",
  ui_story_5020_50201101_1_dialog_content = "<anim type=Shake>끄억...</anim>",
  ui_story_5020_50201101_2_dialog_content = "후우...",
  ui_story_5020_50201101_3_dialog_content = "전부 오니 무사인가...",
  ui_story_5020_50201101_4_dialog_content = "후지쿠모 놈, 이번엔 진정 몰살할 작정이로군.",
  ui_story_5020_50201101_5_dialog_content = "얼마든지 해보라고 해! 전부 쓰러트려 줄 테니까!",
  ui_story_5020_50201101_6_dialog_content = "흐아압──! 석추침해!",
  ui_story_5020_50201101_7_dialog_content = "<anim type=Shake>그으윽...</anim>",
  ui_story_5020_50201101_8_dialog_content = "<size=45><anim type=Shake>그어어어!</anim></size>",
  ui_story_5020_50201101_9_dialog_content = "여, 역시... 이 오니들을 전부 없애는 것은 무리요!",
  ui_story_5020_50201101_10_dialog_content = "그런 일이 가능한 자는 오직 린네뿐일 것이오.",
  ui_story_5020_50201101_11_dialog_content = "<size=45><anim type=Shake>그어어억!</anim></size>",
  ui_story_5020_50201101_12_dialog_content = "흐아압──",
  ui_story_5020_50201101_13_dialog_content = "할 수 있을지 없을지가 중요한 게 아니잖아! 일단 쓰러트리고 나서 말해!",
  ui_story_5020_50201101_14_dialog_content = "천인합일, 파죽지세!",
  ui_story_5020_50201101_15_dialog_content = "<anim type=Shake>끄억...</anim>",
  ui_story_5020_50201101_16_dialog_content = "자, 잠깐만...",
  ui_story_5020_50201101_17_dialog_content = "PlayerName, 성 쪽을 봐!",
  ui_story_5020_50201101_18_dialog_content = "!!!",
  ui_story_5020_50201101_19_dialog_content = "<size=45><anim type=Shake>크오오오──!</anim></size>",
  ui_story_5020_50201101_20_dialog_content = "어, 어째서...!",
  ui_story_5020_50201101_21_dialog_content = "...불길을 피해 본성에서 탈출한 녀석들 같소.",
  ui_story_5020_50201101_22_dialog_content = "단 하루 사이에 이토록 많은 오니 무사를 불러내다니...",
  ui_story_5020_50201101_23_dialog_content = "놈은 필시 오늘만을 기다리고 모든 것을 준비했을 것이오.",
  ui_story_5020_50201101_24_dialog_content = "...에잇!",
  ui_story_5020_50201101_25_dialog_content = "서둘러 사카이 거리를 벗어나야 하오. 여기서 놈들을 뿌리치는 것이오.",
  ui_story_5020_50201101_26_dialog_content = "<color=#e8d9bb>강부성 교외, 묘지 근처</color>",
  ui_story_5020_50201101_27_dialog_content = "앗...!",
  ui_story_5020_50201101_28_dialog_content = "PlayerName, 내 기억이 조금 더 돌아왔어!",
  ui_story_5020_50201101_29_dialog_content = "아무래도 나 여기 와봤던 것 같아!",
  ui_story_5020_50201101_30_dialog_content = "그것도 너한텐 확실히 기억이라고 할 수 있겠네...",
  ui_story_5020_50201101_31_dialog_content = "여긴 우리가 린네랑 아메모리를 처음 만난 곳이잖아!",
  ui_story_5020_50201101_32_dialog_content = "맞아. 우리가 운도에 막 불시착하고 나서...",
  ui_story_5020_50201101_32X_dialog_content = "저 앞의 대나무숲에서 린네 씨를 만났고...",
  ui_story_5020_50201101_33_dialog_content = "아메모리 씨랑 요란한 첫 만남도 있었고 말이야!",
  ui_story_5020_50201101_34_dialog_content = "......",
  ui_story_5020_50201101_35_dialog_content = "아! 그렇네, 어쩐지 익숙하다 싶더라니까!",
  ui_story_5020_50201101_36_dialog_content = "...「논과 마을을 따라 흐르는 이 강과 함께 서쪽 산기슭으로 가면 묘지에 도착할 수 있다」...",
  ui_story_5020_50201101_37_dialog_content = "내 기억대로라면 이쪽이 확실해!",
  ui_story_5020_50201101_38_dialog_content = "야, 아메모리. 지금부터는 날 방해하면 안 돼.",
  ui_story_5020_50201101_39_dialog_content = "웃기는군. 그건 소생이 할 말이외다.",
  ui_story_5020_50201101_40_dialog_content = "천운참은 참귀의 검이오. 우리가 후지쿠모에게 맞설 수 있는 비장의 무기란 말이오.",
  ui_story_5020_50201101_41_dialog_content = "소생도 그대의 도움 따위는 바라지 않소. 부디 방해만 하지 않길 바랄 뿐이오.",
  ui_story_5020_50201101_42_dialog_content = "잠깐만, 너... 그게 무슨 말이야?",
  ui_story_5020_50201101_43_dialog_content = "천운참을 멋대로 가져갈 생각이야?",
  ui_story_5020_50201101_44_dialog_content = "그렇소이다.",
  ui_story_5020_50201101_45_dialog_content = "그, 근데... 그게 네 것도 아니잖아? 천운참은...",
  ui_story_5020_50201101_46_dialog_content = "그 무녀 언니가 남긴 물건이잖아!",
  ui_story_5020_50201101_47_dialog_content = "그게 무슨 상관이란 말이오. 무고한 강부성 백성들의 안위가 걸린 문제요.",
  ui_story_5020_50201101_48_dialog_content = "우와, 그 와중에 엄청 당당하네!",
  ui_story_5020_50201101_49_dialog_content = "만약 스승님이 그 무녀를 싫어하시는 게 아니었어도 그럴 생각이야?",
  ui_story_5020_50201101_50_dialog_content = "(역시 이 두 제자들은 정말 정반대의 성격이란 말이지...)",
  ui_story_5020_50201101_51_dialog_content = "너희... 지금은 싸울 때가 아니잖아!",
  ui_story_5020_50201101_52_dialog_content = "...어라?",
  ui_story_5020_50201101_53_dialog_content = "이건...",
  ui_story_5020_50201101_54_dialog_content = "우와... 눈인가?",
  ui_story_5020_50201101_55_dialog_content = "아니오, 이것은 눈이 아니라...",
  ui_story_5020_50201101_56_dialog_content = "<color=#FFB400>하얀 벚꽃</color>?",
  ui_story_5020_50201101_57_dialog_content = "새하얀 작은 꽃잎들이 흩날려서... 정말 눈이 내리는 것처럼 보여!",
  ui_story_5020_50201101_58_dialog_content = "「운도 사람들은 요염한 색채와 함께 한가득 피어나는 벚꽃의 모습을 좋아한다」...",
  ui_story_5020_50201101_59_dialog_content = "어라? 이건 여행 가이드북 설명이랑 다르잖아!",
  ui_story_5020_50201101_60_dialog_content = "이러한 벚꽃은 아마 운도에서도 이곳밖에 볼 수 없을 것이오...",
  ui_story_5020_50201101_61_dialog_content = "묘지에 거의 다 온 것 같소.",
  ui_story_5020_50201101_62_dialog_content = "으음... 어쩐지... 아까보다 훨씬 조용해진 것 같더라니...",
  ui_story_5020_50201101_63_dialog_content = "<anim type=Shake>그어어...</anim>",
  ui_story_5020_50201101_64_dialog_content = "으엑... 설마, 아니겠지...",
  ui_story_5020_50201101_65_dialog_content = "<anim type=Shake>그어어어!</anim>",
  ui_story_5020_50201101_66_dialog_content = "정말 너무하네!",
  ui_story_5020_50201101_67_dialog_content = "근데 다시 생각해 보니까 묘지 근처에 오니가 있는 것도 정상이지 않을까...",
  ui_story_5020_50201101_68_dialog_content = "수다 떨고 있을 때가 아냐! 그럼 이 대협객이 또 솜씨를 발휘할 차례라고!",
  ui_story_5020_50201201_1_dialog_content = "속사 감지!",
  ui_story_5020_50201201_2_dialog_content = "<anim type=Shake>끄억...</anim>",
  ui_story_5020_50201201_3_dialog_content = "후... 귀찮아!",
  ui_story_5020_50201201_4_dialog_content = "정말 줄줄이 사탕도 아니고 뭐야 이게!",
  ui_story_5020_50201201_5_dialog_content = "...그건 또 어디서 나온 말이야?!",
  ui_story_5020_50201201_6_dialog_content = "우리 언니가 가르쳐 줬어! 언니는 말싸움도 잘하거든. 린 가문에서 이길 사람이 없다구!",
  ui_story_5020_50201201_7_dialog_content = "물론 싸움에서 이길 수 있는 사람도 거의 없고 말이야!",
  ui_story_5020_50201201_8_dialog_content = "뭔가 대단한 사람인 모양이네...",
  ui_story_5020_50201201_9_dialog_content = "그랬군. 어쩐지.",
  ui_story_5020_50201201_10_dialog_content = "응? 뭐가 「어쩐지」야? 아하, 내가 왜 대단한지 알겠다는 거지?",
  ui_story_5020_50201201_11_dialog_content = "어쩐지 그렇게 경솔하고 칠칠맞지 못하다 했소.",
  ui_story_5020_50201201_12_dialog_content = "스승님께서 열과 성을 다해 주신 가르침을 헛되게 만들다니.",
  ui_story_5020_50201201_13_dialog_content = "하아──? 너 그 말 어디 다시 해 봐!",
  ui_story_5020_50201201_14_dialog_content = "PlayerName, 너도 들었지? 저게 사저란 사람이 사매한테 할 말이야?",
  ui_story_5020_50201201_15_dialog_content = "자, 자, 요우 너도 그만하면 됐어.",
  ui_story_5020_50201201_16_dialog_content = "아메모리 너도. 그러게 왜 요우를 건드리고 그래?",
  ui_story_5020_50201201_17_dialog_content = "뭐?! 「건드려」?",
  ui_story_5020_50201201_18_dialog_content = "그럼 내가 괜한 걸 발끈하기라도 했다는 거야?!",
  ui_story_5020_50201201_19_dialog_content = "내가 별일도 아닌데 발끈했다 이거냐고!",
  ui_story_5020_50201201_20_dialog_content = "(이런, 말을 잘못했네...!)",
  ui_story_5020_50201201_21_dialog_content = "미리 말해두겠는데...",
  ui_story_5020_50201201_22_dialog_content = "소생은 무덤 속의 천운참을 어떻게 해서든 손에 넣을 것이오.",
  ui_story_5020_50201201_23_dialog_content = "그대가 다른 이유를 들어 날 방해하는 것은 넘어가 줄 수 있소...",
  ui_story_5020_50201201_24_dialog_content = "그대는 처음에는 스승님조차 기억하지 못했고, 자기 의자매밖에 몰랐으니 말이오.",
  ui_story_5020_50201201_25_dialog_content = "허나 소생은 어려서부터 스승님의 손에 자랐소.",
  ui_story_5020_50201201_26_dialog_content = "스승님께서 후지쿠모를 쓰러트리는 데 도움을 드릴 수 있다면...\n천운참은 반드시 소생이 가져갈 것이외다.",
  ui_story_5020_50201201_27_dialog_content = "(비록 스승님께선 소생에게 아무런 요구도 하지 않으셨지만...)",
  ui_story_5020_50201201_28_dialog_content = "그럼 성을 불태우는 계획도 미리 안 말해주신 거야?",
  ui_story_5020_50201201_29_dialog_content = "으음...",
  ui_story_5020_50201201_30_dialog_content = "스승님께는 스승님의 생각이 있기 마련이오!",
  ui_story_5020_50201201_31_dialog_content = "스승님도 물론 자기 생각이 있으시겠지. 근데 넌 스승님을 얼마나 아는데?",
  ui_story_5020_50201201_32_dialog_content = "?!",
  ui_story_5020_50201201_33_dialog_content = "설마... 소생이 모르는 무언가라도 생각이 난 것이오?!",
  ui_story_5020_50201201_34_dialog_content = "...난 내가 아는 건 이미 전부 말했어.",
  ui_story_5020_50201201_35_dialog_content = "하지만 그 천운참의 소유자는 스승님한테 분명히 특별한 존재였을 거야.",
  ui_story_5020_50201201_36_dialog_content = "......",
  ui_story_5020_50201201_37_dialog_content = "확실히... 소생은 잘 모르겠소...",
  ui_story_5020_50201201_37X_dialog_content = "스승님처럼 명예를 중히 여기시는 분께서...\n왜 친히 그 손을 더럽히셨어야 했는지...",
  ui_story_5020_50201201_38_dialog_content = "흥, 그것뿐만이 아냐...",
  ui_story_5020_50201201_39_dialog_content = "내 기억 속 그 무녀 언니는 분명히 무척 중요한 사람이었어. 느낄 수 있다구.",
  ui_story_5020_50201201_40_dialog_content = "그것을 어찌 안단 말이오.",
  ui_story_5020_50201201_41_dialog_content = "...직감이야!",
  ui_story_5020_50201201_42_dialog_content = "......",
  ui_story_5020_50201201_43_dialog_content = "그 표정은 뭔데?! 내 직감은 아주 잘 맞는단 말이야!",
  ui_story_5020_50201201_44_dialog_content = "그건... 내가 보장할게.",
  ui_story_5020_50201201_45_dialog_content = "네가 믿든 안 믿든 천운참은 내가 꼭 가져갈 거야.",
  ui_story_5020_50201201_46_dialog_content = "그걸 보면 분명히 더 많은 게 다시 생각날 테니까.",
  ui_story_5020_50201201_47_dialog_content = "스승님에 대한 일 말이야!",
  ui_story_5020_50201201_48_dialog_content = "아무튼 그러니까 나도 네 도움 같은 건 필요 없어. 방해하지나 말아줘!",
  ui_story_5020_50201201_49_dialog_content = "......",
  ui_story_5020_50201201_50_dialog_content = "...으음?",
  ui_story_5020_50201201_51_dialog_content = "<color=#e8d9bb>휘익──</color>",
  ui_story_5020_50201201_52_dialog_content = "...에잇!",
  ui_story_5020_50201201_53_dialog_content = "<anim type=Shake>그어어...</anim>",
  ui_story_5020_50201201_54_dialog_content = "소생에게 기습이라니, 요우가 열이 와도 모자라다.",
  ui_story_5020_50201201_55_dialog_content = "후후~ 맞아!",
  ui_story_5020_50201201_55X_dialog_content = "...잠깐만, 잘 생각해 보니까 칭찬이 아닌 것 같기도 하고...",
  ui_story_5020_50201201_56_dialog_content = "<anim type=Shake>그어어!</anim>",
  ui_story_5020_50201201_57_dialog_content = "<size=45><anim type=Shake>그어어어!</anim></size>",
  ui_story_5020_50201201_58_dialog_content = "서로 도와줄지 말지는 일단 넘어가고, 적어도 지금은...",
  ui_story_5020_50201201_59_dialog_content = "흐아압!",
  ui_story_5020_50201201_60_dialog_content = "<anim type=Shake>끄억...</anim>",
  ui_story_5020_50201201_61_dialog_content = "먼저 이 오니들부터 없애버리자구!",
  ui_story_5020_50201201_62_dialog_content = "흥, 그대가 말하지 않아도 알고 있소이다.",
  ui_story_5020_50201202_1_dialog_content = "<anim type=Shake>끄으윽...</anim>",
  ui_story_5020_50201202_2_dialog_content = "흥, 별것도 아니네!",
  ui_story_5020_50201202_3_dialog_content = "모두 조심하시오. 묘지 안에는 더 많은 오니들이 배회하고 있을 것이오.",
  ui_story_5020_50201202_4_dialog_content = "소생이 먼저 상황을 살피고 오겠소.",
  ui_story_5020_50201202_5_dialog_content = "그럼 부탁할게!",
  ui_story_5020_50201202_6_dialog_content = "...흡!",
  ui_story_5020_50201202_7_dialog_content = "<color=#e8d9bb>휘이잉── 휘이잉──</color>",
  ui_story_5020_50201202_8_dialog_content = "뭔가 불안하네... 너무 조용하잖아.",
  ui_story_5020_50201202_9_dialog_content = "겁낼 거 없어! 내 주먹으로 해결 못 할 건 없으니까!",
  ui_story_5020_50201202_10_dialog_content = "으음...?",
  ui_story_5020_50201202_11_dialog_content = "...아메모리?!",
  ui_story_5020_50201202_12_dialog_content = "뭔가 이상하오...",
  ui_story_5020_50201202_13_dialog_content = "뭐가 이상한데? 아메모리! 괜찮아?!",
  ui_story_5020_50201202_14_dialog_content = "...모두 들어오시오.",
  ui_story_5020_50201202_15_dialog_content = "묘지 안에는 오니가 한 마리도 없소이다.",
  ui_story_5020_50201202_16_dialog_content = "뭐라고...?",
  ui_story_5020_50201202_17_dialog_content = "안심해도 좋소. 이곳은 확실히 안전하니 말이오.",
  ui_story_5020_50201202_18_dialog_content = "소생이 정신을 집중하고 숨을 죽여도...",
  ui_story_5020_50201202_19_dialog_content = "들리는 것은 벚꽃이 떨어지는 소리뿐이오.",
  ui_story_5020_50201202_20_dialog_content = "이 벚꽃이란 것은 다른 꽃들처럼 한 번에 피어나는 것이 아니오...",
  ui_story_5020_50201202_21_dialog_content = "녀석은 유유히 꽃잎을 뻗으며 피어나는 순간의 아픔과 기쁨을 참소이다.",
  ui_story_5020_50201202_22_dialog_content = "떨어지는 때는 다른 꽃보다 훨씬 더 조용하오.",
  ui_story_5020_50201202_23_dialog_content = "벚꽃은 인내심이 강한 꽃이오. 그래서 스승님께서 좋아하셨던 것이겠지.",
  ui_story_5020_50201202_24_dialog_content = "오오... 그런 말은 여행 가이드북에서는 못 봤어!",
  ui_story_5020_50201202_25_dialog_content = "왠지는 모르겠지만, 조금 슬픈 기분이 드는걸...",
  ui_story_5020_50201202_26_dialog_content = "어라? 근데...",
  ui_story_5020_50201202_27_dialog_content = "여기 왠지 사람이 아예 안 왔던 건 아닌 것 같아...",
  ui_story_5020_50201202_28_dialog_content = "PlayerName, 봐!",
  ui_story_5020_50201202_29_dialog_content = "아...",
  ui_story_5020_50201202_30_dialog_content = "벚꽃잎을 쓸어서 길을 낸 자국이 있어...",
  ui_story_5020_50201202_31_dialog_content = "...누가 먼저 왔단 말인가?!",
  ui_story_5020_50201202_32_dialog_content = "이런! 설마 천운참을...",
  ui_story_5020_50201202_33_dialog_content = "아...",
  ui_story_5020_50201202_34_dialog_content = "우와... 이게 바로 그...",
  ui_story_5020_50201202_35_dialog_content = "과연 전설의 검이란 말인가.",
  ui_story_5020_50201202_36_dialog_content = "물이 흐르는 듯한 검신... 칼끝의 설계도 고풍스럽군...",
  ui_story_5020_50201202_37_dialog_content = "오랜 세월이 흘렀는데도 온전히 이곳에 잠들어 있었다니...",
  ui_story_5020_50201202_38_dialog_content = "근데 대체 누가 이렇게 둔 거지?",
  ui_story_5020_50201202_39_dialog_content = "이 검이 놓인 방식...",
  ui_story_5020_50201202_40_dialog_content = "아무리 봐도 제물 같잖아!",
  ui_story_5020_50201202_41_dialog_content = "앗, PlayerName, 여기 좀 봐!",
  ui_story_5020_50201202_42_dialog_content = "검 아래에 뭔가 있어...",
  ui_story_5020_50201202_43_dialog_content = "...소생이 살펴보겠소.",
  ui_story_5020_50201202_44_dialog_content = "이곳에 함정이 설치되어 있을 가능성은 낮으나, 만일을 대비해 신중하게...",
  ui_story_5020_50201202_45_dialog_content = "앗, 뭐 하는 거야?!",
  ui_story_5020_50201202_46_dialog_content = "...?",
  ui_story_5020_50201202_47_dialog_content = "왜 네가 천운참을 드는 거냐고!",
  ui_story_5020_50201202_48_dialog_content = "...이런 순간에 소생을 방해하지 마시오.",
  ui_story_5020_50201202_49_dialog_content = "PlayerName! 너도 뭐라고 좀 해 봐!",
  ui_story_5020_50201202_50_dialog_content = "뭐?! 난 너희 사이에 끼어들 생각은 없다고...",
  ui_story_5020_50201202_51_dialog_content = "검은 네가 들어.",
  ui_story_5020_50201202_52_dialog_content = "내...내가?",
  ui_story_5020_50201202_53_dialog_content = "......",
  ui_story_5020_50201202_54_dialog_content = "요우가 그것으로 얌전해진다면, 소생은 상관없소.",
  ui_story_5020_50201202_55_dialog_content = "PlayerName 공, 부디 소생의 시간을 낭비하지 마시오.",
  ui_story_5020_50201202_56_dialog_content = "...알겠어.",
  ui_story_5020_50201202_57_dialog_content = "어라...?",
  ui_story_5020_50201202_58_dialog_content = "이건...",
  ui_story_5020_50201202_59_dialog_content = "천운참이랑 같이 제단에 놓여 있던 건가...",
  ui_story_5020_50201202_60_dialog_content = "...<color=#FFB400>일기</color> 같은데?",
  ui_story_5020_50201202_61_dialog_content = "주인은...",
  ui_story_5020_50201202_62_dialog_content = "...「<color=#FFB400>츠키</color>」?",
  ui_story_5020_50201202_63_dialog_content = "?!",
  ui_story_5020_50201202_64_dialog_content = "...그 이름이로군.",
  ui_story_5020_50201202_65_dialog_content = "그것은 전임 무녀의 것이오.",
  ui_story_5020_50201202_66_dialog_content = "아무래도 누가 잘 보관하고 있었던 모양이오.\n오랜 시간 묘지에 두었던 것으로는 보이지 않소.",
  ui_story_5020_50201202_67_dialog_content = "아마 우리보다 먼저 이곳에 찾아온 이가 있을 것이오.",
  ui_story_5020_50201202_68_dialog_content = "대체 누가 우리보다... 먼저 여길 왔다는 건데?!",
  ui_story_5020_50201202_69_dialog_content = "......",
  ui_story_5020_50201202_70_dialog_content = "소생도 확신할 수는 없으나...",
  ui_story_5020_50201202_71_dialog_content = "적어도 이곳에 온 자와 전임 무녀 사이에는 필시 깊은 관계가 있을 것이오.",
  ui_story_5020_50201202_72_dialog_content = "그럼 이 일기는...",
  ui_story_5020_50201202_73_dialog_content = "당연히 봐야겠지!",
  ui_story_5020_50201202_74_dialog_content = "이 일기에는 분명히 스승님과 관련된 과거가 기록되어 있을 것이오.",
  ui_story_5020_50201202_75_dialog_content = "분명히 내가 잊어버린 과거도 적혀 있을 거라구!",
  ui_story_5020_50201202_76_dialog_content = "조심해서 열어 봐, PlayerName.",
  ui_story_5020_50201202_77_dialog_content = "일단 제일 마지막 장부터! 얼른얼른! 뒤에서부터 차례대로 넘겨 봐!",
  ui_story_5020_50201202_78_dialog_content = "그래, 그래. 알겠으니까. 그럼 다들 가까이 와.",
  ui_story_5020_50201301_1_dialog_content = "무녀님, 준비되셨습니까?",
  ui_story_5020_50201301_2_dialog_content = "네... 다만, 잠시 기다려 주시지요.",
  ui_story_5020_50201301_3_dialog_content = "이것을 제사의 신관에게 전해 주십시오...",
  ui_story_5020_50201301_4_dialog_content = "가신들을 수고롭게 할 것 없다, 츠키.",
  ui_story_5020_50201301_5_dialog_content = "내가 직접 가져가면 된다.",
  ui_story_5020_50201301_6_dialog_content = "아... 합하, 아직 「춘일제」에 가지 않으셨는지요.",
  ui_story_5020_50201301_7_dialog_content = "...절차에 조금 문제가 있었다.",
  ui_story_5020_50201301_8_dialog_content = "고로 내 구름의 거울을 가지러 돌아온 것이다.",
  ui_story_5020_50201301_9_dialog_content = "...무슨 일이 일어난 것인지요.",
  ui_story_5020_50201301_10_dialog_content = "깊이 물을 것 없다. 너는 네 의식 준비만 하고 있으면 된다.",
  ui_story_5020_50201301_11_dialog_content = "<color=#e8d9bb>쿵쿵, 쾅쾅──</color>",
  ui_story_5020_50201301_12_dialog_content = "어머...",
  ui_story_5020_50201301_13_dialog_content = "밖에서 무슨 소리가 나는 듯합니다만.",
  ui_story_5020_50201301_14_dialog_content = "츠키, 네가 신경 쓸 일이...",
  ui_story_5020_50201301_15_dialog_content = "훗...",
  ui_story_5020_50201301_16_dialog_content = "......",
  ui_story_5020_50201301_17_dialog_content = "이게 누구신가, 운도의 역적... 무녀님 아니신가.",
  ui_story_5020_50201301_18_dialog_content = "그렇게 잘 단장한 모습으로 싸우기라도 하면 꼭 내가 나쁜 사람처럼 보이겠군.",
  ui_story_5020_50201301_19_dialog_content = "흥... 아쉽겠지만 올해의 「춘일제」는 내가 곧 중단시킬 것이다.",
  ui_story_5020_50201301_20_dialog_content = "당신들의 바람은... 무엇인지요.",
  ui_story_5020_50201301_21_dialog_content = "...츠키!",
  ui_story_5020_50201301_22_dialog_content = "호오...?",
  ui_story_5020_50201301_23_dialog_content = "단도직입적인 질문이로군...",
  ui_story_5020_50201301_24_dialog_content = "적어도 그 점에서는 네가 후지쿠모보다 훨씬 영리하군그래.",
  ui_story_5020_50201301_25_dialog_content = "내 요구도 아주 간단하다. 「춘일제」를 끝내는 것이다.",
  ui_story_5020_50201301_26_dialog_content = "우리는 본도 세력의 신장을 돕는 일체의 활동을 막을 것이다!",
  ui_story_5020_50201301_27_dialog_content = "제 분수도 모르는구나. 츠키, 놈들과 말을 섞을...",
  ui_story_5020_50201301_28_dialog_content = "알겠습니다.",
  ui_story_5020_50201301_29_dialog_content = "사실 당신들의 바람은 본도의 문화가 만연하는 것을 막는 것이로군요.",
  ui_story_5020_50201301_30_dialog_content = "아, 어떻게 보면 그것도 맞는 말이겠군!",
  ui_story_5020_50201301_31_dialog_content = "운도의 항구가 본도를 향해 열린 그날로부터 우리는 이미 새로운 시대를 맞이했습니다.",
  ui_story_5020_50201301_32_dialog_content = "그것을 빠르게 받아들이는 것도, 현상을 인정하지 않고 거부하는 것도...\n모두 지극히 자연스러운 생각입니다.",
  ui_story_5020_50201301_33_dialog_content = "만약 운도 그 자체에 의지가 있었다면, 이 섬도 분명 세상의 빠른 변천에 감탄했겠지요.",
  ui_story_5020_50201301_34_dialog_content = "허나 강부성이 존재하는 한, 당신과 저는 모두 이 시대를 함께 살아가는 사람입니다.",
  ui_story_5020_50201301_35_dialog_content = "그 사실은 「춘일제」 하나를 없앤다 해서...\n심지어 쇼군을 없앤다 해서 바꿀 수 있는 것이 아닙니다.",
  ui_story_5020_50201301_36_dialog_content = "......",
  ui_story_5020_50201301_37_dialog_content = "축제를 막는다거나 할 생각을 품는 것보다는 차라리...",
  ui_story_5020_50201301_38_dialog_content = "「춘일제」를 어떻게 당신들이 원하는 모습으로 바꿀지 생각하는 것은 어떻겠습니까.",
  ui_story_5020_50201301_39_dialog_content = "............",
  ui_story_5020_50201301_40_dialog_content = "무녀님, 그 반군들은 역시 축제에서 소란을 피우지 않았습니다.",
  ui_story_5020_50201301_41_dialog_content = "후훗, 그렇다면... 저들의 총통은 어찌 되었는지요.",
  ui_story_5020_50201301_42_dialog_content = "총통이라면... 그 「나기」라는 여자 말씀이십니까?",
  ui_story_5020_50201301_43_dialog_content = "저희가 최선을 다해 찾고 있습니다만, 아직까지는 종적을 발견하지 못했습니다.",
  ui_story_5020_50201301_43X_dialog_content = "필요하시다면 병력을 더 파견하여...",
  ui_story_5020_50201301_44_dialog_content = "아니요. 그럴 필요는 없습니다.",
  ui_story_5020_50201301_45_dialog_content = "저들이 다시 소란을 피운다면 합하께서도 골치가 아프실 것입니다.",
  ui_story_5020_50201301_46_dialog_content = "나기가 「춘일제」의 벚꽃을 마음껏 즐길 수 있게 두세요.",
  ui_story_5020_50201301_47_dialog_content = "무녀님... 외람된 말씀이오나...",
  ui_story_5020_50201301_48_dialog_content = "방금 전에 하신 말씀 때문에 합하께서 심기가 불편하신 듯합니다.",
  ui_story_5020_50201301_49_dialog_content = "아... 그것도 그렇겠네요.",
  ui_story_5020_50201301_49X_dialog_content = "아까 제가 아무 말도 없이 떠났다면, 합하께서는 저들을 흔적조차 없게 처리하셨겠지요.",
  ui_story_5020_50201301_50_dialog_content = "아마 저는 그저 즐거운 분위기가 넘치는 오늘 같은 날...",
  ui_story_5020_50201301_51_dialog_content = "합하께서 인명을 해치는 것을 보고 싶지 않았을 뿐일지도 모르겠습니다.",
  ui_story_5020_50201301_52_dialog_content = "...인명을 해친다니, 무슨 말씀이십니까?",
  ui_story_5020_50201301_53_dialog_content = "방금 합하께서 구름의 거울을 가지러 돌아오신 것만으로도 자명하지 않습니까...",
  ui_story_5020_50201301_54_dialog_content = "합하는 구름의 거울을 가지고 오니를 부려 백성들을 진압할 생각이셨던 것입니다.",
  ui_story_5020_50201301_55_dialog_content = "이렇게까지 구름의 거울에 의지하는 것은 그리 좋은 일이 아닙니다만...",
  ui_story_5020_50201301_56_dialog_content = "무녀님께서는 무엇을 우려하시는지요.\n무녀님께는 참귀의 보검 천운참이 있지 않습니까?",
  ui_story_5020_50201301_57_dialog_content = "일이 수습되고 나면 무녀님께서 오니를 베면 되는 것입니다.",
  ui_story_5020_50201301_58_dialog_content = "......",
  ui_story_5020_50201301_59_dialog_content = "천운참과 구름의 거울, 하나는 오니를 물리치고, 하나는 오니를 부리지요.\n모두 신의 비호를 받은 신기입니다...",
  ui_story_5020_50201301_60_dialog_content = "이를 축제의 볼거리로 쓰는 정도는 괜찮습니다만,\n진정으로 통치의 도구가 되어 버린다면...",
  ui_story_5020_50201301_61_dialog_content = "저는 그것이 보통 사람은 받아들일 수 없는 힘을 발휘할까 두려운 것입니다.",
  ui_story_5020_50201301_62_dialog_content = "허나 그것이 바로 무녀님께 부여된 소명이 아닙니까.",
  ui_story_5020_50201301_63_dialog_content = "천운참을 들고 모든 사악한 요마를 베는 것,\n본도에서 돌아온 역대 무녀는 모두 그리 했습니다.",
  ui_story_5020_50201301_64_dialog_content = "이것은 결국 제 창으로 제 방패를 찌르는 일일 뿐입니다.",
  ui_story_5020_50201301_65_dialog_content = "천운참은 오니를 벨 수 있고, 구름의 거울은 오니를 되살릴 수 있습니다...",
  ui_story_5020_50201301_66_dialog_content = "두 강대한 힘이 서로 균형을 이루기 위해서는 「쓰는 이의 의지」가 매우 중요합니다.",
  ui_story_5020_50201301_67_dialog_content = "하지만 저는... 그분의 생각을 움직일 수가 없습니다...",
  ui_story_5020_50201301_68_dialog_content = "결국 저 역시 운도가 평화로 향하도록 돕는 도구에 불과한 것입니다.",
  ui_story_5020_50201301_69_dialog_content = "무녀님... 소, 소신은...",
  ui_story_5020_50201301_70_dialog_content = "역시 무슨 말씀이신지 잘 모르겠습니다...",
  ui_story_5020_50201301_71_dialog_content = "<color=#e8d9bb>딸랑, 딸랑, 딸랑──</color>",
  ui_story_5020_50201301_72_dialog_content = "후훗, 보세요. 합하께서 방울이 잔뜩 달린 가마에 올라타셨습니다.",
  ui_story_5020_50201301_73_dialog_content = "이런... 하, 합하!",
  ui_story_5020_50201301_74_dialog_content = "무녀님, 그럼 소신은 이만 실례하겠습니다. 합하의 호위를 맡고 오겠습니다!",
  ui_story_5020_50201301_75_dialog_content = "<color=#e8d9bb>딸랑, 딸랑, 딸랑──</color>",
  ui_story_5020_50201301_76_dialog_content = "따라오지 마! 따라오지 말라구!",
  ui_story_5020_50201301_77_dialog_content = "하, 하아... 이 자식! 얼른 방울을 츠키한테 돌려주지 못할까!",
  ui_story_5020_50201301_78_dialog_content = "츠키 언니랑 술래잡기할 거야! 잡으면 돌려줄게!",
  ui_story_5020_50201301_79_dialog_content = "...내가 몇 번이나 말했을 텐데, 츠키 님이라고 불러라!",
  ui_story_5020_50201301_80_dialog_content = "알았어, 츠키 언니!",
  ui_story_5020_50201301_81_dialog_content = "됐어요~ 나기, 어린애한테 화를 내면 어떡해요.",
  ui_story_5020_50201301_82_dialog_content = "요우가 언니라고 불러준다는 건 저를 좋아한다는 뜻인걸요.",
  ui_story_5020_50201301_83_dialog_content = "...너는 내 언니다. 요우는 네가 거둔 아이고 말이다.",
  ui_story_5020_50201301_84_dialog_content = "저런 식으로 위아래도 모르고 널 언니라고 부르면... 나는 뭐가 되냔 말이다!",
  ui_story_5020_50201301_85_dialog_content = "후후훗.",
  ui_story_5020_50201301_86_dialog_content = "웃지 마!",
  ui_story_5020_50201301_87_dialog_content = "그나저나 요우는 조금 말괄량이 같지만, 아메모리는 말을 잘 듣는 아이로군요.",
  ui_story_5020_50201301_88_dialog_content = "그저 아이를 잠시 맡겼을 뿐인데, 나기는 아메모리를 자기 자신과 똑같이 가르쳐 버렸군요.",
  ui_story_5020_50201301_89_dialog_content = "음... 녀석은 확실히 소질이 있었다.",
  ui_story_5020_50201301_90_dialog_content = "그래서 자꾸 다른 것들을 가르쳐 주고 싶게 된단 말이지.",
  ui_story_5020_50201301_91_dialog_content = "...나기!",
  ui_story_5020_50201301_92_dialog_content = "뭐, 걱정하진 마라. 네 허락 없이 저 아이들에게 그 술식들을 가르칠 생각은 없으니까.",
  ui_story_5020_50201301_93_dialog_content = "게다가... 아메모리는 왜인지 많은 것을 마음에 짊어진 듯했다...",
  ui_story_5020_50201301_94_dialog_content = "아직 어린 나이인데도 어울리지 않게 담담하고 무정한 척을 하고 있더군...",
  ui_story_5020_50201301_95_dialog_content = "아직 감정을 삭일 나이도 안 된 녀석이 말이야.",
  ui_story_5020_50201301_96_dialog_content = "확실히 그렇습니다.",
  ui_story_5020_50201301_97_dialog_content = "저 아이들을 데려온 뒤로, 저는 줄곧 저 아이들을 제 자식처럼 여겨 왔습니다.",
  ui_story_5020_50201301_98_dialog_content = "하지만 아메모리는 저와 가까이 지내려 하지도 않고,\n요우와 함께 놀려고 하지도 않았습니다...",
  ui_story_5020_50201301_99_dialog_content = "그런데 정작 나기는 좋아하는 것 같더군요.",
  ui_story_5020_50201301_100_dialog_content = "나를... 좋아한다고?",
  ui_story_5020_50201301_101_dialog_content = "그럼요. 아메모리는 비록 말수는 적지만, 항상 당신을 따라다니면서\n나기의 행동을 관찰하고 있어요...",
  ui_story_5020_50201301_102_dialog_content = "보세요. 이제는 좋아하는 꽃조차 나기의 취향과 똑같잖아요.",
  ui_story_5020_50201301_103_dialog_content = "저렇게 어린 나이에 벚꽃이 지는 아름다움을 이해한다니 말이지요.",
  ui_story_5020_50201301_104_dialog_content = "뭐?",
  ui_story_5020_50201301_105_dialog_content = "아, 벌써 벚꽃이 지는 계절이 된 건가.",
  ui_story_5020_50201301_106_dialog_content = "<size=33>...시간이 정말 빠르네요. 이제 저도 곧 본도로 떠나겠지요.</size>",
  ui_story_5020_50201301_107_dialog_content = "...지금 뭐라고 했어... 언니?",
  ui_story_5020_50201301_108_dialog_content = "아니... 아무것도 아니에요.",
  ui_story_5020_50201301_109_dialog_content = "나기, 저는 잠시 운도를 떠나야만 해요.",
  ui_story_5020_50201301_110_dialog_content = "제가 돌아왔을 때면, 당신은 진짜 총통이 되어 있겠지요.",
  ui_story_5020_50201301_111_dialog_content = "어디로... 가는 거야? 뭐 하러? 왜 나한테 말 안 했어?",
  ui_story_5020_50201301_112_dialog_content = "...아메모리랑 요우를 나한테 맡긴 것도 그것 때문이었어?",
  ui_story_5020_50201301_113_dialog_content = "후훗, 저 아이들이 확실히 나기를 힘들게 만들고 있는 모양이군요...",
  ui_story_5020_50201301_114_dialog_content = "그렇다고 저를 원망하진 않으시겠지요.",
  ui_story_5020_50201301_115_dialog_content = "...그럴 리가 없잖아!",
  ui_story_5020_50201301_116_dialog_content = "그렇다면 다행입니다...",
  ui_story_5020_50201301_117_dialog_content = "앞으로도 그랬으면 좋겠습니다만...",
  ui_story_5020_50201301_118_dialog_content = "언니?! 대체 무슨 소릴 하는 거야? 내가 왜 그러겠어...",
  ui_story_5020_50201301_119_dialog_content = "그래요.",
  ui_story_5020_50201301_120_dialog_content = "지금 확실하게 말해줄 수 없는 것은 저만의 이유가 있기 때문이에요.",
  ui_story_5020_50201301_121_dialog_content = "부디 제가 없는 동안, 어릴 적 우리가 불렀던 노래를 저 아이들에게 가르쳐 주세요.",
  ui_story_5020_50201301_122_dialog_content = "뭘 멍하니 있는 거죠? 설마 잊어버린 건가요?",
  ui_story_5020_50201301_123_dialog_content = "다, 당연히 기억하지!",
  ui_story_5020_50201301_124_dialog_content = "그러고 보니... 확실히 이 계절에 어울리는 노래 같네.",
  ui_story_5020_50201301_125_dialog_content = "「붉은 꽃 꺾어 님에게 주니」...♪",
  ui_story_5020_50201301_126_dialog_content = "「꽃잎은 옥설 위에 떨어지네」...♪",
  ui_story_5020_50201301_127_dialog_content = "나기, 눈썹에 정말로 벚꽃잎이 앉았네요.",
  ui_story_5020_50201301_128_dialog_content = "아, 얼른 떼줘, 언니...",
  ui_story_5020_50201301_129_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_5020_50201301_130_dialog_content = "<color=#e8d9bb>............</color>",
  ui_story_5020_50201401_1_dialog_content = "......",
  ui_story_5020_50201401_2_dialog_content = "......",
  ui_story_5020_50201401_3_dialog_content = "무녀 언니가 기록해둔 게... 이런 내용이었다니.",
  ui_story_5020_50201401_4_dialog_content = "그래서 내가 린네를 처음 봤을 때 무척 친근하게 느껴졌던 거구나...",
  ui_story_5020_50201401_5_dialog_content = "이제 알 것 같아. 그럼 전부 설명이 되잖아.",
  ui_story_5020_50201401_6_dialog_content = "어디선가 만난 것 같은 무녀, 기억 속에 울려 퍼지는 방울 소리...",
  ui_story_5020_50201401_7_dialog_content = "과거의 저 시간들이 요우가 잃어버린 기억이었구나!",
  ui_story_5020_50201401_8_dialog_content = "근데 나...",
  ui_story_5020_50201401_9_dialog_content = "...응?",
  ui_story_5020_50201401_10_dialog_content = "왠지... 가슴이 답답해...",
  ui_story_5020_50201401_11_dialog_content = "기억을 되찾는다는 건 즐거워야 되는 거 아냐?",
  ui_story_5020_50201401_12_dialog_content = "난 역시... 스승님을 이해할 수가 없어.",
  ui_story_5020_50201401_13_dialog_content = "근데 내가 스승님이었다면... 나라면 어떻게 했을까...?",
  ui_story_5020_50201401_14_dialog_content = "본도에서 돌아온 무녀는 확실한 운도의 역적이야...",
  ui_story_5020_50201401_15_dialog_content = "애초에 나쁜 사람인지 좋은 사람인지 이렇게 쉽게 구분할 수 있는 거잖아! 그런데...",
  ui_story_5020_50201401_16_dialog_content = "그 당시에 칼을 들었을 스승님보다 어째서 내가 더 마음이 괴로운 거냐구...",
  ui_story_5020_50201401_17_dialog_content = "...그건 아마 이 세계엔 흑백을 가릴 수 없는 문제가 너무 많기 때문일 거야.",
  ui_story_5020_50201401_18_dialog_content = "아스트라 대륙에서도, 극동의 운도에서도...",
  ui_story_5020_50201401_19_dialog_content = "누구나 자신의 입장을 지키고, 각자 어쩔 수 없는 선택을 하고 있을 테니까.",
  ui_story_5020_50201401_20_dialog_content = "...그렇구나.",
  ui_story_5020_50201401_21_dialog_content = "그리고 일기의 마지막 부분에...",
  ui_story_5020_50201401_22_dialog_content = "음... 확실히 여기쯤이었는데...",
  ui_story_5020_50201401_22X_dialog_content = "어라?",
  ui_story_5020_50201401_23_dialog_content = "속표지의 틈에 <color=#FFB400>편지</color>가 들어있어!",
  ui_story_5020_50201401_24_dialog_content = "아무도 열어본 적이 없었던 모양이네.",
  ui_story_5020_50201401_25_dialog_content = "「다, 음, 대, 의, 무, 녀, 에, 게」...",
  ui_story_5020_50201401_26_dialog_content = "앗! 이건... 무녀 언니가 린네한테 남긴 편지야!",
  ui_story_5020_50201401_27_dialog_content = "PlayerName, 이따가 린네 씨한테 갖다주자.",
  ui_story_5020_50201401_28_dialog_content = "으음... 다들 봐봐, 내가 찾으려던 건 여기 일기의 시작 부분이야.",
  ui_story_5020_50201401_29_dialog_content = "무녀 언니가 운도를 떠나기 전 스승님과 헤어질 때... 여기 한 말이 대체 무슨 뜻일까?",
  ui_story_5020_50201401_30_dialog_content = "그때 무녀 언니는 자기가 무녀가 되는 미래가 보인 걸까?",
  ui_story_5020_50201401_31_dialog_content = "스승님과 운도 사람들에게 증오의 대상이 될 수밖에 없는 미래인데도...",
  ui_story_5020_50201401_32_dialog_content = "아마 그럼에도 불구하고 자신이 내린 선택인 거겠지.",
  ui_story_5020_50201401_33_dialog_content = "자신의 선택...?",
  ui_story_5020_50201401_34_dialog_content = "아, 맞다! 그러고 보니까... 후후...",
  ui_story_5020_50201401_35_dialog_content = "어때? 아메모리! 내 말이 맞았지? 무녀 언니는 절대 나쁜 사람이 아니었어!",
  ui_story_5020_50201401_36_dialog_content = "언니는 운도의 평화를 생각했던 대단한 사람이었던 거야!",
  ui_story_5020_50201401_37_dialog_content = "...아메모리?",
  ui_story_5020_50201401_38_dialog_content = "아메모리... 너 지금 우는 거야?",
  ui_story_5020_50201401_39_dialog_content = "...아니오.",
  ui_story_5020_50201401_40_dialog_content = "(그렇게 대놓고 물어보면 어떡해?!)",
  ui_story_5020_50201401_41_dialog_content = "소생은 그저... 다른 시선에서 스승님을 보게 된 것이 처음이라...",
  ui_story_5020_50201401_42_dialog_content = "게다가 스승님이 소생에 대해 남에게 말씀하신 것을 접한 것도 처음이었소.",
  ui_story_5020_50201401_43_dialog_content = "일찍이 소생은 자신이 스승님과 똑같은 사람이라고 생각했소.",
  ui_story_5020_50201401_44_dialog_content = "수하의 촉유군들조차 그렇게 소생을 평가하고 있소.",
  ui_story_5020_50201401_45_dialog_content = "하지만 소생이 정말 스승님과 비슷한지는 스승님 자신밖에 모를 것이오.",
  ui_story_5020_50201401_46_dialog_content = "스승님께서 수행에 힘쓰셨던 몇 년간,\n그분은 몸도 마음도 후지쿠모보다 단단하게 변하신 것 같았소...",
  ui_story_5020_50201401_47_dialog_content = "어떤 힘이든 받아내고, 당시 후지쿠모의 힘에도 견디실 수 있었소...",
  ui_story_5020_50201401_48_dialog_content = "외부의 모든 타격과 과도한 기대, 수많은 비방과 중상도 말이오...",
  ui_story_5020_50201401_49_dialog_content = "그러나 츠키가 임종 전 스승님을 봉인의 땅에 가둔 그 작은 일격은 막지 못하셨지.",
  ui_story_5020_50201401_50_dialog_content = "10년의 시간이 흘러 스승님께서 다시 소생을 보시고 처음 하신 말씀...",
  ui_story_5020_50201401_51_dialog_content = "때로는 애써 무정한 척하고, 때로는 없어야 할 동정과 나약함을 보인다.",
  ui_story_5020_50201401_52_dialog_content = "이 세상을 살아간다면 「감정」 따위는 잊어버리는 게 좋을 게다.",
  ui_story_5020_50201401_53_dialog_content = "어쩌면 그것은... 스승님이 스스로에게 하는 당부였을지도 모르겠소.",
  ui_story_5020_50201401_54_dialog_content = "...무슨 소리야? 넌 당연히 사부님이랑 다르지.",
  ui_story_5020_50201401_55_dialog_content = "그건 처음 스승님을 만났을 때부터 알 수 있었거든.",
  ui_story_5020_50201401_56_dialog_content = "그게 무슨...",
  ui_story_5020_50201401_57_dialog_content = "잘 모르겠으면 내가 차근차근 얘기해 줄게! 크흠...",
  ui_story_5020_50201401_58_dialog_content = "스승님은 자기가 뭘 하고 싶은지 잘 아는 사람이야.",
  ui_story_5020_50201401_59_dialog_content = "스승님만 그런 게 아니라, 무녀 언니도 그렇고...",
  ui_story_5020_50201401_60_dialog_content = "둘 다 자기가 하고 싶은 게 뭔지 아주 잘 알고 있었어.",
  ui_story_5020_50201401_61_dialog_content = "근데 넌 어때? 스승님한테 받은 영향을 빼고,\n네가 자기한테 억지로 새긴 결심도 빼고 나면...",
  ui_story_5020_50201401_62_dialog_content = "<color=#FFB400>진짜 너 자신의 선택</color>은 뭔데?",
  ui_story_5020_50201401_63_dialog_content = "...?!",
  ui_story_5020_50201401_64_dialog_content = "허나... 그것들을 없앤다면 소생은...",
  ui_story_5020_50201401_65_dialog_content = "아무것도 모르겠소...",
  ui_story_5020_50201401_66_dialog_content = "<color=#e8d9bb>투웅───!</color>",
  ui_story_5020_50201401_67_dialog_content = "<color=#e8d9bb>퉁, 투둥, 퉁──!</color>",
  ui_story_5020_50201401_68_dialog_content = "어라, 이 소리는...",
  ui_story_5020_50201401_69_dialog_content = "<color=#FFB400>북소리</color>야! 모모랑 안즈가 북을 치고 있어!",
  ui_story_5020_50201401_70_dialog_content = "근데 왜지...? 강부성 쪽은 지금 분명히...",
  ui_story_5020_50201401_71_dialog_content = "저건 나랑 약속했던 신호야! 린네랑 두 사람이 위험해!",
  ui_story_5020_50201401_72_dialog_content = "린네...?!",
  ui_story_5020_50201401_73_dialog_content = "린네는 지금 어디 있는데?!",
  ui_story_5020_50201401_74_dialog_content = "...지금 즉시 촉유군에게 지원하도록 전하겠소!",
  ui_story_5020_50201401_75_dialog_content = "그럴 필요 없어!",
  ui_story_5020_50201401_75X_dialog_content = "린네는 우리랑 떨어진 뒤로 계속 촉유군이랑 같이 움직이고 있었을 거야.",
  ui_story_5020_50201401_76_dialog_content = "아마 지금 새로운 싸움에 휘말린 거겠지.",
  ui_story_5020_50201401_77_dialog_content = "같이 움직인다고?! 어찌 그런...",
  ui_story_5020_50201401_78_dialog_content = "아메모리... 「선택지가 없다」는 것도 가끔은 일종의 선택지가 되곤 해.",
  ui_story_5020_50201401_79_dialog_content = "적어도 지금 이런 긴급한 상황에서 뭘 해야 할지는 너도 잘 알고 있을 거라 생각해!",
  ui_story_5020_50201401_80_dialog_content = "......",
  ui_story_5020_50201401_81_dialog_content = "항구 쪽 방향이오.",
  ui_story_5020_50201401_82_dialog_content = "요우, 손을 이리 주시오.",
  ui_story_5020_50201401_83_dialog_content = "여기에 10년 전의 기억이 담겨 있다면, 함께 이것으로 과거의 일에 종지부를 찍는 것이오!",
  ui_story_5020_50201401_84_dialog_content = "후훗, 역시 영웅끼리는 뜻이 맞는 법이라니까!",
  ui_story_5020_50201401_85_dialog_content = "가자! 북소리를 따라가는 거야. 목표는 <color=#FFB400>항구</color>야!",
  ui_story_5020_50201401_86_dialog_content = "<color=#e8d9bb>강부성 번화가의 어느 거리</color>",
  ui_story_5020_50201401_87_dialog_content = "여러분! 어서 따라오십시오!",
  ui_story_5020_50201401_88_dialog_content = "사카이 거리의 이 강을 따라 하류로 가면 항구에 도착할 것입니다!",
  ui_story_5020_50201401_89_dialog_content = "모두 서둘러라! 지휘에 따라 신속하게 철수한다!",
  ui_story_5020_50201401_90_dialog_content = "항구에 도착하면 준비한 배를 타고 대피할 수 있을 것이다!",
  ui_story_5020_50201401_91_dialog_content = "강부성 본성에서 최대한 멀리 피해라!",
  ui_story_5020_50201401_92_dialog_content = "이런 날도 오다니...",
  ui_story_5020_50201401_93_dialog_content = "옛 총통의 병사들이 쇼군의 무녀랑 같이 움직이고 있잖아?!",
  ui_story_5020_50201401_93X_dialog_content = "...으억!",
  ui_story_5020_50201401_94_dialog_content = "아이고, 내 엉덩이야!",
  ui_story_5020_50201401_95_dialog_content = "잡담은 삼가라. 안 그러면 다음에 널 찌르는 건 칼자루가 아닐 거다!",
  ui_story_5020_50201401_96_dialog_content = "아빠... 우리도 얼른 저 무녀 누나를 따라가자. 다들 우릴 쳐다보고 있어...",
  ui_story_5020_50201401_97_dialog_content = "저긴 아직도 불타고 있어... 무서워...",
  ui_story_5020_50201401_98_dialog_content = "우, 우리가 왜 무녀를 따라가야 되는 거냐!",
  ui_story_5020_50201401_99_dialog_content = "역적한테 속아서 배를 타면... 본도까지 유괴당할 거다!",
  ui_story_5020_50201401_100_dialog_content = "그리고 본도에는 후지쿠모 100명이 우릴 기다리고 있을 거라고!",
  ui_story_5020_50201401_100X_dialog_content = "...아이고야!",
  ui_story_5020_50201401_101_dialog_content = "으, 아파라... 아이고 내 어깨야!",
  ui_story_5020_50201401_102_dialog_content = "아, 아빠!",
  ui_story_5020_50201401_103_dialog_content = "이 빌어먹을 놈들, 대체 우릴 살리려는 거냐, 아니면 죽이려는 거냐...",
  ui_story_5020_50201401_104_dialog_content = "어라?",
  ui_story_5020_50201401_105_dialog_content = "<anim type=Shake>그...어어어!</anim>",
  ui_story_5020_50201401_106_dialog_content = "오, 오니다... 사카이 거리에도 오니가 있다니!",
  ui_story_5020_50201401_107_dialog_content = "모두 당황하지 말고 피난 대열에 바짝 붙어라!",
  ui_story_5020_50201401_108_dialog_content = "무녀, 내가 뒤를 막을 테니 넌 백성들을 이끌어라!",
  ui_story_5020_50201401_109_dialog_content = "<anim type=Shake>그어어...</anim>",
  ui_story_5020_50201401_110_dialog_content = "<size=45><anim type=Shake>그어억!</anim></size>",
  ui_story_5020_50201401_111_dialog_content = "<size=50><anim type=Shake>그어어어!</anim></size>",
  ui_story_5020_50201401_112_dialog_content = "형제들이여, 칼을 뽑아라!",
  ui_story_5020_50201401_113_dialog_content = "놈들의 영혼까지 베어버리는 거다!",
  ui_story_5020_50201401_114_dialog_content = "우오오──!",
  ui_story_5020_50201501_1_dialog_content = "<color=#e8d9bb>강부성 항구, 부둣가 근처</color>",
  ui_story_5020_50201501_2_dialog_content = "<color=#e8d9bb>퉁, 투둥, 퉁──!</color>",
  ui_story_5020_50201501_3_dialog_content = "사람들이 엄청 많네... 린네는 대체 어디 있는 거야?!",
  ui_story_5020_50201501_4_dialog_content = "됐어, 그렇다면...",
  ui_story_5020_50201501_5_dialog_content = "린──네에에에──!",
  ui_story_5020_50201501_6_dialog_content = "린네? 린네── 어디 있어──?",
  ui_story_5020_50201501_7_dialog_content = "...요우?",
  ui_story_5020_50201501_8_dialog_content = "요우!",
  ui_story_5020_50201501_9_dialog_content = "어머, 아메모리, 바이스 님, PlayerName 님도 계셨군요!",
  ui_story_5020_50201501_10_dialog_content = "역시... 저 북소리가 들리셨던 것이로군요!",
  ui_story_5020_50201501_11_dialog_content = "다 PlayerName 덕분이야! 소리를 듣자마자 바로 달려왔어.",
  ui_story_5020_50201501_12_dialog_content = "상황은 어때? 넌 어디 안 다쳤어?",
  ui_story_5020_50201501_13_dialog_content = "무탈합니다. 강부성 부근의 백성들은 대부분 데려왔습니다.",
  ui_story_5020_50201501_14_dialog_content = "일부 백성들은 촉유군이 이미 배에 태워 피신시켰습니다...",
  ui_story_5020_50201501_15_dialog_content = "괜찮아? 운도 사람들이... 너한테 나쁘게 대하진 않았어?",
  ui_story_5020_50201501_16_dialog_content = "후훗, 저를 걱정해 주시는 것이로군요.",
  ui_story_5020_50201501_17_dialog_content = "괜찮습니다. 보시다시피 아주 좋지 않습니까.\n그것보다 여러분은 괜찮으셨는지요.",
  ui_story_5020_50201501_18_dialog_content = "우리가 무슨 일이 있었겠어? 아, 맞다! PlayerName! 빨리 <color=#FFB400>그거</color> 줘!",
  ui_story_5020_50201501_19_dialog_content = "으음?!",
  ui_story_5020_50201501_20_dialog_content = "그, 그거? 아... 맞다.",
  ui_story_5020_50201501_21_dialog_content = "린네, 이거 받아.",
  ui_story_5020_50201501_22_dialog_content = "어머, 이건... 편지로군요.",
  ui_story_5020_50201501_23_dialog_content = "제 앞으로 온 것인지요. 하지만... 보내신 분은 모르는 이름입니다만...",
  ui_story_5020_50201501_24_dialog_content = "「츠키」는 강부성의 전임 무녀야.",
  ui_story_5020_50201501_25_dialog_content = "...알겠습니다.",
  ui_story_5020_50201501_26_dialog_content = "「다음 대의 무녀에게...」",
  ui_story_5020_50201501_27_dialog_content = "절 찾아올 그녀를 기다리는 동안, 저는 무언가 기록을 남겨야겠다고 생각했습니다.",
  ui_story_5020_50201501_28_dialog_content = "이제는 곧 볼 수 없게 되어버릴 그 미래는... 저 역시 조금 불안하게 느껴집니다...",
  ui_story_5020_50201501_29_dialog_content = "하지만 여러 생각 끝에 가장 염려되었던 것은 언젠가 이 임무를 계승할 당신이었습니다.",
  ui_story_5020_50201501_30_dialog_content = "선배의 가르침을 받을 수 없는 것은 불공평한 일입니다.",
  ui_story_5020_50201501_31_dialog_content = "비록 「무녀」가 된다는 것은...\n그것이 가져올 수많은 불공평과 싸워야 할 운명이라 해도 말이지요.",
  ui_story_5020_50201501_32_dialog_content = "당신이 이 편지를 읽고 있을 때면 운도에는 어느 계절이 돌아오고 있을까요...",
  ui_story_5020_50201501_33_dialog_content = "운도는 예로부터 벚꽃이 유명했습니다. 만개할 때는 이글거리는 자줏빛 구름 같고...",
  ui_story_5020_50201501_33X_dialog_content = "질 때는 새하얀 눈처럼 흩날리지요...",
  ui_story_5020_50201501_34_dialog_content = "어쩌면 운도 사람들의 눈에는 무녀도 이처럼 아름답고 덧없는 인상을 남길 뿐일지도 모르겠습니다.",
  ui_story_5020_50201501_35_dialog_content = "하지만 저는 운도의 무녀가 태양처럼 홀로 빛나,\n이 땅을 지켜 주어야 한다고 생각합니다...",
  ui_story_5020_50201501_36_dialog_content = "우리는 밤의 어둠과 어깨를 나란히 할 수는 있으나,\n결코 본도의 구름에 가려져서는 안 됩니다.",
  ui_story_5020_50201501_37_dialog_content = "그리고 당신이 만약 이 과거에 대해 이미 알았다면,\n같은 무녀인 당신에게는 설명해줄 필요가 있겠지요.",
  ui_story_5020_50201501_38_dialog_content = "합하께서는 결코 하늘을 덮는 먹구름이 아닙니다. 적어도 제 눈에는 결코 그렇지 않습니다.",
  ui_story_5020_50201501_39_dialog_content = "그분께서는 먹구름처럼 높고 먼 것이 아니라, 그저 머리 위의 우산 같은 분입니다.",
  ui_story_5020_50201501_40_dialog_content = "합하께서는 선한 분도 아니고, 선한 일을 하지도 않았습니다.\n그분께서는 이 섬에 많은 불행을 가져왔지요...",
  ui_story_5020_50201501_41_dialog_content = "그러나 그 미래는 그분께서 강부성에 가져다줄 수 있는 가장 좋은 것이었습니다.",
  ui_story_5020_50201501_42_dialog_content = "「마지막으로 부디 이 편지를 만난 적도 없는 당신에게 쓰는 것을 허락해 주십시오.」",
  ui_story_5020_50201501_43_dialog_content = "「편지를 마치면서, 저는 받는 이의 이름을 쓰기 전 오랜 시간 망설였습니다.」",
  ui_story_5020_50201501_44_dialog_content = "「이 순간의 편지는 어쩌면 서글픈 작별의 편지가 될 수밖에 없을 테니 말이지요.」",
  ui_story_5020_50201501_45_dialog_content = "「그래서 저는 이 편지를 미래의 어느 순간 다시 열 수 있게 하기로 결정했습니다.」",
  ui_story_5020_50201501_46_dialog_content = "「부디 제 당부와 함께, 태양처럼 살아가 주세요.」",
  ui_story_5020_50201501_47_dialog_content = "「당신의 선배가.」",
  ui_story_5020_50201501_48_dialog_content = "......",
  ui_story_5020_50201501_49_dialog_content = "실로 기묘한 일이로군요...",
  ui_story_5020_50201501_50_dialog_content = "강부성의 무녀는 오직 고독만을 벗으로 삼는 존재입니다.",
  ui_story_5020_50201501_51_dialog_content = "허나 지금은 이 선배로부터 힘을 받은 것만 같습니다...",
  ui_story_5020_50201501_52_dialog_content = "지금까지의 무녀라면 확실히 그랬을지도 몰라...",
  ui_story_5020_50201501_53_dialog_content = "하지만 린네 넌 이미 모든 것을 바꿔버렸어. 아직도 모르겠어?",
  ui_story_5020_50201501_54_dialog_content = "제가... 말입니까?",
  ui_story_5020_50201501_55_dialog_content = "무, 무녀님... 이걸 받아 주시지요...",
  ui_story_5020_50201501_56_dialog_content = "잔뜩 있으니까 전부 누나한테 줄게!",
  ui_story_5020_50201501_57_dialog_content = "이것은... 귀신을 쫓고 복을 부르는 <color=#FFB400>복콩</color>이 아닙니까.",
  ui_story_5020_50201501_58_dialog_content = "사람들이 가지고 있던 걸 전부 모은 거야.\n우리 복이 전부 이 안에 담겨 있어!",
  ui_story_5020_50201501_59_dialog_content = "그러니까 누나는 이 콩으로 저 악당들을 해치워 줘!",
  ui_story_5020_50201501_60_dialog_content = "저희들의 복이 부디 당신을 지켜주길 바라겠습니다...",
  ui_story_5020_50201501_61_dialog_content = "무녀님, 이 콩을 가지고 싸워주세요.",
  ui_story_5020_50201501_62_dialog_content = "여러분...",
  ui_story_5020_50201501_63_dialog_content = "알겠습니다... 여러분, 부디 저를 믿어 주십시오.",
  ui_story_5020_50201501_64_dialog_content = "무녀, 다음 배가 준비됐다. 남은 사람들도 전부 탈 수 있을 거다.",
  ui_story_5020_50201501_65_dialog_content = "알겠습니다. 이 사람들을 데리고 배에 오르시지요.",
  ui_story_5020_50201501_66_dialog_content = "후후, 아메모리, 왜 아까부터 말이 없어?",
  ui_story_5020_50201501_67_dialog_content = "계속 그렇게 멍하니 있으면, 촉유군에 새로운 대장이 생길 거라구~",
  ui_story_5020_50201501_68_dialog_content = "...소생은 무녀와 나눌 말 따위는 없소이다.",
  ui_story_5020_50201501_69_dialog_content = "어머, 꽤나 냉랭하네요.",
  ui_story_5020_50201501_70_dialog_content = "아메모리, 이렇게 오랜만에 보는데, 제가 그립지는 않으셨는지요.",
  ui_story_5020_50201501_71_dialog_content = "그, 그리 오래된 것도 아니잖소.",
  ui_story_5020_50201501_72_dialog_content = "이런 위급한 시기에 그런 이야기나 하고 있을 틈은 없소!",
  ui_story_5020_50201501_73_dialog_content = "어? 총통님! 오셨습니까!",
  ui_story_5020_50201501_74_dialog_content = "<size=45>아──메──모──리──님!</size>",
  ui_story_5020_50201501_75_dialog_content = "소생이 총통이라 부르지 말라고 말하지 않았소!",
  ui_story_5020_50201501_76_dialog_content = "아메모리 총.통.님, 촉유군을 정말 든든하게 양성하셨군요.",
  ui_story_5020_50201501_77_dialog_content = "저와 손발이 아주 잘 맞더군요.",
  ui_story_5020_50201501_78_dialog_content = "우와, 싸우는 거야? 린네, 아메모리! 그럼 정정당당하게 겨뤄봐!",
  ui_story_5020_50201501_79_dialog_content = "「절대적인 힘으로 촉유군의 통솔권을 쟁취하는 경기」 시작~",
  ui_story_5020_50201501_80_dialog_content = "으악! 아, 아프잖아... 내 머리!",
  ui_story_5020_50201501_81_dialog_content = "농담도 참!",
  ui_story_5020_50201501_82_dialog_content = "자, 그러면 잡담은 여기까지 할까요.",
  ui_story_5020_50201501_83_dialog_content = "저 오니들의 속도라면 곧 항구까지 쫓아올 것입니다.",
  ui_story_5020_50201501_84_dialog_content = "그전까지... PlayerName 님, 저희도 각자 준비하는 것이 좋겠습니다.",
  ui_story_5020_50201501_85_dialog_content = "그래, 그러면...",
  ui_story_5020_50201501_86_dialog_content = "아메모리는 요우와 함께 촉유군을 데리고 사카이 거리에서 부두로 오는 입구를 지켜주세요.",
  ui_story_5020_50201501_87_dialog_content = "바이스 님, PlayerName 님은 이곳에 남아 아메모리 쪽에서 도망친 오니들을 맡아 주십시오.",
  ui_story_5020_50201501_88_dialog_content = "저는 부두로 가서 포위해 오는 무사들을 상대하겠습니다!",
  ui_story_5020_50201501_89_dialog_content = "너... 혼자서 괜찮겠어?",
  ui_story_5020_50201501_90_dialog_content = "아직도 저를 의심하시는 것인지요, PlayerName 님.",
  ui_story_5020_50201501_91_dialog_content = "(린네... 확실히 처음 만났을 때랑 달라졌구나...!)",
  ui_story_5020_50201501_92_dialog_content = "좋아, 그럼 바로 시작하자!",
  ui_story_5020_50201501_93_dialog_content = "응!",
  ui_story_5020_50201501_94_dialog_content = "<anim type=Shake>그어어...</anim>",
  ui_story_5020_50201501_95_dialog_content = "놈들이 벌써 여기까지 왔소.",
  ui_story_5020_50201501_96_dialog_content = "흥, 내 주먹도 좀이 쑤시던 참이라구!",
  ui_story_5020_50201501_97_dialog_content = "아무래도 저는 지금 바로 부두로 가는 것이 좋겠군요.",
  ui_story_5020_50201501_98_dialog_content = "여러분, 부디 무사히 이 싸움을 이겨 주세요!",
  ui_story_5020_50201601_1_dialog_content = "<color=#e8d9bb>강부성 항구, 진입로</color>",
  ui_story_5020_50201601_2_dialog_content = "<color=#e8d9bb>투둑... 화르륵...</color>",
  ui_story_5020_50201601_3_dialog_content = "하... 하아...",
  ui_story_5020_50201601_4_dialog_content = "윽... 콜록콜록!",
  ui_story_5020_50201601_5_dialog_content = "아메모리 님!",
  ui_story_5020_50201601_6_dialog_content = "다치셨군요... 어서 아메모리 님을 후방으로 모셔라!",
  ui_story_5020_50201601_7_dialog_content = "필요 없소. 그대들은 이대로 사카이 거리를 향해 진군하시오...",
  ui_story_5020_50201601_8_dialog_content = "제자리에 머물며 수비를 다지는 것이야말로 패전을 자초하는 전략이오.",
  ui_story_5020_50201601_9_dialog_content = "병력을 견고히 하고 조무래기들에게 방심하지 마시오.",
  ui_story_5020_50201601_10_dialog_content = "만약 벅찬 상대를 만나거늘... 이쪽으로 유인하시오...",
  ui_story_5020_50201601_11_dialog_content = "우리가 가진 천운참으로 처리할 테니 말이오!",
  ui_story_5020_50201601_12_dialog_content = "허나 그러면 아메모리 님이...",
  ui_story_5020_50201601_13_dialog_content = "소생의 말을 이해하지 못했는가!",
  ui_story_5020_50201601_14_dialog_content = "알겠습니다...!",
  ui_story_5020_50201601_15_dialog_content = "<color=#e8d9bb>터벅, 터벅, 터벅...</color>",
  ui_story_5020_50201601_16_dialog_content = "하... 하아...",
  ui_story_5020_50201601_17_dialog_content = "조심해! 아메모리!",
  ui_story_5020_50201601_18_dialog_content = "<anim type=Shake>그어어어!</anim>",
  ui_story_5020_50201601_19_dialog_content = "에잇── 크억...",
  ui_story_5020_50201601_20_dialog_content = "아메모리!",
  ui_story_5020_50201601_21_dialog_content = "소생이 방심했소... 미처 살피지 못했소.",
  ui_story_5020_50201601_22_dialog_content = "요우... 소생의 등 뒤에 서시오.",
  ui_story_5020_50201601_23_dialog_content = "그, 그래...! 근데, 왜...?",
  ui_story_5020_50201601_24_dialog_content = "아... 그렇구나!",
  ui_story_5020_50201601_25_dialog_content = "어렸을 때 린 가문에서 배웠어. 진정한 전사는 정면으로만 적과 맞서 싸운다고.",
  ui_story_5020_50201601_26_dialog_content = "인술에도 그런 전략이 있었던 거야?",
  ui_story_5020_50201601_27_dialog_content = "등을 적에게 맡기는 것은 전쟁의 금기요.",
  ui_story_5020_50201601_28_dialog_content = "본디 인술은 어떠한 방향에서의 습격도 두려울 게 없소이다.",
  ui_story_5020_50201601_29_dialog_content = "다만 지금처럼 힘이 모자랄 때는...",
  ui_story_5020_50201601_30_dialog_content = "소생의 등을 안심하고 맡겨도 되겠소?",
  ui_story_5020_50201601_31_dialog_content = "후후, 그걸 물어볼 필요가 있어?",
  ui_story_5020_50201601_32_dialog_content = "네가 다치지 않았어도, 우리 사이에 「척귀능인」이라는 연결고리가 없었어도...",
  ui_story_5020_50201601_33_dialog_content = "네가 나랑 함께 싸우는 동료인 이상...",
  ui_story_5020_50201601_34_dialog_content = "도와주지 않을 이유가 없잖아!",
  ui_story_5020_50201601_35_dialog_content = "훗... 허울 좋은 말은 그쯤이면 됐소이다.",
  ui_story_5020_50201601_36_dialog_content = "다음 적이 올 테니 말이오...",
  ui_story_5020_50201601_37_dialog_content = "준비는 되었는가, <color=#FFB400>사매</color>.",
  ui_story_5020_50201601_38_dialog_content = "물론이지! 아직도 힘이 남아돈다구!",
  ui_story_5020_50201601_39_dialog_content = "하아아압!",
  ui_story_5020_50201601_40_dialog_content = "하아... 하...",
  ui_story_5020_50201601_41_dialog_content = "아메모리, 조금만 더 버텨...",
  ui_story_5020_50201601_42_dialog_content = "후우... 당연히 그래야지 않겠소...",
  ui_story_5020_50201601_43_dialog_content = "...요우, 천운참을 잘 쥐시오!",
  ui_story_5020_50201601_44_dialog_content = "주변의 공기가 이상하오...",
  ui_story_5020_50201601_45_dialog_content = "알겠어!",
  ui_story_5020_50201601_46_dialog_content = "근데 뭐가 이상한데...? 그리고 우린 이제 어떡해?",
  ui_story_5020_50201601_47_dialog_content = "...우선 사카이 거리 쪽으로 가는 게 좋겠소.\n부두에 있는 린네와 백성들의 안전을 최대한 확보해야 하오.",
  ui_story_5020_50201601_48_dialog_content = "주변의 소리에 계속 주의하시오...",
  ui_story_5020_50201601_49_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_5020_50201601_50_dialog_content = "<color=#e8d9bb>............</color>",
  ui_story_5020_50201601_51_dialog_content = "(두 시 방향에서 촉유군이 오니와 싸우고 있군...)",
  ui_story_5020_50201601_52_dialog_content = "(열 시 방향은 사람의 발소리...)",
  ui_story_5020_50201601_53_dialog_content = "(일곱 시 방향 숲속에서... 새 여섯 마리가 날아올랐다...)",
  ui_story_5020_50201601_54_dialog_content = "(이상하다... 특이한 동향이 전혀 없다니... 어째서...)",
  ui_story_5020_50201601_55_dialog_content = "......",
  ui_story_5020_50201601_56_dialog_content = "어라? 아메모리! 저기 좀 봐!",
  ui_story_5020_50201601_57_dialog_content = "저기 사람이 있어...",
  ui_story_5020_50201601_58_dialog_content = "아직 피하지 못한 강부성 주민인가?",
  ui_story_5020_50201601_59_dialog_content = "어째서 아직도 성안에...",
  ui_story_5020_50201601_60_dialog_content = "...요우! 조심하시오!",
  ui_story_5020_50201601_61_dialog_content = "뭐, 뭐야?!",
  ui_story_5020_50201601_62_dialog_content = "<anim type=Shake>...그어어...</anim>",
  ui_story_5020_50201601_63_dialog_content = "뭐...뭐라는 거지...?",
  ui_story_5020_50201601_64_dialog_content = "<anim type=Shake>그어어...</anim>",
  ui_story_5020_50201601_65_dialog_content = "<size=50><anim type=Shake>크어어어──!</anim></size>",
  ui_story_5020_50201601_66_dialog_content = "후...후지쿠모?!",
  ui_story_5020_50201601_67_dialog_content = "...이런!",
  ui_story_5020_50201601_68_dialog_content = "(스승님과 겨루고도 온전히 항구까지 찾아오다니...)",
  ui_story_5020_50201601_69_dialog_content = "(서, 설마 스승님께서...)",
  ui_story_5020_50201601_70_dialog_content = "뭐, 뭐야? 이 괴물은?!",
  ui_story_5020_50201601_71_dialog_content = "<anim type=Shake>놓아라...</anim>",
  ui_story_5020_50201601_72_dialog_content = "<anim type=Shake>내려 놓아라...</anim>",
  ui_story_5020_50201601_73_dialog_content = "요우, 천운참을 꽉 잡으시오...",
  ui_story_5020_50201601_74_dialog_content = "지금 놈과 싸운다면 우리에게 승산은 없소.",
  ui_story_5020_50201601_75_dialog_content = "허나 천운참은 절대로 넘겨줘서는 아니 되오!",
  ui_story_5020_50201601_76_dialog_content = "빌어먹을 녀석! 스승님은 어찌 된 것이냐!",
  ui_story_5020_50201601_77_dialog_content = "<anim type=Shake>죽여...</anim>",
  ui_story_5020_50201601_78_dialog_content = "<anim type=Shake>죽였다...</anim>",
  ui_story_5020_50201601_79_dialog_content = "뭐...?!",
  ui_story_5020_50201601_80_dialog_content = "............",
  ui_story_5020_50201601_81_dialog_content = "네 이놈! 가만 두지...",
  ui_story_5020_50201601_82_dialog_content = "크으윽! 콜록콜록...",
  ui_story_5020_50201601_83_dialog_content = "(...이젠... 한계인가...)",
  ui_story_5020_50201601_84_dialog_content = "<color=#e8d9bb>휘이잉── 퍼억!</color>",
  ui_story_5020_50201601_85_dialog_content = "속사 감지!",
  ui_story_5020_50201601_86_dialog_content = "신역을 여기에!",
  ui_story_5020_50201601_87_dialog_content = "너희들...?!",
  ui_story_5020_50201601_88_dialog_content = "둘 다 고생했어!",
  ui_story_5020_50201601_89_dialog_content = "우리 쪽은 말끔히 처리했어! 이제 전력을 다해서 여길 지키자!",
  ui_story_5020_50201601_90_dialog_content = "여러분도 어서 신역 안으로 오십시오, 제가...",
  ui_story_5020_50201601_91_dialog_content = "아니...",
  ui_story_5020_50201601_92_dialog_content = "어, 어째서...",
  ui_story_5020_50201601_93_dialog_content = "<size=45><anim type=Shake>그어어어!</anim></size>",
  ui_story_5020_50201601_94_dialog_content = "<anim type=Shake>린...네...</anim>",
  ui_story_5020_50201601_95_dialog_content = "<anim type=Shake>네가... 어찌...</anim>",
  ui_story_5020_50201601_96_dialog_content = "<size=50><anim type=Shake>크어어어──!</anim></size>",
  ui_story_5020_50201601_97_dialog_content = "후지쿠모 쇼군까지... 저렇게 변한 거야?!",
  ui_story_5020_50201601_98_dialog_content = "쿨럭, 쿨럭... 놈이 어떤 모습이 되든 중요한 게 아니잖소!",
  ui_story_5020_50201601_99_dialog_content = "어서... 천운참으로 놈을 죽이시오...",
  ui_story_5020_50201601_100_dialog_content = "린네! 받아줘!",
  ui_story_5020_50201601_101_dialog_content = "알겠습니다...!",
  ui_story_5020_50201601_102_dialog_content = "(이것이... 무녀 대대로 내려오던 신기...)",
  ui_story_5020_50201601_103_dialog_content = "(본디 무녀가 지녀야 할 물건이나... 쇼군이 숨겨두었던 참귀의 검...)",
  ui_story_5020_50201601_104_dialog_content = "<color=#e8d9bb>터벅... 터벅... 터벅...</color>",
  ui_story_5020_50201601_105_dialog_content = "(아... 합하... 어쩌면... 마지막으로 아버님이라고 불러야 하는 것일지요...)",
  ui_story_5020_50201601_106_dialog_content = "(천운참을 쥔 손이... 아무리 참아봐도 떨림이 멈추질 않습니다...)",
  ui_story_5020_50201601_107_dialog_content = "(공포와 긴장, 흥분이 뒤섞인 이 감정을 어찌 해야 하는 것인지...)",
  ui_story_5020_50201601_108_dialog_content = "(당신은... 한 번도 가르쳐 주시지 않았습니다...)",
  ui_story_5020_50201601_109_dialog_content = "<size=50><anim type=Shake>크어어어──!</anim></size>",
  ui_story_5020_50201601_110_dialog_content = "아버님...",
  ui_story_5020_50201601_111_dialog_content = "부디... 받아 주십시오!",
  ui_story_5020_50201602_1_dialog_content = "<anim type=Shake>크어억...</anim>",
  ui_story_5020_50201602_2_dialog_content = "하아... 하아...",
  ui_story_5020_50201602_3_dialog_content = "린네, 어서! 지금이오!",
  ui_story_5020_50201602_4_dialog_content = "하앗──!",
  ui_story_5020_50201602_5_dialog_content = "<size=50><anim type=Shake>크어어어어어어어!</anim></size>",
  ui_story_5020_50201602_6_dialog_content = "<anim type=Shake>스으으윽──</anim>",
  ui_story_5020_50201602_7_dialog_content = "<anim type=Shake>허억... 허억... 헉...</anim>",
  ui_story_5020_50201602_8_dialog_content = "쇼, 쇼군...?",
  ui_story_5020_50201602_9_dialog_content = "해냈어!",
  ui_story_5020_50201602_10_dialog_content = "오니의 모습을 베어서 다시 사람으로 만들다니...",
  ui_story_5020_50201602_11_dialog_content = "이것이 천운참의 힘인가...",
  ui_story_5020_50201602_12_dialog_content = "린네... 그대들은... 역시 천운참을 가지고 온 것이냐...",
  ui_story_5020_50201602_13_dialog_content = "아주... 잘했다...",
  ui_story_5020_50201602_14_dialog_content = "이쪽으로 오거라...",
  ui_story_5020_50201602_15_dialog_content = "쇼군...",
  ui_story_5020_50201602_16_dialog_content = "당신은 결코 용서받을 수 없는 일을 너무나도 많이 했습니다...",
  ui_story_5020_50201602_17_dialog_content = "당신에게 어쩔 수 없는 사정이 있었다고 해도...\n그것은 그렇게 힘을 추구할 이유가 되지 않습니다.",
  ui_story_5020_50201602_18_dialog_content = "강부성의 불길은 이미 사그라들었습니다.",
  ui_story_5020_50201602_19_dialog_content = "...당신도 이제 멈추어 쉬실 때가 되었습니다.",
  ui_story_5020_50201602_20_dialog_content = "어쩔 수 없다? 하하...",
  ui_story_5020_50201602_21_dialog_content = "...그 편지를 읽은 것이로구나.",
  ui_story_5020_50201602_22_dialog_content = "네가 보았던 그 「어쩔 수 없는」 일들 외에도,\n네가 이해할 수 없는 것은 아직도 많이 있느니라.",
  ui_story_5020_50201602_23_dialog_content = "허나, 「어쩔 수 없다」 같은 말은 본디 아이가 꺼낼 말이 아니다.",
  ui_story_5020_50201602_24_dialog_content = "린네... 이제 다 자랐구나.",
  ui_story_5020_50201602_25_dialog_content = "이제는... 「합하」라고 부르지도 않겠다는 것이냐.",
  ui_story_5020_50201602_26_dialog_content = "......",
  ui_story_5020_50201602_27_dialog_content = "흥, 그런 말은 네놈한텐 안 어울려!",
  ui_story_5020_50201602_28_dialog_content = "후지쿠모, 네놈의 명운도 여기까지다.",
  ui_story_5020_50201602_29_dialog_content = "주위를 살펴봐라.",
  ui_story_5020_50201602_30_dialog_content = "퉷! 꼴 좋다!",
  ui_story_5020_50201602_31_dialog_content = "그래! 무릎을 꿇고 고개도 숙이라고!\n...하하하! 천하의 후지쿠모 쇼군 나리한테도 이런 날이 오다니!",
  ui_story_5020_50201602_32_dialog_content = "뭘 시답잖게 떠들고 있어! 냉큼 베어버리면 되지!\n형제들이여! 가서 놈을 베고 춘일제에 바치는 거다!",
  ui_story_5020_50201602_33_dialog_content = "죽여라! 죽여!",
  ui_story_5020_50201602_34_dialog_content = "하하... 하하하하...",
  ui_story_5020_50201602_35_dialog_content = "무엄하다!",
  ui_story_5020_50201602_36_dialog_content = "간악한 우민들! 물러나라!\n합하를 해치는 것은 본도를 적으로 돌리는 일임을 모르느냐!",
  ui_story_5020_50201602_37_dialog_content = "퉷! 본도가 뭐라고!",
  ui_story_5020_50201602_38_dialog_content = "네놈들 무사 몇 명으로 뭘 어쩔 수 있을 줄 알고?\n후지쿠모, 네 꼴을 봐라!",
  ui_story_5020_50201602_39_dialog_content = "형제들이여, 쳐라!",
  ui_story_5020_50201602_40_dialog_content = "<color=#e8d9bb>치잉──</color>",
  ui_story_5020_50201602_41_dialog_content = "누가 감히!",
  ui_story_5020_50201602_42_dialog_content = "물러서라... 쿨럭쿨럭... 어서 물러서지 못할까...",
  ui_story_5020_50201602_43_dialog_content = "합하께서 돌아가시면, 운도가 더 좋아질 것이라 생각하느냐!",
  ui_story_5020_50201602_44_dialog_content = "......",
  ui_story_5020_50201602_45_dialog_content = "네놈들이 지금의 쇼군을 없앤다 한들...",
  ui_story_5020_50201602_46_dialog_content = "보름도 안 돼서 본도에서는 새로운 쇼군을 보내 운도를 지배할 것이다!",
  ui_story_5020_50201602_47_dialog_content = "그때가 되면 네놈들이 또 누굴 원망할 수 있겠느냐!",
  ui_story_5020_50201602_48_dialog_content = "네놈들 역적들의 눈에는 합하가 물리쳐야 할 외지인으로 보이겠지만...",
  ui_story_5020_50201602_49_dialog_content = "합하께서 하신 일은 모두 운도를 위해서였다!",
  ui_story_5020_50201602_50_dialog_content = "여봐라... 누구 없느냐! 이 놈을... 당장 끌어내라...",
  ui_story_5020_50201602_51_dialog_content = "(후지쿠모... 뭔가 말하고 싶은 게 있는 것 같은데...)",
  ui_story_5020_50201602_52_dialog_content = "아닙니다, 합하! 계속하게 해 주십시오!",
  ui_story_5020_50201602_53_dialog_content = "....합하께서 본도와 운도 세력 간의 균형을 지키고...",
  ui_story_5020_50201602_54_dialog_content = "운도의 평화를 위해 애써 오신 노고를... 네놈들은 아느냔 말이다!",
  ui_story_5020_50201602_55_dialog_content = "설령 네놈들 말처럼 합하의 수단에 폐단이 있었다 한들...",
  ui_story_5020_50201602_56_dialog_content = "합하께서 추구하신 결과가 정녕 틀린 것이었느냔 말이다!",
  ui_story_5020_50201602_57_dialog_content = "......",
  ui_story_5020_50201602_58_dialog_content = "말은 틀린 것 같지만...",
  ui_story_5020_50201602_59_dialog_content = "결과는 어째 저 사람 말이 맞는 것 같기도 하단 말이지...",
  ui_story_5020_50201602_60_dialog_content = "나도 사실 계속 같은 생각이었어. 하지만 주변 녀석들은 전부 보는 눈이 없어서...\n높은 사람들이 하는 일 같은 건 이해를 못했다고...",
  ui_story_5020_50201602_61_dialog_content = "만약 내가 운도를 통치했으면 저 후지쿠모보다는 몇백 배는 더 잘했을 거다!",
  ui_story_5020_50201602_62_dialog_content = "그게 무슨 헛소리야? 저놈 말 몇 마디에 홀랑 넘어가는 거냐!",
  ui_story_5020_50201602_63_dialog_content = "놈들 편이 될 거면 나부터 상대해 주마!\n너 같은 역적을 가만 놔둘 순 없지!",
  ui_story_5020_50201602_64_dialog_content = "<color=#e8d9bb>웅성웅성... 웅성웅성...</color>",
  ui_story_5020_50201602_65_dialog_content = "...합하께서 네놈들의 이해 따위를 바라실 성싶으냐?",
  ui_story_5020_50201602_66_dialog_content = "네놈들의 이해 따위는 합하께 있어서는 모욕일 뿐이다!",
  ui_story_5020_50201602_67_dialog_content = "그만 닥치거라...",
  ui_story_5020_50201602_68_dialog_content = "합하의 말씀대로 모두 닥쳐라!",
  ui_story_5020_50201602_69_dialog_content = "진정 합하의 뜻을 이해할 수 있는 자는 드문 법...",
  ui_story_5020_50201602_70_dialog_content = "합하, 소신은 이 세상에서 합하의 뜻을 가장 잘 이해하고 있습니다!",
  ui_story_5020_50201602_71_dialog_content = "지겹지도 않냐!",
  ui_story_5020_50201602_72_dialog_content = "그 무식한 입은 그만 다물지 그래.",
  ui_story_5020_50201602_73_dialog_content = "누, 누구냐?!",
  ui_story_5020_50201602_74_dialog_content = "......",
  ui_story_5020_50201602_75_dialog_content = "왔는가...",
  ui_story_5020_50201701_1_dialog_content = "저, 저 사람은...?!",
  ui_story_5020_50201701_2_dialog_content = "아직 살아 있었다니...",
  ui_story_5020_50201701_3_dialog_content = "아빠... 저 사람이 누군데?",
  ui_story_5020_50201701_4_dialog_content = "쉿!",
  ui_story_5020_50201701_5_dialog_content = "멋대로 말하면 안 돼!",
  ui_story_5020_50201701_6_dialog_content = "(스승님?!)",
  ui_story_5020_50201701_7_dialog_content = "하하...",
  ui_story_5020_50201701_8_dialog_content = "참으로 감동적인 연설이로구나.",
  ui_story_5020_50201701_9_dialog_content = "이처럼 쇼군을 잘 모욕하는 가신도 있었다니.",
  ui_story_5020_50201701_10_dialog_content = "무슨...",
  ui_story_5020_50201701_11_dialog_content = "크억!",
  ui_story_5020_50201701_12_dialog_content = "날 방해하지 마라.",
  ui_story_5020_50201701_13_dialog_content = "......",
  ui_story_5020_50201701_14_dialog_content = "후지쿠모, 이 순간을 쭉 기다리고 있었겠지.",
  ui_story_5020_50201701_15_dialog_content = "이제야 온 것인가.",
  ui_story_5020_50201701_16_dialog_content = "이미 아까 전에 와 있었다.",
  ui_story_5020_50201701_17_dialog_content = "저 무사가 널 괴롭히게 잠깐 놔두는 것도 나쁘진 않았거든.",
  ui_story_5020_50201701_18_dialog_content = "네놈이 지금 가장 원하는 건 인정받는 게 아니라 곧 다가올 죽음이겠지.",
  ui_story_5020_50201701_19_dialog_content = "어때, 아닌가?",
  ui_story_5020_50201701_20_dialog_content = "...허허.",
  ui_story_5020_50201701_21_dialog_content = "전장에서 죽는 건 결코 비극이 아니라... 영웅다운 귀결이다.",
  ui_story_5020_50201701_22_dialog_content = "어서 끝내라...",
  ui_story_5020_50201701_23_dialog_content = "나를 죽이는 자가 그대라면...",
  ui_story_5020_50201701_24_dialog_content = "후지쿠모, 네놈은 평생 비열한 수를 부려왔건만...",
  ui_story_5020_50201701_25_dialog_content = "그럼에도 마지막만큼은 체면을 세우고 싶다는 것이냐.",
  ui_story_5020_50201701_26_dialog_content = "하하하하하... 콜록콜록...",
  ui_story_5020_50201701_27_dialog_content = "나기, 그대의 검술은 항상 날카롭고 깔끔했지...",
  ui_story_5020_50201701_28_dialog_content = "자신을 욕보이는 일이 없도록 주저하지 말고 휘두르는 게 좋을 게다.",
  ui_story_5020_50201701_29_dialog_content = "흥, 괜한 염려다.",
  ui_story_5020_50201701_30_dialog_content = "<color=#e8d9bb>치잉──</color>",
  ui_story_5020_50201701_31_dialog_content = "......",
  ui_story_5020_50201701_32_dialog_content = "그 전에 마지막으로 남길 말은 없는가.",
  ui_story_5020_50201701_33_dialog_content = "......",
  ui_story_5020_50201701_34_dialog_content = "츠키여...",
  ui_story_5020_50201701_35_dialog_content = "지금의 강부성은... 네가 보고 싶었던 모습이더냐...",
  ui_story_5020_50201701_36_dialog_content = "......",
  ui_story_5020_50201701_37_dialog_content = "............",
  ui_story_5020_50201701_38_dialog_content = "주...죽은 거야...?",
  ui_story_5020_50201701_39_dialog_content = "죽은 거지?",
  ui_story_5020_50201701_40_dialog_content = "죽은 것 같아...",
  ui_story_5020_50201701_41_dialog_content = "죽었어! 죽었다고... 진짜 죽었어!",
  ui_story_5020_50201701_42_dialog_content = "후지쿠모가 죽었다! 이제 운도에 쇼군은 없다!",
  ui_story_5020_50201701_43_dialog_content = "<size=50><anim type=Shake>우오오오오오──!</anim></size>",
  ui_story_5020_50201701_44_dialog_content = "<size=50><anim type=Shake>쇼군이 죽었다──!</anim></size>",
  ui_story_5020_50201701_45_dialog_content = "<size=50><anim type=Shake>운도 만세──!</anim></size>",
  ui_story_5020_50201701_46_dialog_content = "<anim type=Shake>오오오오──</anim>",
  ui_story_5020_50201701_47_dialog_content = "......",
  ui_story_5020_50201701_48_dialog_content = "초...총통!",
  ui_story_5020_50201701_49_dialog_content = "사, 살아계셨습니까?",
  ui_story_5020_50201701_50_dialog_content = "정말 나기 님이십니까?",
  ui_story_5020_50201701_51_dialog_content = "총통? 어, 어딜 가시려는 겁니까?!",
  ui_story_5020_50201701_52_dialog_content = "잠깐만요!",
  ui_story_5020_50201701_53_dialog_content = "...?",
  ui_story_5020_50201701_54_dialog_content = "너희인가.",
  ui_story_5020_50201701_55_dialog_content = "굳이 작별 인사를 해야겠다면, 좀 빨리해줬으면 좋겠군.",
  ui_story_5020_50201701_56_dialog_content = "스승님, 잠시만요!",
  ui_story_5020_50201701_57_dialog_content = "저, 스승님... 정말 감사합니다!",
  ui_story_5020_50201701_58_dialog_content = "...무슨 말이냐.",
  ui_story_5020_50201701_59_dialog_content = "전 이번에 운도에 와서 여러 가지로 참 힘들었어요.\n전부 스승님 덕분이에요!",
  ui_story_5020_50201701_60_dialog_content = "(...그거 어떻게 들어도 좋은 말이 아니잖아!)",
  ui_story_5020_50201701_61_dialog_content = "전 스승님 덕분에 지난 세대의 선배들이 겪었던 저마다의 입장과 다툼을 알 수 있었어요.",
  ui_story_5020_50201701_62_dialog_content = "그건... 지금까지 제 인생에서는 전혀 경험해 본 적 없는 것들이었어요.",
  ui_story_5020_50201701_63_dialog_content = "그러니까 앞으로도 계속해서 스승님이라고 부르고 싶어요.",
  ui_story_5020_50201701_64_dialog_content = "앞으로 뭔가 곤란한 일이 있으시면...\n아스트라 대륙 움브라톤의 린 가문 상회로 연락해 주세요!",
  ui_story_5020_50201701_65_dialog_content = "이 요우, 어디 있든지 반드시 스승님께 가서 도와드리겠습니다!",
  ui_story_5020_50201701_66_dialog_content = "하하... 고맙구나, 요우.",
  ui_story_5020_50201701_67_dialog_content = "허나 앞으로의 길은 나 혼자서 걸어야만 한다.",
  ui_story_5020_50201701_68_dialog_content = "내 손으로 운도에 대한 본도의 통치를 끝내야만,\n비로소 이 원한의 역사를 진정으로 끝마칠 수 있다.",
  ui_story_5020_50201701_69_dialog_content = "이제... 본도로 가시는 것입니까.",
  ui_story_5020_50201701_70_dialog_content = "스승님, 부디...",
  ui_story_5020_50201701_71_dialog_content = "존체를 보중하시고, 운도를 위해 새로운 세상을 열어 주십시오.",
  ui_story_5020_50201701_72_dialog_content = "소생과 촉유군은 영원히 스승님의 힘이 될 것입니다.",
  ui_story_5020_50201701_73_dialog_content = "호오? 아메모리...",
  ui_story_5020_50201701_74_dialog_content = "드디어 성장했구나.",
  ui_story_5020_50201701_75_dialog_content = "너라면 앞으로도 촉유군을 나보다 더 잘 이끌 수 있을 거다.",
  ui_story_5020_50201701_76_dialog_content = "나기 님! 보중하십시오! 승리하여 돌아오실 날을 기다리고 있겠습니다!",
  ui_story_5020_50201701_77_dialog_content = "......",
  ui_story_5020_50201701_78_dialog_content = "그럼, 또 보자고.",
  ui_story_5020_50201701_79_dialog_content = "아! 잠깐만요! 하나 더 있는데요...",
  ui_story_5020_50201701_80_dialog_content = "PlayerName, 그거 나기 씨한테 주자.",
  ui_story_5020_50201701_81_dialog_content = "아, 그렇네!",
  ui_story_5020_50201701_82_dialog_content = "으음?",
  ui_story_5020_50201701_83_dialog_content = "나기 씨, 이 일기도 가져가세요.",
  ui_story_5020_50201701_84_dialog_content = "비록 그분께서 직접 말씀을 남기지는 않으셨지만...",
  ui_story_5020_50201701_85_dialog_content = "그분께서 남긴 것이라면, 당신께도 필시 소중한 것이겠지요.",
  ui_story_5020_50201701_86_dialog_content = "그것은 역시 당신이 가지고 있는 것이 좋겠습니다.",
  ui_story_5020_50201701_87_dialog_content = "츠키... 일기 쓰는 습관도 있었나...",
  ui_story_5020_50201701_88_dialog_content = "지금까지 전혀 몰랐구나...",
  ui_story_5020_50201701_89_dialog_content = "허나 난 이제 그 무엇도 돌아보지 않고 본도로 갈 생각이다.",
  ui_story_5020_50201701_90_dialog_content = "그러니 그것은 너희가 대신 가지고 있어라.",
  ui_story_5020_50201701_91_dialog_content = "정말... 안 읽어봐도 되겠어요?",
  ui_story_5020_50201701_92_dialog_content = "전 과거를 털어내려면... 과거로부터 도망치기보다는...\n먼저 온전히 과거를 마주해야 한다고 생각해요.",
  ui_story_5020_50201701_93_dialog_content = "만약 나기 씨한테 의문이나 원망이 남아 있다면...\n이 일기가 답을 줄지도 모르잖아요.",
  ui_story_5020_50201701_94_dialog_content = "......",
  ui_story_5020_50201701_95_dialog_content = "좋다.",
  ui_story_5020_50201701_96_dialog_content = "......",
  ui_story_5020_50201701_97_dialog_content = "............",
  ui_story_5020_50201701_98_dialog_content = "<size=30>언니...</size>",
  ui_story_5020_50201701_99_dialog_content = "언니......",
  ui_story_5020_50201701_100_dialog_content = "<color=#e8d9bb>강부성 번화가의 어느 거리</color>",
  ui_story_5020_50201701_101_dialog_content = "어머, 참으로 정다운 풍경이로군요.",
  ui_story_5020_50201701_102_dialog_content = "화려한 장막의 무대... 시작을 기다리는 북, 벚꽃 아래서 금붕어 낚시를 즐기는 사람들...",
  ui_story_5020_50201701_103_dialog_content = "그리고 얌전히 제 곁에 앉아 소란을 피우지 않는 닌자 나리도 말이지요.",
  ui_story_5020_50201701_104_dialog_content = "소생을 그렇게 부르지 마시오.",
  ui_story_5020_50201701_105_dialog_content = "모모와 안즈의 성의를 헛되게 하면 안 돼요. 그 차, 정말 맛있답니다.",
  ui_story_5020_50201701_106_dialog_content = "...나는 맛이 진한 것은 좋아하지 않소이다.\n이 가게에서는 아무것도 입에 댈 생각이 없소.",
  ui_story_5020_50201701_107_dialog_content = "(꼬르륵...)",
  ui_story_5020_50201701_108_dialog_content = "으윽...!",
  ui_story_5020_50201701_109_dialog_content = "네~ 오래 기다리셨습니다!",
  ui_story_5020_50201701_110_dialog_content = "우리 가게에서 특별히 출시한 신제품! 흐르는 소면 등장!",
  ui_story_5020_50201701_111_dialog_content = "이건 요우 씨가 몇 번이나 시식하고 엄선해서 완성한 우리 가게만의 독점 메뉴야!",
  ui_story_5020_50201701_112_dialog_content = "꺼억... 배불러...",
  ui_story_5020_50201701_113_dialog_content = "(요우가... 벌써 배가 부르다고?!)",
  ui_story_5020_50201701_114_dialog_content = "그...그렇다면...",
  ui_story_5020_50201701_115_dialog_content = "어쩔 수 없이 소생도 한입 거들어 주겠소.",
  ui_story_5020_50201701_116_dialog_content = "신제품도 나왔으니까 새로 들려줄 이야기도 얼른 준비해야지!",
  ui_story_5020_50201701_117_dialog_content = "맨날 똑같은 이야기만 들려주면 새로운 손님들이 안 와준다구!",
  ui_story_5020_50201701_118_dialog_content = "PlayerName 씨는 어떤 이야기가 좋을 것 같아?",
  ui_story_5020_50201701_119_dialog_content = "뭐? 나한테 물어보는 거야?",
  ui_story_5020_50201701_120_dialog_content = "내 취향대로 말하자면...",
  ui_story_5020_50201701_121_option_content = "「세 사람의 인연」은 어때?",
  ui_story_5020_50201701_122_dialog_content = "평생 끊을 수 없는 인연으로 이어진 세 사람이...\n저마다의 방식으로 한 땅을 지키고 있었고...",
  ui_story_5020_50201701_123_dialog_content = "서로 다른 길을 걸을 수밖에 없었던 자매는...\n두 사람의 노래를 이 땅에 오래도록 전했다.",
  ui_story_5020_50201701_124_dialog_content = "사람들에게 이해받지 못한 무녀와 쇼군은...\n비록 서로 다른 처지였지만 서로를 신뢰했고...",
  ui_story_5020_50201701_125_dialog_content = "서로 적이 될 운명이었던 전사들은 마지막 싸움에서...\n상대를 이해하면서 마지막 작별을 고했다.",
  ui_story_5020_50201701_126_dialog_content = "그들은 모두 마음속으로 이 땅의 모습을 그렸다...\n그들이 꿈꾸는 방법대로 평화를 향해 나아갈 것이라고...",
  ui_story_5020_50201701_127_dialog_content = "그런 얘기를... 밥 먹으면서 들어도 되겠어?!",
  ui_story_5020_50201701_128_option_content = "「세 아이 이야기」는 어때?",
  ui_story_5020_50201701_129_dialog_content = "저마다 비범한 재능을 타고난 세 아이가...\n저마다 다른 이유로 요괴 퇴치 여행을 떠났다...",
  ui_story_5020_50201701_130_dialog_content = "하지만 그 과정에서 세 사람은 승리보다 더 갚진 것을 얻을 수 있었다.",
  ui_story_5020_50201701_131_dialog_content = "견고한 가면을 쓴 양철 인간은「우정이 가득한 마음」을 얻었고...",
  ui_story_5020_50201701_132_dialog_content = "바닷물에 잠겼던 허수아비는 「추억이 가득한 뇌」를 얻었다.",
  ui_story_5020_50201701_133_dialog_content = "공연 복장을 입은 어린 사자는 「운명에 맞설 용기」를 얻었고...",
  ui_story_5020_50201701_134_dialog_content = "북방 동화를 표절하면 어떡해! 너무 뜬금없잖아!",
  ui_story_5020_50201701_135_dialog_content = "음... 그것도 꽤 괜찮은 생각인데?",
  ui_story_5020_50201701_136_dialog_content = "그럼 PlayerName 씨 말대로 써볼게!",
  ui_story_5020_50201701_137_dialog_content = "근데 그 전에 지난번 운도 전설의 진짜 결말부터 얘기해야겠지...",
  ui_story_5020_50201701_138_dialog_content = "진짜 결말? 그럼 우리가 지금 와서도 아직 모르는 게 있었단 말이야?",
  ui_story_5020_50201701_139_dialog_content = "후후후... 그건 말이지. 알바생한테서 얻은 지 얼마 안 된 정보가 있거든!",
  ui_story_5020_50201701_140_dialog_content = "듣고 싶어? 간단해~ 주문만 하면...",
  ui_story_5020_50201701_141_dialog_content = "한 그릇 더.",
  ui_story_5020_50201701_142_dialog_content = "역시 뭘 좀 아는 손님이네! 그럼 지난번 이야기는 어디까지 했더라...",
  ui_story_5020_50201701_143_dialog_content = "「후지쿠모는 불사신이고, 피도 눈물도 없는 자라고 한다」\n운도의 그 누구도 그의 약점을 알지 못했다. 오직 한 사람...",
  ui_story_5020_50201701_144_dialog_content = "짜잔! 우리 카야노만 빼고 말이야!",
  ui_story_5020_50201701_145_dialog_content = "으엑? 너...너무 갑작스럽잖아요... 저, 절 부르셨나요...",
  ui_story_5020_50201701_146_dialog_content = "이리 와, 알바생~ PlayerName 씨한테 들려줘.\n네가 땡땡이 쳤던 날 뭘 봤는지 말이야.",
  ui_story_5020_50201701_147_dialog_content = "저, 저는... 그날 교외의 <color=#FFB400>묘지</color>에서 벚꽃 구경을 했습니다...\n지금은 마침 하얀 벚꽃이 날리는 계절이거든요...",
  ui_story_5020_50201701_148_dialog_content = "입구에 도착했는데... 묘지 안에는 먼저 온 사람이 있었어요...",
  ui_story_5020_50201701_149_dialog_content = "?!",
  ui_story_5020_50201701_150_dialog_content = "(우리보다 먼저 묘지에 있었던 그자인가!)",
  ui_story_5020_50201701_151_dialog_content = "그게... 대체 누구였어?!",
  ui_story_5020_50201701_152_dialog_content = "아아... PlayerName 님... 너, 너무 사납습니다...",
  ui_story_5020_50201701_153_dialog_content = "미, 미안...",
  ui_story_5020_50201701_154_dialog_content = "상대는 저를 알아채지 못했습니다... 하지만 전 분명히 봤습니다...",
  ui_story_5020_50201701_155_dialog_content = "그 사람은... <color=#FFB400>후지쿠모 쇼군</color>이었습니다...",
  ui_story_5020_50201701_156_dialog_content = "......",
  ui_story_5020_50201701_157_dialog_content = "누구의 무덤인지는 모르겠지만 조용히 그 앞에 서 있었고...\n병사들도 거느리고 있지 않았습니다...",
  ui_story_5020_50201701_158_dialog_content = "저는... 분명히 쇼군이 무덤에 있는 검을 가지고 가려는 줄 알았습니다...\n하지만 그렇지 않았습니다...",
  ui_story_5020_50201701_159_dialog_content = "오히려... 떠나기 전에 그 자리에 책 같은 것을 정중하게 두고 갔습니다...",
  ui_story_5020_50201701_160_dialog_content = "그...그러다가 전 들킬 뻔해서... 재빨리 도망쳐 버렸습니다...",
  ui_story_5020_50201701_161_dialog_content = "......",
  ui_story_5020_50201701_162_dialog_content = "역시 후지쿠모였단 말인가...",
  ui_story_5020_50201701_163_dialog_content = "바로 그거야! 무자비한 전대 쇼군이 아무도 없는 묘지에서...\n몰래 고인을 그리워하고 있었던 거지...",
  ui_story_5020_50201701_164_dialog_content = "후후후, 이런 이야기라면 분명히 새로운 손님들을 끌어모을 수 있을 거야!",
  ui_story_5020_50201701_165_dialog_content = "잠깐만, 근데 그건...",
  ui_story_5020_50201701_166_dialog_content = "괜찮습니다, PlayerName 님.",
  ui_story_5020_50201701_167_dialog_content = "혹여 그것이... 쇼군과 전임 무녀가 운도에 남길 수 있는 마지막 모습이라면...",
  ui_story_5020_50201701_168_dialog_content = "저는 그러한 모습으로 운도의 과거에 종지부를 찍는 것도 좋다고 생각합니다.",
  ui_story_5020_50201701_169_dialog_content = "이제는 새로운 시대가...",
  ui_story_5020_50201701_170_dialog_content = "시작되었으니 말이지요.",
  ui_story_5020_50201701_171_dialog_content = "<color=#e8d9bb>......</color>",
  ui_story_5020_50201701_172_dialog_content = "길을 비켜라! 여기다 노점을 차리지 마라!\n본성으로 향하는 길을 막아선 안 된다!",
  ui_story_5020_50201701_173_dialog_content = "본성? 그딴 게 어디 있다고 그래? 어디서 왔수?",
  ui_story_5020_50201701_174_dialog_content = "......",
  ui_story_5020_50201701_175_dialog_content = "보시지요. 본도가 벌써 행동을 시작했습니다.\n저 사람들이 입은 옷의 문양은 본도의 것입니다.",
  ui_story_5020_50201701_176_dialog_content = "역시 저들은 운도에 대한 관할권을 포기할 생각이 없는 모양이로군요.",
  ui_story_5020_50201701_177_dialog_content = "린네 씨, 이대로... 계속 여기 머무를 건가요?",
  ui_story_5020_50201701_178_dialog_content = "후훗, 어떻게 할지는 이미 결정했습니다. 그보다 여러분은...",
  ui_story_5020_50201701_179_dialog_content = "어떻게 돌아가실 생각이신지요.",
  ui_story_5020_50201701_180_dialog_content = "걱정할 거 없어. 우린 콜로서스를 타고 왔던 길로 돌아가기만 하면 되니까.",
  ui_story_5020_50201701_181_dialog_content = "그러고 보니... 스카이워커도 제대로 수리해야 하는데 말이지...",
  ui_story_5020_50201701_182_dialog_content = "...콜로서스? 스카이...워커?",
  ui_story_5020_50201701_183_dialog_content = "어머, 모두 들어본 적이 없는 말이로군요...",
  ui_story_5020_50201701_184_dialog_content = "아무래도 역시 저도 바깥세상을 조금 다녀볼 필요가 있는 모양입니다.",
  ui_story_5020_50201701_185_dialog_content = "<color=#e8d9bb>강부성 항구, 부둣가</color>",
  ui_story_5020_50201701_186_dialog_content = "자, 자, 됐어. 배웅은 여기까지만 해주면 돼!",
  ui_story_5020_50201701_187_dialog_content = "이제 곧 배도 올 테니까.",
  ui_story_5020_50201701_188_dialog_content = "흥.",
  ui_story_5020_50201701_189_dialog_content = "꼭 그대를 배웅하려던 것은 아니었소...",
  ui_story_5020_50201701_190_dialog_content = "소생은 그저 운도의 예법에 따라 손님을 대했을 뿐이오.",
  ui_story_5020_50201701_191_dialog_content = "아, 아메모리...",
  ui_story_5020_50201701_192_dialog_content = "역시... 난...",
  ui_story_5020_50201701_193_dialog_content = "<size=45>흐아아아앙──!</size>",
  ui_story_5020_50201701_194_dialog_content = "무, 무, 무슨 짓이오! 가, 갑자기!",
  ui_story_5020_50201701_195_dialog_content = "흐아아앙... 아메모리 너도 역시 나랑 헤어지는 게 아쉬웠구나! 난...",
  ui_story_5020_50201701_196_dialog_content = "<size=50><anim type=Shake>모두랑 헤어지는 게 너무 슬퍼어어──!</anim></size>",
  ui_story_5020_50201701_197_dialog_content = "자, 요우, 착한 아이는 울면 안 돼요.",
  ui_story_5020_50201701_198_dialog_content = "우린 또 만날 기회가 있을 테니까요.",
  ui_story_5020_50201701_199_dialog_content = "으앗... 뭐, 뭐라고?",
  ui_story_5020_50201701_200_dialog_content = "린네... 너...",
  ui_story_5020_50201701_201_dialog_content = "<size=50><anim type=Shake>흐아아아앙! 정말 나랑 같이 안 가는 거야?!</anim></size>",
  ui_story_5020_50201701_202_dialog_content = "<size=55><anim type=Shake>흐아아아아앙...</anim></size>",
  ui_story_5020_50201701_203_dialog_content = "어머... 정말 큰일이네요...",
  ui_story_5020_50201701_204_dialog_content = "요우, 제 말을 들어주세요.",
  ui_story_5020_50201701_205_dialog_content = "전 아직 운도에서 해야 할 일이 많아요...",
  ui_story_5020_50201701_206_dialog_content = "본도의 세력이 이미 움직이기 시작한 이상... 누군가는 여기서 저들을 견제해야 해요.",
  ui_story_5020_50201701_207_dialog_content = "구름의 거울과 천운참은... 제가 잘 보관해 두었어요.",
  ui_story_5020_50201701_208_dialog_content = "지금부터는 저 자신의 힘으로 이 운도에 평화를 가져올 생각이에요.",
  ui_story_5020_50201701_209_dialog_content = "물론...아메모리가 촉유군을 이끌고 저를 도와줄 거예요. 그렇지요?",
  ui_story_5020_50201701_210_dialog_content = "당연하지 않은가.",
  ui_story_5020_50201701_211_dialog_content = "그대가 말을 하지 않아도, 본도 세력에 대항하는 것은 촉유군의 사명이오.",
  ui_story_5020_50201701_212_dialog_content = "그러니까... 요우, 저는 운도에 더 많은 변화를 가져올 거예요.",
  ui_story_5020_50201701_213_dialog_content = "저를 믿어주시겠어요?",
  ui_story_5020_50201701_214_dialog_content = "흐아앙... 물론 린네라면 분명히 잘할 거라고 믿어...",
  ui_story_5020_50201701_215_dialog_content = "그럼... 린네, 아메모리... 그리고 카야노, 모모, 안즈...",
  ui_story_5020_50201701_216_dialog_content = "다들 건강해야 해!",
  ui_story_5020_50201701_217_dialog_content = "그리고... PlayerName, 바이스!",
  ui_story_5020_50201701_218_dialog_content = "으, 응?",
  ui_story_5020_50201701_219_dialog_content = "정말 고마워... 힘든 의뢰였는데 받아주고, 날 여기까지 데려와 줘서 고마워.",
  ui_story_5020_50201701_220_dialog_content = "게다가 기억만큼이나 소중한 친구들도 생겼고...",
  ui_story_5020_50201701_221_dialog_content = "이 섬에서 얻은 건 나한테 일생 최고의 소중한 보물이야!",
  ui_story_5020_50201701_222_dialog_content = "훌쩍...",
  ui_story_5020_50201701_223_dialog_content = "(이런... 얼른 위로해줘야 되는데...)",
  ui_story_5020_50201701_224_dialog_content = "그러니까...",
  ui_story_5020_50201701_225_dialog_content = "린 가문에 돌아가면, 7자릿수 이상의 돈을 네 계좌에 넣어줄게!",
  ui_story_5020_50201701_226_dialog_content = "뭐?!",
  ui_story_5020_50201701_227_dialog_content = "...안 되는 거야?! 그, 그거 말고는 어떻게 감사의 뜻을 표현해야 할지 모르겠다구!",
  ui_story_5020_50201701_228_dialog_content = "이...이미 너무 많아!",
  ui_story_5020_50201701_229_dialog_content = "아... 그럼 이번 수입을 어떻게 쓸지 계획을 확실히 세워야겠어.\n일단 콜로서스부터 수리하고, 그다음엔...",
  ui_story_5020_50201701_230_dialog_content = "(벌써 받아서 쓸 생각밖에 없는 거냐고!)",
  ui_story_5020_50201701_231_dialog_content = "흐음? 저기 배가 오고 있소.",
  ui_story_5020_50201701_232_dialog_content = "<color=#e8d9bb>뚜우우──</color>",
  ui_story_5020_50201701_233_dialog_content = "으윽... 우웨엑──",
  ui_story_5020_50201701_234_dialog_content = "이게 바로... 바다의 힘이라는 것인가...",
  ui_story_5020_50201701_235_dialog_content = "으앗! 어, 언니, 그러지 마... 나까지 무서워졌잖아!",
  ui_story_5020_50201701_236_dialog_content = "절대 다른 사람한테 알려지면 안 돼...\n린 가문의 명성이 자자한 리잉의 약점이... 배멀미라고 말이야!",
  ui_story_5020_50201701_237_dialog_content = "으어... 소리 지르지 마... 우욱...",
  ui_story_5020_50201701_238_dialog_content = "흐아아아앙!",
  ui_story_5020_50201701_239_dialog_content = "단골 씨... 한 끼에 일곱 그릇 먹는 우리 단골 씨...",
  ui_story_5020_50201701_240_dialog_content = "꼭 다시 운도에 와줘...",
  ui_story_5020_50201701_241_dialog_content = "해가 라면을 잊지 말아줘!",
  ui_story_5020_50201701_242_dialog_content = "흐아아아앙...",
  ui_story_5020_50201701_243_dialog_content = "사, 사장님들...",
  ui_story_5020_50201701_244_dialog_content = "요우 씨가 시식해준 신제품... 분명히 많이 팔릴 거예요...",
  ui_story_5020_50201701_245_dialog_content = "그러니까... 너무 슬퍼하지 마세요...",
  ui_story_5020_50201701_246_dialog_content = "...그것도 그렇네!",
  ui_story_5020_50201701_247_dialog_content = "요우──",
  ui_story_5020_50201701_248_dialog_content = "부디 조심히 가세요──",
  ui_story_5020_50201701_249_dialog_content = "다음에 만날 때는 소생의 체면을 깎지 마시오.",
  ui_story_5020_50201701_250_dialog_content = "아...",
  ui_story_5020_50201701_251_dialog_content = "다들...",
  ui_story_5020_50201701_252_dialog_content = "또 만나──!",
  ui_story_5020_50201701_253_dialog_content = "(요우는 배에 올랐고, 린네는 손을 흔들어 작별을 고했다.\n아메모리는 그 뒤에서 배가 멀어져가는 것을 바라보고 있었다.)",
  ui_story_5020_50201701_254_dialog_content = "(배가 수평선 너머로 사라질 때까지의 그 순간은 모두 소중하게 간직했을 것이다.)",
  ui_story_5020_50201701_255_dialog_content = "(10년 전, 한 사람의 죽음은 세 소녀를 갈라놓았다.)",
  ui_story_5020_50201701_256_dialog_content = "(그리고 10년 뒤, 또 한 사람의 죽음이 이들을 이별로 인도했다.)",
  ui_story_5020_50201701_257_dialog_content = "(연분홍빛 눈은 운도에 꽃이 피고 졌던 10년간 소녀들의 만남과 이별을 줄곧 지켜봐 왔다.)",
  ui_story_5020_50201701_258_dialog_content = "(그리고 이미 세상을 떠난 자들과 오랜 세월의 생사를 넘어,\n마침내 소녀들이 함께하는 모습도 지켜보았을 것이다.)",
  ui_story_5020_50201701_259_dialog_content = "<color=#e8d9bb>-끝-</color>"
}
return config
